function encodeRuns(values) {
  const encoded = [];
  let index = 0;
  while (index < values.length) {
    const value = values[index];
    let count = 1;
    while (index + count < values.length && values[index + count] === value) {
      count += 1;
    }
    encoded.push([count, value]);
    index += count;
  }
  return encoded;
}

function decodeRuns(encoded) {
  const decoded = [];
  for (const [count, value] of encoded) {
    for (let repeat = 0; repeat < count; repeat += 1) {
      decoded.push(value);
    }
  }
  return decoded;
}

function validateIntegers(values) {
  if (!Array.isArray(values)) {
    throw new TypeError('input must be an array of integers');
  }
  values.forEach((value, position) => {
    if (!Number.isInteger(value)) {
      throw new TypeError(`element at index ${position} is not an integer`);
    }
  });
  return values;
}

function formatRuns(encoded) {
  const parts = encoded.map(([count, value]) => `${count}x${value}`);
  return parts.join(' ');
}

function runLengthRoundTrip(values) {
  validateIntegers(values);
  const encoded = encodeRuns(values);
  return decodeRuns(encoded);
}

function report(values) {
  const encoded = encodeRuns(validateIntegers(values));
  const restored = decodeRuns(encoded);
  const intact = restored.length === values.length && restored.every((value, i) => value === values[i]);
  return `[${values.join(', ')}] -> ${formatRuns(encoded)} -> [${restored.join(', ')}] (${intact ? 'ok' : 'mismatch'})`;
}

function main() {
  const samples = [
    [5, 5, 2],
    [1, 1, 1, 4, 4, 9],
    [7],
    [],
  ];
  samples.forEach((sample) => {
    console.log(report(sample));
  });
  console.log(runLengthRoundTrip([5, 5, 2]).join(', '));
  try {
    runLengthRoundTrip([3, 2.5]);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { encodeRuns, decodeRuns, runLengthRoundTrip, report };

