const PRICE = 125;

const DENOMINATIONS = [200, 100, 50, 20, 10, 5, 2, 1];

function createRegister() {
  const stock = new Map();
  stock.set(200, 1);
  stock.set(100, 2);
  stock.set(50, 3);
  stock.set(20, 4);
  stock.set(10, 5);
  stock.set(5, 6);
  stock.set(2, 7);
  stock.set(1, 8);
  return { stock };
}

function validatePayment(payment) {
  if (!Number.isInteger(payment)) {
    throw new TypeError(`payment must be a whole number of units, got ${payment}`);
  }
  if (payment < PRICE) {
    throw new RangeError(`payment of ${payment} is below the price of ${PRICE}`);
  }
}

function dispenseChange(register, amount) {
  const dispensed = [];
  let remaining = amount;
  for (const value of DENOMINATIONS) {
    let available = register.stock.get(value);
    while (value <= remaining && available > 0) {
      dispensed.push(value);
      remaining -= value;
      available -= 1;
    }
    register.stock.set(value, available);
  }
  return { dispensed, remaining };
}

function purchase(register, payment) {
  validatePayment(payment);
  const change = payment - PRICE;
  const { dispensed, remaining } = dispenseChange(register, change);
  if (remaining > 0) {
    throw new Error(`cannot complete purchase: ${remaining} units of change unavailable`);
  }
  return dispensed;
}

function formatReceipt(payment, coins) {
  const total = coins.reduce((sum, coin) => sum + coin, 0);
  const listed = coins.length > 0 ? coins.join(', ') : 'none';
  return `paid ${payment} -> change ${total}: ${listed}`;
}

function describeStock(register) {
  const parts = DENOMINATIONS.map((value) => `${value}x${register.stock.get(value)}`);
  return parts.join(' ');
}

function main() {
  const register = createRegister();
  for (const payment of [200, 125, 500, 1000]) {
    const coins = purchase(register, payment);
    console.log(formatReceipt(payment, coins));
  }
  console.log(`remaining inventory: ${describeStock(register)}`);
  try {
    purchase(register, 100);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

