const ROMAN_TABLE = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

const ROMAN_DIGITS = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

function toRoman(value) {
  if (!Number.isInteger(value)) {
    throw new TypeError('toRoman expects an integer');
  }
  if (value < 1 || value > 3999) {
    throw new RangeError('toRoman supports 1..3999, got ' + value);
  }
  let remainder = value;
  let out = '';
  for (const [amount, symbol] of ROMAN_TABLE) {
    while (remainder >= amount) {
      out += symbol;
      remainder -= amount;
    }
  }
  return out;
}

function fromRoman(text) {
  const chars = String(text).toUpperCase().split('');
  let total = 0;
  for (let i = 0; i < chars.length; i += 1) {
    const current = ROMAN_DIGITS[chars[i]];
    if (current === undefined) {
      throw new SyntaxError('not a Roman digit: ' + chars[i]);
    }
    const next = ROMAN_DIGITS[chars[i + 1]];
    if (next !== undefined && next > current) {
      total -= current;
    } else {
      total += current;
    }
  }
  return total;
}

function roundTrip(value) {
  const roman = toRoman(value);
  return fromRoman(roman);
}

function describe(value) {
  const roman = toRoman(value);
  const restored = fromRoman(roman);
  const mark = restored === value ? 'ok' : 'MISMATCH';
  return `${value} -> ${roman} -> ${restored} [${mark}]`;
}

function main() {
  const samples = [10, 4, 9, 14, 1666, 1990, 2024, 3999];
  for (const sample of samples) {
    console.log(describe(sample));
  }
  console.log('roundTrip(10) =', roundTrip(10));
}

main();

module.exports = { toRoman, fromRoman, roundTrip, describe };

