function validateGrid(grid) {
  if (!Array.isArray(grid) || grid.length === 0) {
    throw new TypeError('grid must be a non-empty array of arrays');
  }
  const width = grid[0].length;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== width) {
      throw new TypeError('every row must be an array of the same length');
    }
    for (const cell of row) {
      if (cell !== 0 && cell !== 1) {
        throw new TypeError('cells must be 0 or 1');
      }
    }
  }
  return width;
}

function countLiveNeighbors(grid, row, col) {
  const height = grid.length;
  const width = grid[0].length;
  let total = 0;
  for (let dr = -1; dr <= 1; dr += 1) {
    for (let dc = -1; dc <= 1; dc += 1) {
      if (dr === 0 && dc === 0) {
        continue;
      }
      const r = row + dr;
      const c = col + dc;
      if (r >= 0 && r < height && c >= 0 && c < width) {
        total += grid[r][c];
      }
    }
  }
  return total;
}

function nextState(grid) {
  const width = validateGrid(grid);
  const result = [];
  for (let row = 0; row < grid.length; row += 1) {
    const newRow = new Array(width);
    for (let col = 0; col < width; col += 1) {
      const neighbors = countLiveNeighbors(grid, row, col);
      const alive = grid[row][col] === 1;
      newRow[col] = neighbors === 3 || (alive && neighbors === 2) ? 1 : 0;
    }
    result.push(newRow);
  }
  return result;
}

function formatGrid(grid) {
  return grid.map((row) => row.map((cell) => (cell === 1 ? '#' : '.')).join('')).join('\n');
}

function main() {
  const blinker = [
    [0, 1, 0],
    [0, 1, 0],
    [0, 1, 0],
  ];
  console.log('generation 0:');
  console.log(formatGrid(blinker));
  let current = blinker;
  for (let generation = 1; generation <= 2; generation += 1) {
    current = nextState(current);
    console.log(`generation ${generation}:`);
    console.log(formatGrid(current));
  }
  console.log('raw next state of the example grid:');
  console.log(JSON.stringify(nextState(blinker)));
}

main();

