function validateGrid(grid) {
  if (!Array.isArray(grid) || grid.length === 0) {
    throw new TypeError('grid must be a non-empty array of rows');
  }
  const width = grid[0].length;
  if (width === 0) {
    throw new TypeError('grid rows must not be empty');
  }
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== width) {
      throw new TypeError('grid must be rectangular');
    }
    for (const cell of row) {
      if (cell !== 0 && cell !== 1) {
        throw new RangeError('grid cells must be 0 (open) or 1 (wall)');
      }
    }
  }
  return { height: grid.length, width };
}

function shortestPath(grid) {
  const { height, width } = validateGrid(grid);
  if (grid[0][0] === 1 || grid[height - 1][width - 1] === 1) {
    return -1;
  }
  const visited = [];
  for (let r = 0; r < height; r += 1) {
    visited.push(new Array(width).fill(false));
  }
  const queue = [{ row: 0, col: 0, steps: 0 }];
  visited[0][0] = true;
  const moves = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  let head = 0;
  while (head < queue.length) {
    const current = queue[head];
    head += 1;
    if (current.row === height - 1 && current.col === width - 1) {
      return current.steps;
    }
    for (const [dr, dc] of moves) {
      const row = current.row + dr;
      const col = current.col + dc;
      if (row < 0 || row >= height || col < 0 || col >= width) {
        continue;
      }
      if (visited[row][col] || grid[row][col] === 1) {
        continue;
      }
      visited[row][col] = true;
      queue.push({ row, col, steps: current.steps + 1 });
    }
  }
  return -1;
}

function renderGrid(grid) {
  return grid.map((row) => row.map((cell) => (cell === 1 ? '#' : '.')).join('')).join('\n');
}

function report(name, grid) {
  const steps = shortestPath(grid);
  const outcome = steps < 0 ? 'blocked' : `${steps} steps`;
  console.log(`${name}: ${outcome}`);
  console.log(renderGrid(grid));
  console.log('');
}

