const MAX_WIDTH = 20;

function splitWords(text) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  const words = text.split(/\s+/).filter(function (word) {
    return word.length > 0;
  });
  for (const word of words) {
    if (word.length > MAX_WIDTH) {
      throw new RangeError('word longer than the line width: ' + word);
    }
  }
  return words;
}

function padLine(words, width) {
  if (words.length === 1) {
    return words[0] + ' '.repeat(width - words[0].length);
  }
  const letters = words.reduce(function (sum, word) {
    return sum + word.length;
  }, 0);
  const gaps = words.length - 1;
  const spaces = width - letters;
  const base = Math.floor(spaces / gaps);
  let extra = spaces % gaps;
  let line = words[0];
  for (let i = 1; i < words.length; i += 1) {
    let pad = base;
    if (extra > 0) {
      pad += 1;
      extra -= 1;
    }
    line += ' '.repeat(pad) + words[i];
  }
  return line;
}

function justifyText(text, width) {
  const limit = width === undefined ? MAX_WIDTH : width;
  const words = splitWords(text);
  const lines = [];
  let current = [];
  let length = 0;
  for (const word of words) {
    const needed = current.length === 0 ? word.length : length + 1 + word.length;
    if (needed > limit) {
      lines.push(padLine(current, limit));
      current = [word];
      length = word.length;
    } else {
      current.push(word);
      length = needed;
    }
  }
  if (current.length > 0) {
    lines.push(padLine(current, limit));
  }
  return lines;
}

function renderBlock(lines) {
  return lines.map(function (line, index) {
    return String(index + 1).padStart(2, ' ') + ' |' + line + '|';
  }).join('\n');
}

function main() {
