  console.log(JSON.stringify(justifyText(phrase)));
  const passage = 'The quick brown fox jumps over the lazy dog and keeps on running';
  console.log(renderBlock(justifyText(passage)));
  console.log(renderBlock(justifyText(passage, 30)));
}

