const DIGITS = 9;

function getRow(board, index) {
  return board[index].slice();
}

function getColumn(board, index) {
  const column = [];
  for (let r = 0; r < DIGITS; r += 1) {
    column.push(board[r][index]);
  }
  return column;
}

function getSubgrid(board, index) {
  const rowStart = Math.floor(index / 3) * 3;
  const colStart = (index % 3) * 3;
  const cells = [];
  for (let r = rowStart; r < rowStart + 3; r += 1) {
    for (let c = colStart; c < colStart + 3; c += 1) {
      cells.push(board[r][c]);
    }
  }
  return cells;
}

function isValidGroup(group) {
  if (group.length !== DIGITS) {
    return false;
  }
  const counts = new Map();
  for (const value of group) {
    if (!Number.isInteger(value) || value < 1 || value > DIGITS) {
      return false;
    }
    counts.set(value, (counts.get(value) || 0) + 1);
  }
  return counts.size === DIGITS;
}

function isValidSudoku(board) {
  if (!Array.isArray(board) || board.length !== DIGITS) {
    return false;
  }
  for (const row of board) {
    if (!Array.isArray(row) || row.length !== DIGITS) {
      return false;
    }
  }
  for (let i = 0; i < DIGITS; i += 1) {
    if (!isValidGroup(getRow(board, i))) {
      return false;
    }
    if (!isValidGroup(getColumn(board, i))) {
      return false;
    }
    if (!isValidGroup(getSubgrid(board, i))) {
      return false;
    }
  }
  return true;
}

