'use strict';

function merge(left, right) {
  const result = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i]);
      i += 1;
    } else {
      result.push(right[j]);
      j += 1;
    }
  }
  while (i < left.length) {
    result.push(left[i]);
    i += 1;
  }
  while (j < right.length) {
    result.push(right[j]);
    j += 1;
  }
  return result;
}

function mergeSort(array) {
  if (!Array.isArray(array)) {
    throw new TypeError('mergeSort expects an array of strings');
  }
  if (array.length <= 1) {
    return array.slice();
  }
  const middle = Math.floor(array.length / 2);
  const left = mergeSort(array.slice(0, middle));
  const right = mergeSort(array.slice(middle));
  return merge(left, right);
}

function parseList(text) {
  const parts = text.split(',');
  const words = [];
  for (const part of parts) {
    const word = part.trim();
    if (word.length > 0) {
      words.push(word);
    }
  }
  return words;
}

function formatList(words) {
  return words.join(', ');
}

function report(text) {
  const input = parseList(text);
  const sorted = mergeSort(input);
  return formatList(input) + ' -> ' + formatList(sorted);
}

function main() {
  const samples = [
    'cherry, apple, banana',
    'pear',
    'kiwi, fig, grape, date, apple, lemon, mango'
  ];
  for (const sample of samples) {
    console.log(report(sample));
  }
}

main();

module.exports = { mergeSort, merge, parseList, formatList, report };

