function parseQuery(address) {
  const pairs = [];
  const markIndex = address.indexOf('?');
  if (markIndex === -1) {
    return pairs;
  }
  const queryPart = address.slice(markIndex + 1);
  if (queryPart === '') {
    return pairs;
  }
  const chunks = queryPart.split('&');
  for (const chunk of chunks) {
    if (chunk === '') {
      continue;
    }
    const equalsIndex = chunk.indexOf('=');
    let rawKey = chunk;
    let rawValue = '';
    if (equalsIndex !== -1) {
      rawKey = chunk.slice(0, equalsIndex);
      rawValue = chunk.slice(equalsIndex + 1);
    }
    pairs.push([decodeComponent(rawKey), decodeComponent(rawValue)]);
  }
  return pairs;
}

function decodeComponent(text) {
  const spaced = text.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(spaced);
  } catch (error) {
    return spaced;
  }
}

function encodeComponent(text) {
  return encodeURIComponent(text).replace(/%20/g, '+');
}

function buildQuery(pairs) {
  const chunks = [];
  for (const [key, value] of pairs) {
    const encodedKey = encodeComponent(String(key));
    if (value === '' || value === null || value === undefined) {
      chunks.push(encodedKey);
      continue;
    }
    chunks.push(encodedKey + '=' + encodeComponent(String(value)));
  }
  return '?' + chunks.join('&');
}

function addPageParameter(address) {
  const pairs = parseQuery(address);
  pairs.push(['page', '2']);
  return buildQuery(pairs);
}

function report(address) {
  const rebuilt = addPageParameter(address);
  console.log(address + '  ->  ' + rebuilt);
}

report('search?q=cats');
report('http://example.com/list?name=John+Doe&sort=date');
report('/plain/path');
report('shop?tag=caf%C3%A9&empty=');

module.exports = { parseQuery, buildQuery, addPageParameter };

