function signature(word) {
  const normalized = String(word).toLowerCase();
  const letters = normalized.split('');
  letters.sort();
  return letters.join('');
}

function collectSignatures(words) {
  const buckets = new Map();
  for (const word of words) {
    const key = signature(word);
    if (!buckets.has(key)) {
      buckets.set(key, []);
    }
    buckets.get(key).push(word);
  }
  return buckets;
}

function findAnagramGroups(words) {
  if (!Array.isArray(words)) {
    throw new TypeError('findAnagramGroups expects an array of strings');
  }
  const buckets = collectSignatures(words);
  const groups = [];
  for (const group of buckets.values()) {
    if (group.length > 1) {
      groups.push(group);
    }
  }
  groups.sort((a, b) => b.length - a.length);
  return groups;
}

function formatGroup(group) {
  return group.join(', ');
}

function report(words) {
  const groups = findAnagramGroups(words);
  const lines = [];
  lines.push(`Scanned ${words.length} words, found ${groups.length} anagram group(s).`);
  groups.forEach((group, index) => {
    const label = `${index + 1}`.padStart(2, ' ');
    lines.push(`${label}. [${group.length}] ${formatGroup(group)}`);
  });
  if (groups.length === 0) {
    lines.push('No anagrams present.');
  }
  return lines.join('\n');
}

function main() {
  const simple = ['cat', 'act', 'dog'];
  console.log(JSON.stringify(findAnagramGroups(simple)));
  const dictionary = [
    'Listen', 'Silent', 'Enlist', 'Google', 'Banana',
    'Evil', 'Vile', 'Live', 'Veil', 'Stone',
    'Tones', 'Notes', 'Onset', 'Zebra', 'Elvis',
  ];
  console.log(report(dictionary));
  const isolated = ['alpha', 'beta', 'gamma'];
  console.log(report(isolated));
}

main();

module.exports = { signature, collectSignatures, findAnagramGroups, formatGroup, report };

