function buildAdjacency(edges) {
  const adjacency = new Map();
  for (const [source, destination, weight] of edges) {
    if (!adjacency.has(source)) {
      adjacency.set(source, []);
    }
    if (!adjacency.has(destination)) {
      adjacency.set(destination, []);
    }
    adjacency.get(source).push({ node: destination, weight });
  }
  return adjacency;
}

function collectNodes(adjacency, start, target) {
  const nodes = new Set(adjacency.keys());
  nodes.add(start);
  nodes.add(target);
  return nodes;
}

function pickClosest(unvisited, costs) {
  let best = null;
  let bestCost = Infinity;
  for (const node of unvisited) {
    const cost = costs.get(node);
    if (cost < bestCost) {
      bestCost = cost;
      best = node;
    }
  }
  return best;
}

function shortestPathCost(edges, start = 0, target = 4) {
  const adjacency = buildAdjacency(edges);
  const unvisited = collectNodes(adjacency, start, target);
  const costs = new Map();
  for (const node of unvisited) {
    costs.set(node, Infinity);
  }
  costs.set(start, 0);
  while (unvisited.size > 0) {
    const current = pickClosest(unvisited, costs);
    if (current === null) {
      break;
    }
    const currentCost = costs.get(current);
    for (const edge of adjacency.get(current) || []) {
      const candidate = currentCost + edge.weight;
      if (candidate < costs.get(edge.node)) {
        costs.set(edge.node, candidate);
      }
    }
    unvisited.delete(current);
  }
  return costs.get(target);
}

function formatCost(cost) {
  return cost === Infinity ? "unreachable" : String(cost);
}

function main() {
  const network = [
    [0, 1, 4],
    [0, 2, 1],
    [2, 1, 1],
    [1, 3, 5],
    [2, 3, 8],
    [3, 4, 3],
  ];
  console.log("network cost 0 -> 4:", formatCost(shortestPathCost(network)));
  const singleLink = [[0, 4, 7]];
  console.log("single link cost 0 -> 4:", formatCost(shortestPathCost(singleLink)));
  const broken = [[0, 1, 2], [1, 3, 2]];
  console.log("broken network cost 0 -> 4:", formatCost(shortestPathCost(broken)));
}

main();

