const LINES = [
  [0, 1, 2],
  [3, 4, 5],
  [6, 7, 8],
  [0, 3, 6],
  [1, 4, 7],
  [2, 5, 8],
  [0, 4, 8],
  [2, 4, 6],
];

function validateMoves(moves) {
  if (!Array.isArray(moves)) {
    throw new TypeError('moves must be an array of integers');
  }
  const seen = new Set();
  for (const move of moves) {
    if (!Number.isInteger(move) || move < 0 || move > 8) {
      throw new RangeError(`illegal move: ${move}`);
    }
    if (seen.has(move)) {
      throw new Error(`square ${move} is already occupied`);
    }
    seen.add(move);
  }
}

function findWinner(board) {
  for (const [a, b, c] of LINES) {
    const symbol = board[a];
    if (symbol !== '' && symbol === board[b] && symbol === board[c]) {
      return symbol;
    }
  }
  return null;
}

function simulate(moves) {
  validateMoves(moves);
  const board = ['', '', '', '', '', '', '', '', ''];
  let player = 'x';
  for (const move of moves) {
    board[move] = player;
    const winner = findWinner(board);
    if (winner !== null) {
      return { board, winner };
    }
    player = player === 'x' ? 'o' : 'x';
  }
  return { board, winner: null };
}

function playGame(moves) {
  const { board, winner } = simulate(moves);
  if (winner !== null) {
    return winner;
  }
  if (board.includes('')) {
    return 'unfinished';
  }
  return 'draw';
}

