  const { board } = simulate(moves);
  const cells = board.map((cell) => (cell === '' ? '.' : cell));
  const rows = [cells.slice(0, 3), cells.slice(3, 6), cells.slice(6, 9)];
  return rows.map((row) => row.join(' ')).join('\n');
}

