function sanitize(input) {
  const trimmed = String(input).replace(/[\s-]/g, "");
  if (trimmed.length === 0) {
    throw new Error("identification number must contain at least one digit");
  }
  if (!/^[0-9]+$/.test(trimmed)) {
    throw new Error(`invalid character in identification number: ${input}`);
  }
  return trimmed;
}

function luhnSum(digits) {
  let total = 0;
  for (let offset = 0; offset < digits.length; offset += 1) {
    const index = digits.length - 1 - offset;
    let value = digits.charCodeAt(index) - 48;
    if (offset % 2 === 1) {
      value *= 2;
      if (value > 9) {
        value -= 9;
      }
    }
    total += value;
  }
  return total;
}

function checkDigit(partial) {
  const padded = sanitize(partial) + "0";
  const sum = luhnSum(padded);
  const remainder = sum % 10;
  if (remainder === 0) {
    return 0;
  }
  return 10 - remainder;
}

function completeNumber(partial) {
  const body = sanitize(partial);
  return body + String(checkDigit(body));
}

function isValidLuhn(candidate) {
  const digits = sanitize(candidate);
  return luhnSum(digits) % 10 === 0;
}

function report(partial) {
  const complete = completeNumber(partial);
  const status = isValidLuhn(complete) ? "valid" : "invalid";
  return `${partial} -> ${complete} (${status})`;
}

function main() {
  const inputs = ["12345", "7992739871", "4539 1488 0343 645", "0"];
  for (const partial of inputs) {
    console.log(report(partial));
  }
  try {
    console.log(report("12a45"));
  } catch (error) {
    console.error(`error: ${error.message}`);
  }
}

main();

module.exports = { sanitize, luhnSum, checkDigit, completeNumber, isValidLuhn, report };

