const PRECEDENCE = { '+': 1, '-': 1, '*': 2, '/': 2 };

function tokenize(expression) {
  const tokens = [];
  let index = 0;
  while (index < expression.length) {
    const ch = expression[index];
    if (ch === ' ') {
      index += 1;
      continue;
    }
    if (/[0-9.]/.test(ch)) {
      let number = '';
      while (index < expression.length && /[0-9.]/.test(expression[index])) {
        number += expression[index];
        index += 1;
      }
      tokens.push(Number(number));
      continue;
    }
    if (PRECEDENCE[ch] !== undefined || ch === '(' || ch === ')') {
      tokens.push(ch);
      index += 1;
      continue;
    }
    throw new Error('Unexpected character: ' + ch);
  }
  return tokens;
}

function toPostfix(tokens) {
  const output = [];
  const operators = [];
  for (const token of tokens) {
    if (typeof token === 'number') {
      output.push(token);
    } else if (token === '(') {
      operators.push(token);
    } else if (token === ')') {
      while (operators.length > 0 && operators[operators.length - 1] !== '(') {
        output.push(operators.pop());
      }
      operators.pop();
    } else {
      while (operators.length > 0 && PRECEDENCE[operators[operators.length - 1]] >= PRECEDENCE[token]) {
        output.push(operators.pop());
      }
      operators.push(token);
    }
  }
  while (operators.length > 0) {
    output.push(operators.pop());
  }
  return output;
}

function applyOperator(operator, left, right) {
  if (operator === '+') {
    return left + right;
  }
  if (operator === '-') {
    return left - right;
  }
  if (operator === '*') {
    return left * right;
  }
  return left / right;
}

function evaluatePostfix(postfix) {
  const stack = [];
  for (const token of postfix) {
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      const right = stack.pop();
      const left = stack.pop();
      stack.push(applyOperator(token, left, right));
    }
  }
  return stack.pop();
}

function evaluate(expression) {
  return evaluatePostfix(toPostfix(tokenize(expression)));
}

const samples = ['3 + 4 * 2', '10 - 2 - 3', '(1 + 2) * (3 + 4)', '8 / 2 + 5 * 3'];
for (const sample of samples) {
  console.log(sample + ' = ' + evaluate(sample));
}

