function normalizeRange(range) {
  if (!Array.isArray(range) || range.length !== 2) {
    throw new TypeError('each range must be an array of two numbers');
  }
  const [a, b] = range;
  if (typeof a !== 'number' || typeof b !== 'number' || Number.isNaN(a) || Number.isNaN(b)) {
    throw new TypeError('range bounds must be numbers');
  }
  return a <= b ? [a, b] : [b, a];
}

function sortedRanges(ranges) {
  const cleaned = ranges.map(normalizeRange);
  cleaned.sort((left, right) => left[0] - right[0] || left[1] - right[1]);
  return cleaned;
}

function mergeRanges(ranges) {
  const sorted = sortedRanges(ranges);
  if (sorted.length === 0) {
    return [];
  }
  const merged = [];
  let [activeStart, activeEnd] = sorted[0];
  for (let i = 1; i < sorted.length; i += 1) {
    const [start, end] = sorted[i];
    if (start > activeEnd) {
      merged.push([activeStart, activeEnd]);
      activeStart = start;
      activeEnd = end;
    } else if (end > activeEnd) {
      activeEnd = end;
    }
  }
  merged.push([activeStart, activeEnd]);
  return merged;
}

function totalCoveredLength(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError('ranges must be an array');
  }
  let total = 0;
  for (const [start, end] of mergeRanges(ranges)) {
    total += end - start;
  }
  return total;
}

function formatSegment(segment) {
  const [start, end] = segment;
  return `[${start}, ${end}] -> ${end - start}`;
}

function report(label, ranges) {
  const segments = mergeRanges(ranges);
  const lines = segments.map(formatSegment);
  const total = totalCoveredLength(ranges);
  return `${label}\n  ${lines.join('\n  ')}\n  total = ${total}`;
}

function main() {
  const sample = [
    [1.1, 2.2],
    [6.5, 7.8],
    [0.5, 2.0],
    [-3.0, 4.0],
    [3.0, 9.0],
  ];
  const disjoint = [[0, 1], [2, 3], [5, 10]];
  console.log(report('overlapping ranges', sample));
  console.log(report('disjoint ranges', disjoint));
  console.log(`empty input total = ${totalCoveredLength([])}`);
}

main();

module.exports = { mergeRanges, totalCoveredLength, formatSegment, report };

