function flatten(value, out) {
  const target = out || [];
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i += 1) {
      flatten(value[i], target);
    }
    return target;
  }
  if (typeof value !== 'number' || Number.isNaN(value)) {
    throw new TypeError('flatten expects only numbers inside the nested arrays');
  }
  target.push(value);
  return target;
}

function reverseArray(items) {
  let left = 0;
  let right = items.length - 1;
  while (left < right) {
    const held = items[left];
    items[left] = items[right];
    items[right] = held;
    left += 1;
    right -= 1;
  }
  return items;
}

function flattenAndReverse(nested) {
  if (!Array.isArray(nested)) {
    throw new TypeError('flattenAndReverse expects an array as input');
  }
  const flat = flatten(nested);
  return reverseArray(flat);
}

function maxDepth(value) {
  if (!Array.isArray(value)) {
    return 0;
  }
  let deepest = 1;
  for (const child of value) {
    const childDepth = maxDepth(child) + 1;
    if (childDepth > deepest) {
      deepest = childDepth;
    }
  }
  return deepest;
}

function describe(nested) {
  const result = flattenAndReverse(nested);
  const parts = [
    `depth=${maxDepth(nested)}`,
    `count=${result.length}`,
    `result=[${result.join(', ')}]`
  ];
  return parts.join(' ');
}

const samples = [
  [1, [2, [3, [4, [5, 6]]], 7], [[8], 9]],
  [[[[42]]]],
  [10, 20, 30],
  []
];

for (const sample of samples) {
  console.log(describe(sample));
}

try {
  flattenAndReverse([1, [2, 'three']]);
} catch (err) {
  console.log(`rejected: ${err.message}`);
}

