const WEEKDAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];

function isLeapYear(year) {
  if (year % 400 === 0) {
    return true;
  }
  if (year % 100 === 0) {
    return false;
  }
  return year % 4 === 0;
}

function monthLengths(year) {
  const february = isLeapYear(year) ? 29 : 28;
  return [31, february, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
}

function firstOfJanuaryWeekday(year) {
  const month = 13;
  const shiftedYear = year - 1;
  const yearOfCentury = shiftedYear % 100;
  const century = Math.floor(shiftedYear / 100);
  const term = 1 + Math.floor(13 * (month + 1) / 5) + yearOfCentury;
  const zeller = term + Math.floor(yearOfCentury / 4) + Math.floor(century / 4) + 5 * century;
  return (zeller % 7 + 6) % 7;
}

function monthStartWeekdays(year) {
  if (!Number.isInteger(year) || year < 1) {
    throw new RangeError(`year must be a positive integer, received ${year}`);
  }
  const lengths = monthLengths(year);
  const starts = [];
  let running = firstOfJanuaryWeekday(year);
  for (let month = 0; month < 12; month += 1) {
    starts.push(running);
    running = (running + lengths[month]) % 7;
  }
  return starts;
}

function formatCalendarSummary(year) {
  const starts = monthStartWeekdays(year);
  const lengths = monthLengths(year);
  const lines = starts.map((weekday, index) => {
    const name = MONTH_NAMES[index].padEnd(9, ' ');
    return `${name} starts on ${WEEKDAY_NAMES[weekday]} and has ${lengths[index]} days`;
  });
  const leapNote = isLeapYear(year) ? 'leap year' : 'common year';
  lines.unshift(`Calendar for ${year} (${leapNote})`);
  return lines.join('\n');
}

function main() {
  const years = [2000, 1900, 2024];
  years.forEach((year) => {
    console.log(formatCalendarSummary(year));
    console.log(`weekday indices: ${monthStartWeekdays(year).join(', ')}`);
    console.log('');
  });
}

main();

module.exports = { isLeapYear, firstOfJanuaryWeekday, monthStartWeekdays, formatCalendarSummary };

