const BOLD_PATTERN = /\*\*(.+?)\*\*/g;
const EMPHASIS_PATTERN = /\*(.+?)\*/g;
const HEADER_PATTERN = /^(#{1,6}) +(.*)$/;

function renderInline(text) {
  const bolded = text.replace(BOLD_PATTERN, '<strong>$1</strong>');
  return bolded.replace(EMPHASIS_PATTERN, '<em>$1</em>');
}

function renderHeader(line) {
  const match = HEADER_PATTERN.exec(line);
  if (match === null) {
    return null;
  }
  const level = match[1].length;
  const content = renderInline(match[2].trim());
  return `<h${level}>${content}</h${level}>`;
}

function renderParagraph(lines) {
  const text = lines.map(renderInline).join(' ');
  return `<p>${text}</p>`;
}

function render(markdown) {
  if (typeof markdown !== 'string') {
    throw new TypeError('render expects a markdown string');
  }
  const lines = markdown.split(/\r?\n/);
  const blocks = [];
  let pending = [];
  const flush = () => {
    if (pending.length > 0) {
      blocks.push(renderParagraph(pending));
      pending = [];
    }
  };
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (line === '') {
      flush();
      continue;
    }
    const header = renderHeader(line);
    if (header !== null) {
      flush();
      blocks.push(header);
      continue;
    }
    pending.push(line);
  }
  flush();
  return blocks.join('');
}

function prettyPrint(html) {
  return html.replace(/></g, '>\n<');
}

const document = [
  '# Markdown to HTML',
  '',
  'This paragraph spans two source lines',
  'and mixes **bold** with *emphasis*.',
  '',
  '### A smaller heading with **weight**',
  '',
  'A final *short* paragraph.',
].join('\n');

const html = render(document);
console.log(prettyPrint(html));

