class LRUCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError(`capacity must be a positive integer, got ${capacity}`);
    }
    this.capacity = capacity;
    this.store = new Map();
  }

  get(key) {
    if (!this.store.has(key)) {
      return -1;
    }
    const value = this.store.get(key);
    this.store.delete(key);
    this.store.set(key, value);
    return value;
  }

  put(key, value) {
    if (this.store.has(key)) {
      this.store.delete(key);
    } else if (this.store.size >= this.capacity) {
      const oldest = this.store.keys().next().value;
      this.store.delete(oldest);
    }
    this.store.set(key, value);
  }
}

function parseOperation(operation) {
  if (!Array.isArray(operation) || operation.length === 0) {
    throw new TypeError('each operation must be a non-empty list');
  }
  const name = String(operation[0]).toLowerCase();
  const args = operation.slice(1).map(Number);
  if (args.some((n) => !Number.isFinite(n))) {
    throw new TypeError(`operation ${name} has non-numeric arguments`);
  }
  if (name === 'put' && args.length !== 2) {
    throw new TypeError('put requires a key and a value');
  }
  if (name === 'get' && args.length !== 1) {
    throw new TypeError('get requires a key');
  }
  if (name !== 'put' && name !== 'get') {
    throw new TypeError(`unknown operation: ${operation[0]}`);
  }
  return { name, args };
}

function simulate(operations, capacity) {
  const cache = new LRUCache(capacity);
  const results = [];
  for (const operation of operations) {
    const { name, args } = parseOperation(operation);
    if (name === 'put') {
      cache.put(args[0], args[1]);
    } else {
      results.push(cache.get(args[0]));
    }
  }
  return results;
}

function formatResults(results) {
  return results.length === 0 ? '(no get operations)' : results.join(', ');
}

function main() {
  const script = [
    ['put', 1, 1],
    ['put', 2, 2],
    ['get', 1],
    ['put', 3, 3],
    ['get', 2],
    ['put', 4, 4],
    ['get', 1],
    ['get', 3],
    ['get', 4],
  ];
  console.log(formatResults(simulate(script, 2)));
  console.log(formatResults(simulate([['get', 7], ['put', 7, 9], ['get', 7]], 1)));
}

main();

