function validateEdges(edges) {
  if (!Array.isArray(edges)) {
    throw new TypeError('edges must be an array of [source, destination] pairs');
  }
  edges.forEach((edge, index) => {
    if (!Array.isArray(edge) || edge.length !== 2) {
      throw new TypeError(`edge at index ${index} must be a pair`);
    }
    const [from, to] = edge;
    if (typeof from !== 'number' || typeof to !== 'number') {
      throw new TypeError(`edge at index ${index} must contain numbers`);
    }
  });
  return edges;
}

function buildGraph(edges) {
  const adjacency = new Map();
  const incoming = new Map();
  const touch = (node) => {
    if (!adjacency.has(node)) {
      adjacency.set(node, []);
      incoming.set(node, 0);
    }
  };
  for (const [from, to] of edges) {
    touch(from);
    touch(to);
    adjacency.get(from).push(to);
    incoming.set(to, incoming.get(to) + 1);
  }
  return { adjacency, incoming };
}

function sort(edges) {
  validateEdges(edges);
  const { adjacency, incoming } = buildGraph(edges);
  const queue = [];
  for (const [node, count] of incoming) {
    if (count === 0) {
      queue.push(node);
    }
  }
  const ordered = [];
  while (queue.length > 0) {
    const node = queue.shift();
    ordered.push(node);
    for (const neighbour of adjacency.get(node)) {
      const remaining = incoming.get(neighbour) - 1;
      incoming.set(neighbour, remaining);
      if (remaining === 0) {
        queue.push(neighbour);
      }
    }
  }
  if (ordered.length !== adjacency.size) {
    return [];
  }
  return ordered;
}

function describeOrder(edges) {
  const ordered = sort(edges);
  if (ordered.length === 0 && edges.length > 0) {
    return 'cycle detected: no topological order exists';
  }
  return `order: ${ordered.join(' -> ')}`;
}

const acyclic = [[5, 2], [5, 0], [4, 0], [4, 1], [2, 3], [3, 1]];
const cyclic = [[0, 1], [1, 2], [2, 0]];
console.log(describeOrder(acyclic));
console.log(describeOrder(cyclic));

module.exports = { sort, buildGraph, validateEdges, describeOrder };

