const PRIME = 31;

function hashString(text) {
  let total = 0;
  for (let i = 0; i < text.length; i += 1) {
    total += text.charCodeAt(i) * PRIME;
  }
  return total;
}

function ringPosition(text) {
  return hashString(text) % 1000;
}

function buildRing(nodes) {
  const ring = [];
  for (const name of nodes) {
    ring.push({ name: name, slot: ringPosition(name) });
  }
  ring.sort((a, b) => a.slot - b.slot || a.name.localeCompare(b.name));
  return ring;
}

function findOwner(ring, slot) {
  for (const entry of ring) {
    if (entry.slot >= slot) {
      return entry.name;
    }
  }
  return ring[0].name;
}

function balance(nodes, keys) {
  if (!Array.isArray(nodes) || nodes.length === 0) {
    throw new Error('at least one node is required');
  }
  const ring = buildRing(nodes);
  const assignments = [];
  for (const key of keys) {
    const slot = ringPosition(key);
    assignments.push([key, findOwner(ring, slot)]);
  }
  return assignments;
}

function countPerNode(nodes, assignments) {
  const tally = new Map();
  for (const name of nodes) {
    tally.set(name, 0);
  }
  for (const [, owner] of assignments) {
    tally.set(owner, tally.get(owner) + 1);
  }
  return tally;
}

function formatReport(nodes, keys) {
  const assignments = balance(nodes, keys);
  const lines = assignments.map(([key, owner]) => `${key} (slot ${ringPosition(key)}) -> ${owner}`);
  const tally = countPerNode(nodes, assignments);
  for (const node of nodes) {
    lines.push(`${node} holds ${tally.get(node)} key(s) at slot ${ringPosition(node)}`);
  }
  return lines.join('\n');
}

function main() {
  const nodes = ['alpha', 'bravo', 'charlie', 'delta'];
  const keys = ['user:1001', 'user:1002', 'session:abc', 'cart:xyz', 'image:007'];
  console.log(formatReport(nodes, keys));
}

main();

