const END = '\u0000';

function insert(root, word) {
  let node = root;
  for (const ch of word) {
    if (!node[ch]) {
      node[ch] = {};
    }
    node = node[ch];
  }
  node[END] = true;
}

function buildTrie(words) {
  const root = {};
  for (const word of words) {
    insert(root, word);
  }
  return root;
}

function descend(root, prefix) {
  let node = root;
  for (const ch of prefix) {
    node = node[ch];
    if (!node) {
      return null;
    }
  }
  return node;
}

function collect(node, prefix, out) {
  if (node[END]) {
    out.push(prefix);
  }
  const branches = Object.keys(node).filter((key) => key !== END).sort();
  for (const ch of branches) {
    collect(node[ch], prefix + ch, out);
  }
  return out;
}

function normalize(words) {
  const cleaned = [];
  for (const word of words) {
    const text = String(word).trim().toLowerCase();
    if (text.length > 0) {
      cleaned.push(text);
    }
  }
  return cleaned;
}

function complete(words, prefix) {
  const target = String(prefix).trim().toLowerCase();
  const root = buildTrie(normalize(words));
  const node = descend(root, target);
  if (node === null) {
    return [];
  }
  return collect(node, target, []).sort();
}

function report(words, prefix) {
  const matches = complete(words, prefix);
  const label = prefix === '' ? '(all)' : prefix;
  if (matches.length === 0) {
    return `${label}: no matches`;
  }
  return `${label}: ${matches.join(', ')}`;
}

const dictionary = ['cat', 'car', 'cart', 'care', 'dog', 'dot', 'Camera ', 'do'];

for (const query of ['ca', 'car', 'do', 'z', '']) {
  console.log(report(dictionary, query));
}

module.exports = { complete, buildTrie, report };

