function lcsTable(original, updated) {
  const rows = original.length + 1;
  const cols = updated.length + 1;
  const table = [];
  for (let i = 0; i < rows; i += 1) {
    table.push(new Array(cols).fill(0));
  }
  for (let i = 1; i < rows; i += 1) {
    for (let j = 1; j < cols; j += 1) {
      if (original[i - 1] === updated[j - 1]) {
        table[i][j] = table[i - 1][j - 1] + 1;
      } else {
        table[i][j] = Math.max(table[i - 1][j], table[i][j - 1]);
      }
    }
  }
  return table;
}

function compare(original, updated) {
  if (!Array.isArray(original) || !Array.isArray(updated)) {
    throw new TypeError('compare expects two arrays of strings');
  }
  const table = lcsTable(original, updated);
  const changes = [];
  let i = original.length;
  let j = updated.length;
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && original[i - 1] === updated[j - 1]) {
      changes.push(['keep', original[i - 1]]);
      i -= 1;
      j -= 1;
    } else if (j > 0 && (i === 0 || table[i][j - 1] >= table[i - 1][j])) {
      changes.push(['add', updated[j - 1]]);
      j -= 1;
    } else {
      changes.push(['remove', original[i - 1]]);
      i -= 1;
    }
  }
  changes.reverse();
  return changes;
}

const MARKERS = { add: '+', remove: '-', keep: ' ' };

function formatDiff(changes) {
  return changes.map(([op, line]) => `${MARKERS[op]} ${line}`).join('\n');
}

function summarize(changes) {
  const counts = { add: 0, remove: 0, keep: 0 };
  for (const [op] of changes) {
    counts[op] += 1;
  }
  return `${counts.add} added, ${counts.remove} removed, ${counts.keep} unchanged`;
}

function main() {
  const original = ['the quick', 'brown fox', 'jumps over', 'the lazy dog'];
  const updated = ['the quick', 'red fox', 'jumps over', 'a lazy dog', 'again'];
  const changes = compare(original, updated);
  console.log(formatDiff(changes));
  console.log(summarize(changes));
}

main();

