const BASE_RATING = 1200;
const K_FACTOR = 32;

function expectedScore(ratingA, ratingB) {
  const exponent = (ratingB - ratingA) / 400;
  return 1 / (1 + Math.pow(10, exponent));
}

function validateMatch(match, index) {
  if (!Array.isArray(match) || match.length !== 2) {
    throw new Error(`match ${index} must be a pair of player names`);
  }
  const [winner, loser] = match;
  if (typeof winner !== 'string' || typeof loser !== 'string') {
    throw new Error(`match ${index} must contain player names as strings`);
  }
  if (winner === loser) {
    throw new Error(`match ${index} lists ${winner} as both winner and loser`);
  }
  return [winner, loser];
}

function ratingOf(ratings, player) {
  if (!Object.prototype.hasOwnProperty.call(ratings, player)) {
    ratings[player] = BASE_RATING;
  }
  return ratings[player];
}

function rank(matches) {
  const ratings = {};
  matches.forEach((match, index) => {
    const [winner, loser] = validateMatch(match, index);
    const winnerRating = ratingOf(ratings, winner);
    const loserRating = ratingOf(ratings, loser);
    const winnerExpected = expectedScore(winnerRating, loserRating);
    const loserExpected = expectedScore(loserRating, winnerRating);
    ratings[winner] = winnerRating + K_FACTOR * (1 - winnerExpected);
    ratings[loser] = loserRating + K_FACTOR * (0 - loserExpected);
  });
  const table = Object.keys(ratings).map((player) => [player, Math.round(ratings[player])]);
  table.sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]));
  return table;
}

function formatTable(table) {
  const width = table.reduce((longest, row) => Math.max(longest, row[0].length), 0);
  return table
    .map((row, index) => {
      const place = String(index + 1).padStart(2, ' ');
      const name = row[0].padEnd(width, ' ');
      return `${place}. ${name}  ${row[1]}`;
    })
    .join('\n');
}

function main() {
  const matches = [
    ['Alice', 'Bob'],
    ['Alice', 'Carol'],
    ['Bob', 'Carol'],
    ['Carol', 'Dave'],
    ['Dave', 'Bob'],
    ['Alice', 'Dave'],
    ['Carol', 'Bob'],
  ];
  const standings = rank(matches);
  console.log(formatTable(standings));
  const leader = standings[0];
  console.log(`Champion: ${leader[0]} with ${leader[1]} points`);
}

main();

