const OPERATORS = '+-*/^%';
const PUNCTUATION = '(),';

function isDigitChar(ch) {
  return ch >= '0' && ch <= '9';
}

function isNumberStart(ch) {
  return isDigitChar(ch) || ch === '.';
}

function isNameChar(ch) {
  const lower = ch.toLowerCase();
  return (lower >= 'a' && lower <= 'z') || ch === '_';
}

function readNumber(expression, start) {
  let end = start;
  let dots = 0;
  while (end < expression.length && isNumberStart(expression[end])) {
    if (expression[end] === '.') {
      dots += 1;
    }
    end += 1;
  }
  if (dots > 1) {
    throw new SyntaxError('Malformed number at position ' + start);
  }
  return expression.slice(start, end);
}

function readName(expression, start) {
  let end = start;
  while (end < expression.length && (isNameChar(expression[end]) || isDigitChar(expression[end]))) {
    end += 1;
  }
  return expression.slice(start, end);
}

function tokenize(expression) {
  if (typeof expression !== 'string') {
    throw new TypeError('tokenize expects a string');
  }
  const tokens = [];
  let i = 0;
  while (i < expression.length) {
    const ch = expression[i];
    if (/\s/.test(ch)) {
      i += 1;
    } else if (isNumberStart(ch)) {
      const number = readNumber(expression, i);
      tokens.push(number);
      i += number.length;
    } else if (isNameChar(ch)) {
      const name = readName(expression, i);
      tokens.push(name);
      i += name.length;
    } else if (OPERATORS.includes(ch) || PUNCTUATION.includes(ch)) {
      tokens.push(ch);
      i += 1;
    } else {
      throw new SyntaxError('Unexpected character "' + ch + '" at position ' + i);
    }
  }
  return tokens;
}

function describe(expression) {
  const tokens = tokenize(expression);
  return tokens.length + ' tokens: ' + tokens.join(' | ');
}

const samples = ['(3 + x)', 'max(2.5, alpha) * -beta^2', '12.5%4 / n_1'];
for (const sample of samples) {
  console.log(sample.padEnd(28) + '=> ' + describe(sample));
}

try {
