  const hw = node.w / 2;
  const hh = node.h / 2;
  node.children = [
    makeNode(node.x, node.y, hw, hh),
    makeNode(node.x + hw, node.y, hw, hh),
    makeNode(node.x, node.y + hh, hw, hh),
    makeNode(node.x + hw, node.y + hh, hw, hh)
  ];
  const stored = node.points;
  node.points = [];
  for (const point of stored) {
