const EPSILON = 1e-12;

function validatePoint(point) {
  if (!Array.isArray(point) || point.length !== 2) {
    throw new TypeError('point must be a list of two numbers');
  }
  const [x, y] = point;
  if (typeof x !== 'number' || typeof y !== 'number') {
    throw new TypeError('point coordinates must be numbers');
  }
  if (!Number.isFinite(x) || !Number.isFinite(y)) {
    throw new RangeError('point coordinates must be finite');
  }
}

function validatePolygon(polygon) {
  if (!Array.isArray(polygon) || polygon.length < 3) {
    throw new TypeError('polygon must have at least three vertices');
  }
  for (const vertex of polygon) {
    validatePoint(vertex);
  }
}

function crossesRay(point, start, end) {
  const [px, py] = point;
  let [ax, ay] = start;
  let [bx, by] = end;
  if (ay > by) {
    [ax, ay, bx, by] = [bx, by, ax, ay];
  }
  if (Math.abs(by - ay) < EPSILON) {
    return false;
  }
  if (py < ay || py >= by) {
    return false;
  }
  const xAtRay = ax + ((py - ay) * (bx - ax)) / (by - ay);
  return xAtRay > px;
}

function test(point, polygon) {
  validatePoint(point);
  validatePolygon(polygon);
  let crossings = 0;
  for (let i = 0; i < polygon.length; i += 1) {
    const start = polygon[i];
    const end = polygon[(i + 1) % polygon.length];
    if (crossesRay(point, start, end)) {
      crossings += 1;
    }
  }
  return crossings % 2 === 1;
}

function describe(name, point, polygon) {
  const verdict = test(point, polygon) ? 'inside' : 'outside';
  return `${name} ${JSON.stringify(point)} is ${verdict}`;
}

