const BASE = 256;
const PRIME = 101;

function computeHash(str, length) {
  let hash = 0;
  for (let i = 0; i < length; i += 1) {
    hash = (hash * BASE + str.charCodeAt(i)) % PRIME;
  }
  return hash;
}

function highestPower(length) {
  let power = 1;
  for (let i = 1; i < length; i += 1) {
    power = (power * BASE) % PRIME;
  }
  return power;
}

function regionMatches(text, pattern, start) {
  for (let i = 0; i < pattern.length; i += 1) {
    if (text.charCodeAt(start + i) !== pattern.charCodeAt(i)) {
      return false;
    }
  }
  return true;
}

function search(text, pattern) {
  const matches = [];
  const n = text.length;
  const m = pattern.length;
  if (m === 0 || m > n) {
    return matches;
  }
  const patternHash = computeHash(pattern, m);
  const leadMultiplier = highestPower(m);
  let windowHash = computeHash(text, m);
  for (let start = 0; start <= n - m; start += 1) {
    if (windowHash === patternHash && regionMatches(text, pattern, start)) {
      matches.push(start);
    }
    if (start < n - m) {
      const exiting = text.charCodeAt(start) * leadMultiplier;
      const entering = text.charCodeAt(start + m);
      windowHash = ((windowHash - exiting) * BASE + entering) % PRIME;
      if (windowHash < 0) {
        windowHash += PRIME;
      }
    }
  }
  return matches;
}

function formatReport(text, pattern) {
  const positions = search(text, pattern);
  const label = `"${pattern}" in "${text}"`;
  if (positions.length === 0) {
    return `${label}: no matches`;
  }
  return `${label}: found at ${positions.join(", ")}`;
}

function main() {
  const text = "abracadabra, abracadabra!";
  const patterns = ["abra", "cad", "dabra", "zebra", ""];
  for (const pattern of patterns) {
    console.log(formatReport(text, pattern));
  }
  const total = search(text, "a").length;
  console.log(`letter "a" occurs ${total} times`);
}

main();

