function movingAverage(prices, window) {
  const averages = new Array(prices.length).fill(null);
  let sum = 0;
  for (let i = 0; i < prices.length; i += 1) {
    sum += prices[i];
    if (i >= window) {
      sum -= prices[i - window];
    }
    if (i >= window - 1) {
      averages[i] = sum / window;
    }
  }
  return averages;
}

function validateWindows(prices, short, long) {
  if (!Array.isArray(prices)) {
    throw new TypeError('prices must be an array of numbers');
  }
  if (!Number.isInteger(short) || !Number.isInteger(long)) {
    throw new TypeError('window sizes must be integers');
  }
  if (short < 1 || long < 1) {
    throw new RangeError('window sizes must be positive');
  }
  if (short >= long) {
    throw new RangeError('short window must be smaller than long window');
  }
}

function analyze(prices, short, long) {
  validateWindows(prices, short, long);
  const shortAvg = movingAverage(prices, short);
  const longAvg = movingAverage(prices, long);
  const signals = [];
  let previous = null;
  for (let day = 0; day < prices.length; day += 1) {
    if (shortAvg[day] === null || longAvg[day] === null) {
      continue;
    }
    const current = Math.sign(shortAvg[day] - longAvg[day]);
    if (previous !== null && current !== 0 && current !== previous) {
      signals.push([day, current > 0 ? 'buy' : 'sell']);
    }
    if (current !== 0) {
      previous = current;
    }
  }
  return signals;
}

function formatSignals(prices, signals) {
  if (signals.length === 0) {
    return 'no crossovers detected';
  }
  const lines = signals.map(([day, kind]) => {
    const price = prices[day].toFixed(2);
    return `day ${day}: ${kind.toUpperCase()} at ${price}`;
  });
  return lines.join('\n');
}

function main() {
  const prices = [10, 11, 12, 13, 12, 11, 9, 8, 9, 11, 14, 16, 15, 13, 12];
  const signals = analyze(prices, 3, 5);
  console.log(formatSignals(prices, signals));
  console.log(JSON.stringify(signals));
  const flat = new Array(8).fill(5);
  console.log(formatSignals(flat, analyze(flat, 2, 4)));
}

main();

module.exports = { analyze, movingAverage, formatSignals };

