function parseAddress(address) {
  if (typeof address !== 'string') {
    throw new TypeError('address must be a string');
  }
  const parts = address.split('.');
  if (parts.length !== 4) {
    throw new Error(`malformed address: ${address}`);
  }
  let value = 0;
  for (const part of parts) {
    if (!/^\d{1,3}$/.test(part)) {
      throw new Error(`invalid octet "${part}" in ${address}`);
    }
    const octet = Number(part);
    if (octet > 255) {
      throw new RangeError(`octet out of range: ${part}`);
    }
    value = ((value << 8) | octet) >>> 0;
  }
  return value;
}

function formatAddress(value) {
  const octets = [];
  for (let shift = 24; shift >= 0; shift -= 8) {
    octets.push((value >>> shift) & 0xFF);
  }
  return octets.join('.');
}

function maskFromPrefix(prefix) {
  if (!Number.isInteger(prefix) || prefix < 0 || prefix > 32) {
    throw new RangeError(`prefix must be an integer in 0..32, got ${prefix}`);
  }
  if (prefix === 0) {
    return 0;
  }
  return (0xFFFFFFFF << (32 - prefix)) >>> 0;
}

function subnet(address, prefix) {
  const value = parseAddress(address);
  const mask = maskFromPrefix(prefix);
  const network = (value & mask) >>> 0;
  const broadcast = (network | (~mask >>> 0)) >>> 0;
  return [formatAddress(network), formatAddress(broadcast)];
}

function describe(address, prefix) {
  const [network, broadcast] = subnet(address, prefix);
  const hostBits = 32 - prefix;
  const total = Math.pow(2, hostBits);
  const usable = hostBits > 1 ? total - 2 : total;
  return `${address}/${prefix} -> network ${network}, broadcast ${broadcast}, mask ${formatAddress(maskFromPrefix(prefix))}, usable hosts ${usable}`;
}

function main() {
  const cases = [
    ['192.168.1.130', 26],
    ['10.0.55.7', 16],
    ['172.16.34.200', 20],
    ['8.8.8.8', 32],
    ['203.0.113.45', 0],
  ];
  for (const [address, prefix] of cases) {
    console.log(describe(address, prefix));
  }
  try {
    subnet('192.168.1.300', 24);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

