  const [network, broadcast] = subnet(address, prefix)
  const hostBits = 32 - prefix
  const total = Math.pow(2, hostBits)
  const usable = hostBits > 1 ? total - 2 : total
  return `${address}/${prefix} -> network ${network}, broadcast ${broadcast}, mask ${formatAddress(maskFromPrefix(prefix))}, usable hosts ${usable}`
}

