function buildGraph(pages, links) {
  const outgoing = new Map();
  const incoming = new Map();
  for (const page of pages) {
    outgoing.set(page, []);
    incoming.set(page, []);
  }
  for (const [from, to] of links) {
    if (!outgoing.has(from) || !outgoing.has(to)) {
      throw new Error(`link references unknown page: ${from} -> ${to}`);
    }
    outgoing.get(from).push(to);
    incoming.get(to).push(from);
  }
  return { outgoing, incoming };
}

function score(pages, links) {
  const unique = new Set(pages);
  if (unique.size !== pages.length) {
    throw new Error('page names must be unique');
  }
  const damping = 0.85;
  const baseline = 1 - damping;
  const { outgoing, incoming } = buildGraph(pages, links);
  let current = new Map();
  for (const page of pages) {
    current.set(page, 1);
  }
  for (let round = 0; round < 10; round += 1) {
    const next = new Map();
    for (const page of pages) {
      let inflow = 0;
      for (const source of incoming.get(page)) {
        inflow += current.get(source) / outgoing.get(source).length;
      }
      next.set(page, baseline + damping * inflow);
    }
    current = next;
  }
  return pages.map((page) => [page, Math.round(current.get(page) * 1000) / 1000]);
}

