function tokenize(text) {
  const words = [];
  for (const piece of String(text).split(/\s+/)) {
    if (piece.length > 0) {
      words.push(piece);
    }
  }
  return words;
}

function wrap(text, limit) {
  const max = Math.floor(limit);
  if (!Number.isFinite(max) || max < 1) {
    throw new RangeError('limit must be a positive integer');
  }
  const words = tokenize(text);
  const lines = [];
  let current = '';
  for (const word of words) {
    if (current.length === 0) {
      current = word;
    } else if (current.length + 1 + word.length <= max) {
      current += ' ' + word;
    } else {
      lines.push(current);
      current = word;
    }
    if (current.length > max) {
      lines.push(current);
      current = '';
    }
  }
  if (current.length > 0) {
    lines.push(current);
  }
  return lines;
}

function longestLine(lines) {
  let longest = 0;
  for (const line of lines) {
    longest = Math.max(longest, line.length);
  }
  return longest;
}

function report(text, limit) {
  const lines = wrap(text, limit);
  const header = 'limit ' + limit + ': ' + lines.length + ' line(s), widest ' + longestLine(lines);
  const body = lines.map((line, index) => {
    const number = String(index + 1).padStart(2, ' ');
    return number + ' | ' + line;
  });
  return [header].concat(body).join('\n');
}

function main() {
  const fox = 'the quick brown fox';
  console.log(report(fox, 10));
  console.log(report('In the beginning the Universe was created. This has made a lot of people very angry.', 20));
