const MAX_WIDTH = 20;

function validate(frequencies) {
  if (!Array.isArray(frequencies)) {
    throw new TypeError('frequencies must be an array');
  }
  frequencies.forEach(function (value, index) {
    if (!Number.isInteger(value) || value < 0) {
      throw new RangeError('frequencies[' + index + '] must be a non negative integer');
    }
  });
  return frequencies;
}

function maxFrequency(frequencies) {
  let largest = 0;
  for (const value of frequencies) {
    if (value > largest) {
      largest = value;
    }
  }
  return largest;
}

function barLength(value, largest) {
  if (largest === 0) {
    return 0;
  }
  const scaled = (value * MAX_WIDTH) / largest;
  return Math.round(scaled);
}

function chart(frequencies) {
  validate(frequencies);
  const largest = maxFrequency(frequencies);
  return frequencies.map(function (value) {
    const width = barLength(value, largest);
    return '#'.repeat(width);
  });
}

function labelWidth(frequencies) {
  let widest = 0;
  for (const value of frequencies) {
    const digits = String(value).length;
    if (digits > widest) {
      widest = digits;
    }
  }
  return widest;
}

function report(frequencies) {
  const bars = chart(frequencies);
  const pad = labelWidth(frequencies);
  const lines = [];
  bars.forEach(function (bar, index) {
    const label = String(frequencies[index]).padStart(pad, ' ');
    lines.push(label + ' | ' + bar);
  });
  return lines.join('\n');
}

function main() {
  console.log(JSON.stringify(chart([10, 5])));
  console.log(report([5, 3, 9, 0, 12]));
  console.log(JSON.stringify(chart([0, 0, 0])));
  console.log(report([1, 2, 3, 100]));
}

main();

module.exports = { chart, report, barLength, maxFrequency };

