const VOWELS = 'aeiou';

function endsWithSibilant(word) {
  const sibilantSuffixes = ['s', 'x', 'z', 'ch', 'sh'];
  return sibilantSuffixes.some((suffix) => word.endsWith(suffix));
}

function endsWithConsonantY(word) {
  if (!word.endsWith('y') || word.length < 2) {
    return false;
  }
  const beforeY = word[word.length - 2];
  return !VOWELS.includes(beforeY);
}

function pluralizeWord(word) {
  if (endsWithSibilant(word)) {
    return word + 'es';
  }
  if (endsWithConsonantY(word)) {
    return word.slice(0, -1) + 'ies';
  }
  return word + 's';
}

function validateWords(words) {
  if (!Array.isArray(words)) {
    throw new TypeError('pluralize expects an array of strings');
  }
  words.forEach((word, index) => {
    if (typeof word !== 'string') {
      throw new TypeError(`entry ${index} is not a string`);
    }
    if (word !== word.toLowerCase()) {
      throw new RangeError(`entry ${index} ("${word}") must be lowercase`);
    }
    if (word.length === 0) {
      throw new RangeError(`entry ${index} is empty`);
    }
  });
}

function pluralize(words) {
  validateWords(words);
  return words.map(pluralizeWord);
}

function formatReport(words) {
  const plurals = pluralize(words);
  const widest = words.reduce((max, word) => Math.max(max, word.length), 0);
  const lines = words.map((word, index) => {
    const padded = word.padEnd(widest, ' ');
    return `${padded} -> ${plurals[index]}`;
  });
  return lines.join('\n');
}

function main() {
  const sample = ['box', 'cherry', 'bus', 'church', 'dish', 'day', 'cat', 'quiz', 'key'];
  console.log(formatReport(sample));
  const singleWords = ['box', 'cherry'];
  console.log(pluralize(singleWords).join(' and '));
  try {
    pluralize(['Box']);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { pluralize, pluralizeWord, formatReport };

