function parseDigits(digits) {
  if (typeof digits !== 'string') {
    throw new TypeError('barcode must be supplied as a string');
  }
  const trimmed = digits.trim();
  if (trimmed.length !== 12) {
    throw new RangeError(`expected 12 digits, received ${trimmed.length}`);
  }
  if (!/^[0-9]{12}$/.test(trimmed)) {
    throw new RangeError(`barcode contains non-numeric characters: ${trimmed}`);
  }
  return Array.from(trimmed, (character) => Number(character));
}

function checksum(digits) {
  const values = parseDigits(digits);
  let total = 0;
  for (let index = 0; index < values.length; index += 1) {
    const position = index + 1;
    const weight = position % 2 === 0 ? 3 : 1;
    total += values[index] * weight;
  }
  const remainder = total % 10;
  const check = 10 - remainder;
  return check === 10 ? 0 : check;
}

function fullBarcode(digits) {
  const body = parseDigits(digits).join('');
  return body + String(checksum(body));
}

function isValidBarcode(thirteenDigits) {
  if (typeof thirteenDigits !== 'string' || !/^[0-9]{13}$/.test(thirteenDigits)) {
    return false;
  }
  const body = thirteenDigits.slice(0, 12);
  const given = Number(thirteenDigits.slice(12));
  return checksum(body) === given;
}

function formatBarcode(thirteenDigits) {
  if (!isValidBarcode(thirteenDigits)) {
    throw new RangeError(`not a valid barcode: ${thirteenDigits}`);
  }
  const system = thirteenDigits.slice(0, 1);
  const manufacturer = thirteenDigits.slice(1, 6);
  const product = thirteenDigits.slice(6, 11);
  const check = thirteenDigits.slice(12);
  return `${system} ${manufacturer} ${product} ${check}`;
}

function report(bodies) {
  const lines = bodies.map((body) => {
    const code = fullBarcode(body);
    return `${body} -> check ${checksum(body)} -> ${formatBarcode(code)}`;
