function parseFormula(formula) {
  if (typeof formula !== 'string') {
    throw new TypeError('formula must be a string');
  }
  const trimmed = formula.trim();
  if (trimmed.length === 0) {
    throw new Error('formula must not be empty');
  }
  const pattern = /([A-Z][a-z]*)(\d*)/g;
  const tokens = [];
  let cursor = 0;
  let match = pattern.exec(trimmed);
  while (match !== null) {
    if (match.index !== cursor) {
      throw new Error(`unexpected character "${trimmed[cursor]}" at index ${cursor}`);
    }
    const symbol = match[1];
    const digits = match[2];
    const count = digits === '' ? 1 : Number.parseInt(digits, 10);
    if (count === 0) {
      throw new Error(`quantity for ${symbol} must be at least one`);
    }
    tokens.push({ symbol: symbol, count: count });
    cursor = pattern.lastIndex;
    match = pattern.exec(trimmed);
  }
  if (cursor !== trimmed.length) {
    throw new Error(`unexpected character "${trimmed[cursor]}" at index ${cursor}`);
  }
  return tokens;
}

function tally(formula) {
  const tokens = parseFormula(formula);
  const totals = new Map();
  for (const token of tokens) {
    const running = totals.has(token.symbol) ? totals.get(token.symbol) : 0;
    totals.set(token.symbol, running + token.count);
  }
  return Array.from(totals.entries(), function (entry) {
    return [entry[0], entry[1]];
  });
}

function totalAtoms(pairs) {
  let sum = 0;
  for (const pair of pairs) {
    sum += pair[1];
  }
  return sum;
}

function formatTally(pairs) {
  const parts = pairs.map(function (pair) {
    return `${pair[0]} ${pair[1]}`;
  });
  return parts.join(', ');
}

