const BOMB = '*';
const EMPTY = '-';

function validateGrid(grid) {
  if (!Array.isArray(grid)) {
    throw new TypeError('grid must be a list of lists of strings');
  }
  const width = grid.length > 0 ? grid[0].length : 0;
  for (const row of grid) {
    if (!Array.isArray(row)) {
      throw new TypeError('every row must be a list of strings');
    }
    if (row.length !== width) {
      throw new Error('grid must be rectangular');
    }
    for (const cell of row) {
      if (cell !== BOMB && cell !== EMPTY) {
        throw new Error(`unexpected cell value: ${JSON.stringify(cell)}`);
      }
    }
  }
  return width;
}

function countAdjacentBombs(grid, row, col) {
  let count = 0;
  for (let dr = -1; dr <= 1; dr += 1) {
    for (let dc = -1; dc <= 1; dc += 1) {
      if (dr === 0 && dc === 0) {
        continue;
      }
      const r = row + dr;
      const c = col + dc;
      const inside = r >= 0 && r < grid.length && c >= 0 && c < grid[r].length;
      if (inside && grid[r][c] === BOMB) {
        count += 1;
      }
    }
  }
  return count;
}

function reveal(grid) {
  validateGrid(grid);
  return grid.map((row, r) => row.map((cell, c) => {
    if (cell === BOMB) {
      return BOMB;
    }
    const count = countAdjacentBombs(grid, r, c);
    return count === 0 ? EMPTY : String(count);
  }));
}

function formatGrid(grid) {
  return grid.map((row) => row.join('')).join('\n');
}

function main() {
  const boards = [
    [['*', '-']],
    [
      ['-', '*', '-', '-'],
      ['-', '-', '-', '*'],
      ['*', '-', '-', '-'],
    ],
    [
      ['-', '-', '-'],
      ['-', '-', '-'],
    ],
  ];
  for (const board of boards) {
    const revealed = reveal(board);
    console.log(formatGrid(board));
    console.log('becomes');
    console.log(formatGrid(revealed));
    console.log('');
  }
}

main();

