function parseEndpoints(endpoints) {
  if (!Array.isArray(endpoints) || endpoints.length !== 3) {
    throw new TypeError('blend expects [startColor, endColor, steps]');
  }
  const [start, end, steps] = endpoints;
  if (!Number.isInteger(steps) || steps < 1) {
    throw new RangeError('step count must be a positive integer');
  }
  return { start: validateColor(start), end: validateColor(end), steps };
}

function validateColor(color) {
  if (!Array.isArray(color) || color.length !== 3) {
    throw new TypeError('a color must be a list of three channels');
  }
  return color.map(function (channel) {
    if (!Number.isFinite(channel) || channel < 0 || channel > 255) {
      throw new RangeError('channel out of range: ' + channel);
    }
    return channel;
  });
}

function interpolateChannel(from, to, fraction) {
  const value = from + (to - from) * fraction;
  return Math.round(value);
}

function blend(endpoints) {
  const { start, end, steps } = parseEndpoints(endpoints);
  if (steps === 1) {
    return [start.slice()];
  }
  const sequence = [];
  for (let step = 0; step < steps; step += 1) {
    const fraction = step / (steps - 1);
    const color = [
      interpolateChannel(start[0], end[0], fraction),
      interpolateChannel(start[1], end[1], fraction),
      interpolateChannel(start[2], end[2], fraction)
    ];
    sequence.push(color);
  }
  return sequence;
}

function toHex(color) {
  const digits = color.map(function (channel) {
    return channel.toString(16).padStart(2, '0');
  });
  return '#' + digits.join('');
}

function describe(label, endpoints) {
  const sequence = blend(endpoints);
  const lines = sequence.map(function (color, index) {
    return '  ' + index + ': [' + color.join(', ') + '] ' + toHex(color);
  });
  return label + '\n' + lines.join('\n');
}

function main() {
  console.log(describe('black -> white in 3 steps', [[0, 0, 0], [255, 255, 255], 3]));
  console.log(describe('red -> blue in 5 steps', [[255, 0, 0], [0, 0, 255], 5]));
  console.log(describe('teal -> gold in 4 steps', [[0, 128, 128], [255, 215, 0], 4]));
  try {
    blend([[0, 0, 0], [255, 255, 255], 0]);
  } catch (error) {
    console.log('rejected: ' + error.message);
  }
}

main();

