const DIGIT_GROUPS = {
  b: '1', f: '1', p: '1', v: '1',
  c: '2', g: '2', j: '2', k: '2', q: '2', s: '2', x: '2', z: '2',
  d: '3', t: '3',
  l: '4',
  m: '5', n: '5',
  r: '6'
};

function codeOf(letter) {
  const digit = DIGIT_GROUPS[letter.toLowerCase()];
  return digit === undefined ? '' : digit;
}

function normalize(name) {
  if (typeof name !== 'string') {
    throw new TypeError('soundex expects a list of strings');
  }
  return name.replace(/[^A-Za-z]/g, '').toUpperCase();
}

function soundexOne(name) {
  const cleaned = normalize(name);
  if (cleaned.length === 0) {
    return '0000';
  }
  const first = cleaned.charAt(0);
  let result = first;
  let lastDigit = codeOf(first);
  for (let i = 1; i < cleaned.length && result.length < 4; i += 1) {
    const letter = cleaned.charAt(i);
    const digit = codeOf(letter);
    if (digit !== '' && digit !== lastDigit) {
      result += digit;
    }
    if (letter !== 'H' && letter !== 'W') {
      lastDigit = digit;
    }
  }
  return (result + '000').slice(0, 4);
}

function soundex(names) {
  if (!Array.isArray(names)) {
    throw new TypeError('soundex expects an array');
  }
  return names.map(soundexOne);
}

function groupByCode(names) {
  const buckets = new Map();
  soundex(names).forEach(function (code, index) {
    if (!buckets.has(code)) {
      buckets.set(code, []);
    }
    buckets.get(code).push(names[index]);
  });
  return buckets;
}

function formatReport(names) {
  const lines = [];
  groupByCode(names).forEach(function (members, code) {
    lines.push(code + ': ' + members.join(', '));
  });
  return lines.join('\n');
}

const sample = [
  'Robert', 'Rupert', 'Ashcraft', 'Ashcroft', 'Tymczak', 'Pfister',
  'Honeyman', "O'Hara", 'Van de Graaff', 'Lee', 'Gutierrez', 'Jackson'
];
console.log(soundex(sample).join(' '));
console.log(formatReport(sample));

module.exports = { soundex, soundexOne, groupByCode, formatReport };

