const CODE_PATTERN = /^[A-Za-z]{3}$/;

function normalizeTicket(ticket, index) {
  if (!Array.isArray(ticket) || ticket.length !== 2) {
    throw new TypeError(`ticket ${index} must be a pair of airport codes`);
  }
  const origin = String(ticket[0]).trim();
  const destination = String(ticket[1]).trim();
  if (!CODE_PATTERN.test(origin) || !CODE_PATTERN.test(destination)) {
    throw new TypeError(`ticket ${index} has an invalid airport code`);
  }
  if (origin.toUpperCase() === destination.toUpperCase()) {
    throw new Error(`ticket ${index} departs and arrives at ${origin}`);
  }
  return { origin, destination };
}

function indexTickets(tickets) {
  const legs = new Map();
  const arrivals = new Set();
  tickets.forEach((ticket, index) => {
    const leg = normalizeTicket(ticket, index);
    const key = leg.origin.toUpperCase();
    if (legs.has(key)) {
      throw new Error(`two departures from ${leg.origin}`);
    }
    legs.set(key, leg);
    arrivals.add(leg.destination.toUpperCase());
  });
  return { legs, arrivals };
}

function findStart(legs, arrivals) {
  const origins = [...legs.values()]
    .map((leg) => leg.origin)
    .filter((origin) => !arrivals.has(origin.toUpperCase()));
  if (origins.length !== 1) {
    throw new Error(`expected exactly one starting airport, found ${origins.length}`);
  }
  return origins[0];
}

function connect(tickets) {
  if (!Array.isArray(tickets)) {
    throw new TypeError('tickets must be an array of pairs');
  }
  if (tickets.length === 0) {
    return [];
  }
  const { legs, arrivals } = indexTickets(tickets);
  const route = [];
  let current = findStart(legs, arrivals);
  while (current !== undefined) {
    route.push(current);
    const key = current.toUpperCase();
    const leg = legs.get(key);
    legs.delete(key);
    current = leg === undefined ? undefined : leg.destination;
  }
  if (legs.size > 0) {
    throw new Error('the tickets do not form a single continuous trip');
  }
  return route;
}

function formatRoute(route) {
  return route.length === 0 ? '(no flights)' : route.join(' -> ');
}

const worldTrip = [
  ['GRU', 'JFK'],
  ['NRT', 'SYD'],
  ['LHR', 'DXB'],
  ['DXB', 'NRT'],
  ['JFK', 'LHR'],
];
const worldRoute = connect(worldTrip);
console.log(formatRoute(connect([['jfk', 'lhr'], ['sfo', 'jfk']])));
console.log(formatRoute(worldRoute));
console.log(`legs flown: ${worldRoute.length - 1}`);

