const VOWELS = 'aeiouy';

function isVowel(ch) {
  return VOWELS.indexOf(ch) !== -1;
}

function normalize(word) {
  const cleaned = String(word).toLowerCase().replace(/[^a-z]/g, '');
  return cleaned;
}

function countVowelGroups(word) {
  let groups = 0;
  let inGroup = false;
  for (let i = 0; i < word.length; i += 1) {
    const vowel = isVowel(word[i]);
    if (vowel && !inGroup) {
      groups += 1;
    }
    inGroup = vowel;
  }
  return groups;
}

function hasSilentE(word) {
  if (word.length < 3 || word[word.length - 1] !== 'e') {
    return false;
  }
  const previous = word[word.length - 2];
  return !isVowel(previous) && previous !== 'l';
}

function syllablesOf(word) {
  const normalized = normalize(word);
  if (normalized.length === 0) {
    return 0;
  }
  let syllables = countVowelGroups(normalized);
  if (hasSilentE(normalized)) {
    syllables -= 1;
  }
  return Math.max(1, syllables);
}

function count(words) {
  if (!Array.isArray(words)) {
    throw new TypeError('count expects a list of words');
  }
  return words.map(syllablesOf);
}

function report(words) {
  const counts = count(words);
  const width = words.reduce((longest, word) => Math.max(longest, word.length), 0);
  const lines = words.map((word, index) => {
    const label = word.padEnd(width, ' ');
    return `${label}  ${counts[index]}`;
  });
  return lines.join('\n');
}

