function parseVersion(version) {
  if (typeof version !== 'string') {
    throw new TypeError('version must be a string');
  }
  const trimmed = version.trim();
  if (trimmed === '') {
    throw new Error('version string must not be empty');
  }
  const parts = trimmed.split('.');
  const numbers = parts.map(function (part) {
    if (!/^\d+$/.test(part)) {
      throw new Error('invalid version component: "' + part + '"');
    }
    return parseInt(part, 10);
  });
  return numbers;
}

function compareVersions(left, right) {
  const a = parseVersion(left);
  const b = parseVersion(right);
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i += 1) {
    if (a[i] !== b[i]) {
      return a[i] < b[i] ? -1 : 1;
    }
  }
  if (a.length !== b.length) {
    return a.length < b.length ? -1 : 1;
  }
  return 0;
}

function sort(versions) {
  if (!Array.isArray(versions)) {
    throw new TypeError('versions must be an array');
  }
  const copy = versions.slice();
  copy.sort(compareVersions);
  return copy;
}

function formatOrder(versions) {
  const ordered = sort(versions);
  const labelled = ordered.map(function (version, index) {
    const rank = index + 1;
    return rank + '. ' + version;
  });
  return labelled.join('\n');
}

function main() {
  const samples = [
    ['1.10', '1.2'],
    ['1.2.3', '1.2', '1.2.3.0', '0.9.99'],
    ['10.0.1', '2.30.4', '10.0', '2.30.4.1', '3']
  ];
  samples.forEach(function (sample) {
    const ordered = sort(sample);
    console.log('input:  ' + sample.join(', '));
    console.log('sorted: ' + ordered.join(', '));
    console.log(formatOrder(sample));
    console.log('');
  });
  const newest = sort(samples[2]).pop();
  console.log('newest of last sample: ' + newest);
}

main();

module.exports = { sort, compareVersions, parseVersion, formatOrder };

