const VOWELS = new Set(['a', 'e', 'i', 'o', 'u']);

function isVowel(letter) {
  return VOWELS.has(letter);
}

function onsetLength(word) {
  let index = 0;
  while (index < word.length && !isVowel(word[index])) {
    index += 1;
  }
  return index;
}

function translateWord(word) {
  const cut = onsetLength(word);
  if (cut === 0) {
    return word + 'way';
  }
  const onset = word.slice(0, cut);
  const rest = word.slice(cut);
  return rest + onset + 'ay';
}

function translateSentence(sentence) {
  const pieces = sentence.split(/(\s+)/);
  const converted = pieces.map(function (piece) {
    if (piece.length === 0 || /\s/.test(piece)) {
      return piece;
    }
    return translateWord(piece);
  });
  return converted.join('');
}

function translate(sentences) {
  if (!Array.isArray(sentences)) {
    throw new TypeError('translate expects an array of strings');
  }
  return sentences.map(function (sentence, position) {
    if (typeof sentence !== 'string') {
      throw new TypeError('sentence at index ' + position + ' is not a string');
    }
    return translateSentence(sentence);
  });
}

function formatReport(sentences, results) {
  const lines = sentences.map(function (sentence, position) {
    return sentence + '  ->  ' + results[position];
  });
  return lines.join('\n');
}

function main() {
  const input = [
    'hello world',
    'the quick brown fox jumps over the lazy dog',
    'apple orange   under',
    'rhythm my sky'
  ];
  const output = translate(input);
  console.log(formatReport(input, output));
}

main();

module.exports = { translate, translateSentence, translateWord };

