function splitSegments(path) {
  const parts = path.split('/');
  const segments = [];
  for (const part of parts) {
    if (part === '' || part === '.') {
      continue;
    }
    if (part === '..') {
      if (segments.length > 0) {
        segments.pop();
      }
      continue;
    }
    segments.push(part);
  }
  return segments;
}

function normalize(path) {
  if (typeof path !== 'string') {
    throw new TypeError('each path must be a string, got ' + typeof path);
  }
  const segments = splitSegments(path);
  return '/' + segments.join('/');
}

function resolve(paths) {
  if (!Array.isArray(paths)) {
    throw new TypeError('resolve expects an array of paths');
  }
  return paths.map(normalize);
}

function depthOf(path) {
  const simplified = normalize(path);
  if (simplified === '/') {
    return 0;
  }
  return simplified.split('/').length - 1;
}

function report(paths) {
  const simplified = resolve(paths);
  const width = paths.reduce((max, raw) => Math.max(max, raw.length), 0);
  const lines = [];
  for (let i = 0; i < paths.length; i += 1) {
    const raw = paths[i].padEnd(width, ' ');
    const depth = depthOf(paths[i]);
    lines.push(raw + '  ->  ' + simplified[i] + '  (depth ' + depth + ')');
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    '/a/b/../c',
    'home//user/./docs/',
    '/../../etc/passwd',
    'usr/local/../../bin/tools/..',
    '.',
    '/'
  ];
  console.log(report(samples));
  const deepest = samples.reduce((best, path) => (depthOf(path) > depthOf(best) ? path : best));
  console.log('deepest: ' + normalize(deepest));
}

main();

module.exports = { resolve, normalize, depthOf, report };

