function validate(elevations) {
  if (!Array.isArray(elevations)) {
    throw new TypeError('elevations must be an array');
  }
  for (const height of elevations) {
    if (!Number.isInteger(height) || height < 0) {
      throw new RangeError(`invalid terrain height: ${height}`);
    }
  }
  return elevations;
}

function leftMaxima(elevations) {
  const maxima = new Array(elevations.length);
  let running = 0;
  for (let i = 0; i < elevations.length; i += 1) {
    running = Math.max(running, elevations[i]);
    maxima[i] = running;
  }
  return maxima;
}

function rightMaxima(elevations) {
  const maxima = new Array(elevations.length);
  let running = 0;
  for (let i = elevations.length - 1; i >= 0; i -= 1) {
    running = Math.max(running, elevations[i]);
    maxima[i] = running;
  }
  return maxima;
}

function measure(elevations) {
  validate(elevations);
  const left = leftMaxima(elevations);
  const right = rightMaxima(elevations);
  let total = 0;
  for (let i = 0; i < elevations.length; i += 1) {
    const boundary = Math.min(left[i], right[i]);
    const depth = boundary - elevations[i];
    if (depth > 0) {
      total += depth;
    }
  }
  return total;
}

function profile(elevations) {
  validate(elevations);
  const left = leftMaxima(elevations);
  const right = rightMaxima(elevations);
  return elevations.map((height, i) => {
    const depth = Math.min(left[i], right[i]) - height;
    return { index: i, height, water: depth > 0 ? depth : 0 };
  });
}

function report(elevations) {
  const cells = profile(elevations);
  const wet = cells.filter((cell) => cell.water > 0);
  const columns = wet.map((cell) => `#${cell.index}:${cell.water}`).join(' ');
  const summary = `terrain [${elevations.join(', ')}] traps ${measure(elevations)} unit(s)`;
  return wet.length === 0 ? `${summary}` : `${summary} -> ${columns}`;
}

const terrains = [
  [2, 0, 2],
  [0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1],
  [4, 2, 0, 3, 2, 5],
  [1, 2, 3, 4],
];

for (const terrain of terrains) {
  console.log(report(terrain));
}

module.exports = { measure, profile, report };

