function stripComments(styles) {
  let output = ''
  let index = 0
  while (index < styles.length) {
    const isCommentStart = styles[index] === '/' && styles[index + 1] === '*'
    if (isCommentStart) {
      const end = styles.indexOf('*/', index + 2)
      index = end === -1 ? styles.length : end + 2
    } else {
      output += styles[index]
      index += 1
    }
  }
  return output
}

function flattenWhitespace(styles) {
  let flattened = ''
  for (const character of styles) {
    if (character === '\n' || character === '\r' || character === '\t') {
      flattened += ' '
    } else {
      flattened += character
    }
  }
  return flattened
}

function collapseRuns(styles) {
  const collapsed = []
  for (const character of styles) {
    const previous = collapsed[collapsed.length - 1]
    if (character === ' ' && previous === ' ') {
      continue
    }
    collapsed.push(character)
  }
  return collapsed.join('')
}

function trimAroundTokens(styles) {
  const tokens = '{}:;'
  let trimmed = ''
  for (let i = 0; i < styles.length; i += 1) {
    const character = styles[i]
    if (character !== ' ') {
      trimmed += character
      continue
    }
    const before = trimmed[trimmed.length - 1]
    const after = styles[i + 1]
    const touchesToken = tokens.includes(before) || tokens.includes(after)
    if (!touchesToken) {
      trimmed += character
    }
  }
  return trimmed
}

function minify(styles) {
  if (typeof styles !== 'string') {
    throw new TypeError('minify expects a stylesheet string')
  }
  const withoutComments = stripComments(styles)
  const singleLine = flattenWhitespace(withoutComments)
  const collapsed = collapseRuns(singleLine)
  return trimAroundTokens(collapsed).trim()
}

function reportSavings(original, compressed) {
  const saved = original.length - compressed.length
  const ratio = original.length === 0 ? 0 : (saved / original.length) * 100
  return `${compressed} (saved ${saved} of ${original.length} chars, ${ratio.toFixed(1)}%)`
}

const sheet = [
  '/* page frame */',
  'body {',
  '\tcolor: red;',
  '\tmargin : 0 auto ;',
  '}',
  'a:hover { text-decoration : underline }'
].join('\n')

console.log(minify('body {color: red}'))
console.log(reportSavings(sheet, minify(sheet)))

