const DIGIT_LETTERS = {
  '2': 'abc',
  '3': 'def',
  '4': 'ghi',
  '5': 'jkl',
  '6': 'mno',
  '7': 'pqrs',
  '8': 'tuv',
  '9': 'wxyz'
};

function validate(digits) {
  if (typeof digits !== 'string') {
    throw new TypeError('digits must be a string');
  }
  for (const ch of digits) {
    if (!(ch in DIGIT_LETTERS)) {
      throw new RangeError(`unsupported digit: ${ch}`);
    }
  }
  return digits;
}

function combinations(digits) {
  validate(digits);
  if (digits.length === 0) {
    return [];
  }
  let results = [''];
  for (const digit of digits) {
    const letters = DIGIT_LETTERS[digit];
    const next = [];
    for (const prefix of results) {
      for (const letter of letters) {
        next.push(prefix + letter);
      }
    }
    results = next;
  }
  return results;
}

function countCombinations(digits) {
  validate(digits);
  let total = digits.length === 0 ? 0 : 1;
  for (const digit of digits) {
    total *= DIGIT_LETTERS[digit].length;
  }
  return total;
}

function report(digits) {
  const words = combinations(digits);
  const expected = countCombinations(digits);
  const shown = words.slice(0, 12).join(', ');
  const tail = words.length > 12 ? ', ...' : '';
  return `${digits || '(empty)'} -> ${expected} combination(s): ${shown}${tail}`;
}

function main() {
  const inputs = ['23', '7', '', '279'];
  for (const input of inputs) {
    console.log(report(input));
  }
  try {
    combinations('12');
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

