'use strict';

function validate(sequence) {
  if (!Array.isArray(sequence)) {
    throw new TypeError('sequence must be an array');
  }
  if (sequence.length < 3) {
    throw new RangeError('sequence must contain at least three elements');
  }
  for (const value of sequence) {
    if (!Number.isInteger(value)) {
      throw new TypeError(`sequence must hold integers, got ${value}`);
    }
  }
}

function step(sequence) {
  const first = sequence[0];
  const last = sequence[sequence.length - 1];
  const span = last - first;
  const delta = span / sequence.length;
  if (!Number.isInteger(delta) || delta === 0) {
    throw new RangeError('sequence does not describe a strict progression');
  }
  return delta;
}

function find(sequence) {
  validate(sequence);
  const delta = step(sequence);
  for (let i = 1; i < sequence.length; i += 1) {
    const previous = sequence[i - 1];
    const current = sequence[i];
    if (current - previous !== delta) {
      return previous + delta;
    }
  }
  throw new RangeError('sequence has no missing element');
}

function restore(sequence) {
  const missing = find(sequence);
  const delta = step(sequence);
  const full = sequence.slice();
  const position = full.findIndex((value) => value === missing - delta) + 1;
  full.splice(position, 0, missing);
  return full;
}

function report(sequence) {
  const missing = find(sequence);
  const delta = step(sequence);
  const shown = sequence.join(', ');
  const rebuilt = restore(sequence).join(', ');
  return `[${shown}] step ${delta} -> missing ${missing} -> [${rebuilt}]`;
}

function main() {
  const samples = [
    [2, 4, 8],
    [1, 2, 3, 4, 6, 7, 8, 9, 10],
    [10, 20, 30, 50, 60],
    [-7, -4, -1, 5, 8],
  ];
  for (const sample of samples) {
    console.log(report(sample));
  }
  try {
    find([3, 3, 3]);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { find, restore, report };

