const OVERDRAFT_FEE = 35;

function validateTransactions(transactions) {
  if (!Array.isArray(transactions)) {
    throw new TypeError('transactions must be an array');
  }
  transactions.forEach((amount, index) => {
    if (typeof amount !== 'number' || !Number.isFinite(amount)) {
      throw new TypeError(`transaction at index ${index} is not a finite number`);
    }
  });
  return transactions;
}

function reconcile(transactions) {
  validateTransactions(transactions);
  let balance = 0;
  let fees = 0;
  for (const amount of transactions) {
    balance += amount;
    if (balance < 0) {
      balance -= OVERDRAFT_FEE;
      fees += 1;
    }
  }
  return [balance, fees];
}

function formatAmount(amount) {
  const sign = amount < 0 ? '-' : '';
  const cents = Math.round(Math.abs(amount) * 100);
  const whole = Math.floor(cents / 100);
  const fraction = String(cents % 100).padStart(2, '0');
  return `${sign}$${whole}.${fraction}`;
}

function describeStatement(label, transactions) {
  const [balance, fees] = reconcile(transactions);
  const activity = transactions.map(formatAmount).join(', ');
  const feeText = fees === 1 ? '1 fee' : `${fees} fees`;
  return `${label}: [${activity}] -> ${formatAmount(balance)} with ${feeText}`;
}

function summarize(accounts) {
  const lines = [];
  let totalFees = 0;
  for (const [label, transactions] of accounts) {
    lines.push(describeStatement(label, transactions));
    totalFees += reconcile(transactions)[1];
  }
  lines.push(`Total fees charged across accounts: ${formatAmount(totalFees * OVERDRAFT_FEE)}`);
  return lines.join('\n');
}

function main() {
  const accounts = [
    ['Checking', [10, -20]],
    ['Savings', [100, -50, 25.5, -10]],
    ['Payroll', [-5, 200, -300, 150]],
    ['Empty', []],
  ];
  console.log(summarize(accounts));
}

main();

module.exports = { reconcile, formatAmount, describeStatement, summarize };

