function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function normalizeScale(scale) {
  if (typeof scale !== 'string' || scale.length !== 1) {
    throw new TypeError('scale must be a single character');
  }
  const lower = scale.toLowerCase();
  if (lower !== 'c' && lower !== 'f') {
    throw new RangeError(`unsupported scale: ${scale}`);
  }
  return lower;
}

function roundToTenth(value) {
  const scaled = Math.round(value * 10);
  return scaled / 10;
}

function celsiusToFahrenheit(celsius) {
  return celsius * 9 / 5 + 32;
}

function fahrenheitToCelsius(fahrenheit) {
  return (fahrenheit - 32) * 5 / 9;
}

function convertPair(pair) {
  if (!Array.isArray(pair) || pair.length !== 2) {
    throw new TypeError('each reading must be a [value, scale] pair');
  }
  const [value, scale] = pair;
  if (!isFiniteNumber(value)) {
    throw new TypeError(`reading value must be a finite number: ${value}`);
  }
  const from = normalizeScale(scale);
  if (from === 'c') {
    return [roundToTenth(celsiusToFahrenheit(value)), 'f'];
  }
  return [roundToTenth(fahrenheitToCelsius(value)), 'c'];
}

function convert(temperatures) {
  if (!Array.isArray(temperatures)) {
    throw new TypeError('temperatures must be a list of pairs');
  }
  return temperatures.map(convertPair);
}

function formatReading(pair) {
  const [value, scale] = pair;
  return `${value.toFixed(1)}${scale.toUpperCase()}`;
}

function report(temperatures) {
  const converted = convert(temperatures);
  const lines = [];
  for (let i = 0; i < temperatures.length; i += 1) {
    lines.push(`${formatReading(temperatures[i])} -> ${formatReading(converted[i])}`);
  }
  return lines.join('\n');
}

function main() {
  const readings = [[0, 'c'], [32, 'f'], [100, 'c'], [-40, 'f'], [98.6, 'F'], [37, 'C']];
  console.log(report(readings));
  console.log(JSON.stringify(convert([[0, 'c'], [32, 'f']])));
  try {
    convert([[20, 'k']]);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { convert, report, formatReading };

