function buildAdjacency(edges) {
  const adjacency = new Map();
  for (const edge of edges) {
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b)) {
      throw new TypeError(`edge [${a}, ${b}] must contain integer node identifiers`);
    }
    if (!adjacency.has(a)) {
      adjacency.set(a, []);
    }
    if (!adjacency.has(b)) {
      adjacency.set(b, []);
    }
    adjacency.get(a).push(b);
    adjacency.get(b).push(a);
  }
  return adjacency;
}

function validate(edges) {
  const adjacency = buildAdjacency(edges);
  const colors = new Map();
  for (const start of adjacency.keys()) {
    if (colors.has(start)) {
      continue;
    }
    colors.set(start, 0);
    const queue = [start];
    while (queue.length > 0) {
      const node = queue.shift();
      const nodeColor = colors.get(node);
      for (const neighbor of adjacency.get(node)) {
        if (!colors.has(neighbor)) {
          colors.set(neighbor, 1 - nodeColor);
          queue.push(neighbor);
        } else if (colors.get(neighbor) === nodeColor) {
          return false;
        }
      }
    }
  }
  return true;
}

function describeGraph(name, edges) {
  const adjacency = buildAdjacency(edges);
  const nodeCount = adjacency.size;
  const verdict = validate(edges) ? "two-colorable" : "not two-colorable";
  return `${name}: ${nodeCount} nodes, ${edges.length} edges -> ${verdict}`;
}

function main() {
  const graphs = [
    ["cyclic square", [[0, 1], [1, 2], [2, 3], [3, 0]]],
    ["triangle", [[0, 1], [1, 2], [2, 0]]],
    ["path", [[5, 6], [6, 7], [7, 8]]],
    ["two components", [[0, 1], [1, 2], [10, 11], [11, 12], [12, 10]]],
    ["empty graph", []],
  ];
  for (const [name, edges] of graphs) {
    console.log(describeGraph(name, edges));
  }
  try {
    validate([[0, 1], [1, 2.5]]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

