const PLAYER_ONE = "player one";
const PLAYER_TWO = "player two";
const POINT_NAMES = ["zero", "fifteen", "thirty", "forty"];

function validatePoints(points) {
  if (!Array.isArray(points)) {
    throw new TypeError("points must be an array of player names");
  }
  points.forEach((winner, index) => {
    if (winner !== PLAYER_ONE && winner !== PLAYER_TWO) {
      throw new Error(`point ${index + 1} has unknown winner: ${winner}`);
    }
  });
  return points;
}

function describeScore(one, two) {
  if (one >= 3 && two >= 3) {
    const lead = one - two;
    if (lead === 0) {
      return "deuce";
    }
    if (lead === 1) {
      return `advantage ${PLAYER_ONE}`;
    }
    if (lead === -1) {
      return `advantage ${PLAYER_TWO}`;
    }
    return lead > 0 ? `${PLAYER_ONE} wins game` : `${PLAYER_TWO} wins game`;
  }
  if (one === 4) {
    return `${PLAYER_ONE} wins game`;
  }
