function createBuffer(capacity) {
  return { items: [], capacity: capacity };
}

function pushItem(buffer, value) {
  const lost = [];
  buffer.items.push(value);
  while (buffer.items.length > buffer.capacity) {
    lost.push(buffer.items.shift());
  }
  return lost;
}

function popItem(buffer) {
  if (buffer.items.length === 0) {
    return [];
  }
  const oldest = buffer.items.shift();
  return [oldest];
}

function resizeBuffer(buffer, capacity) {
  const lost = [];
  buffer.capacity = capacity;
  while (buffer.items.length > buffer.capacity) {
    lost.push(buffer.items.shift());
  }
  return lost;
}

function parseCommand(command) {
  if (!Array.isArray(command) || command.length === 0) {
    throw new TypeError('each command must be a non-empty array');
  }
  const name = command[0];
  const argument = command[1];
  if (name === 'pop') {
    return { name: name, argument: null };
  }
  if (name !== 'push' && name !== 'resize') {
    throw new RangeError('unknown command: ' + String(name));
  }
  if (!Number.isInteger(argument)) {
    throw new TypeError(name + ' requires an integer argument');
  }
  if (name === 'resize' && argument < 0) {
    throw new RangeError('capacity cannot be negative');
  }
  return { name: name, argument: argument };
}

function simulate(commands) {
  const buffer = createBuffer(5);
  const removed = [];
  for (const raw of commands) {
    const command = parseCommand(raw);
    if (command.name === 'push') {
      removed.push(...pushItem(buffer, command.argument));
    } else if (command.name === 'pop') {
      removed.push(...popItem(buffer));
    } else {
      removed.push(...resizeBuffer(buffer, command.argument));
    }
  }
  return removed;
}

function describe(commands) {
  const removed = simulate(commands);
  return commands.length + ' commands -> removed [' + removed.join(', ') + ']';
}

const overflow = [1, 2, 3, 4, 5, 6].map((n) => ['push', n]);
console.log(describe(overflow));
console.log(describe([...overflow, ['pop'], ['resize', 2], ['push', 7]]));
console.log(describe([['push', 10], ['pop'], ['pop'], ['resize', 0], ['push', 11]]));

