function validateWeights(weights) {
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new TypeError('weights must be a non-empty array');
  }
  let total = 0;
  for (const w of weights) {
    if (!Number.isInteger(w) || w < 0) {
      throw new RangeError(`weight ${w} must be a non-negative integer`);
    }
    total += w;
  }
  if (total === 0) {
    throw new RangeError('weights must not sum to zero');
  }
  return total;
}

function validateRandoms(randoms) {
  if (!Array.isArray(randoms)) {
    throw new TypeError('randoms must be an array');
  }
  for (const r of randoms) {
    if (typeof r !== 'number' || Number.isNaN(r) || r < 0 || r >= 1) {
      throw new RangeError(`random ${r} must lie in [0, 1)`);
    }
  }
  return randoms.length;
}

function sample(weights, randoms) {
  const total = validateWeights(weights);
  validateRandoms(randoms);
  const picked = [];
  for (const r of randoms) {
    const target = r * total;
    let accumulated = 0;
    let index = weights.length - 1;
    for (let i = 0; i < weights.length; i += 1) {
      accumulated += weights[i];
      if (accumulated > target) {
        index = i;
        break;
      }
    }
    picked.push(index);
  }
  return picked;
}

function tally(indices, categoryCount) {
  const counts = new Array(categoryCount).fill(0);
  for (const index of indices) {
    counts[index] += 1;
  }
  return counts;
}

function report(weights, randoms) {
  const indices = sample(weights, randoms);
  const counts = tally(indices, weights.length);
  const total = weights.reduce((a, b) => a + b, 0);
  const lines = counts.map((count, i) => {
    const expected = (weights[i] / total) * indices.length;
    return `category ${i}: weight ${weights[i]}, picked ${count}, expected ${expected.toFixed(2)}`;
  });
  return lines.join('\n');
}

const weights = [10, 90];
const randoms = [0.05, 0.1, 0.4, 0.75, 0.99];
console.log(sample(weights, randoms).join(', '));
console.log(report(weights, randoms));

