const TIME_PATTERN = /^(\d{2}):(\d{2}):(\d{2}),(\d{3})$/;

function parseTimestamp(text) {
  const match = TIME_PATTERN.exec(text);
  if (!match) {
    throw new Error(`invalid timestamp: ${text}`);
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  const seconds = Number(match[3]);
  const millis = Number(match[4]);
  if (minutes > 59 || seconds > 59) {
    throw new Error(`timestamp out of range: ${text}`);
  }
  return ((hours * 60 + minutes) * 60 + seconds) * 1000 + millis;
}

function formatTimestamp(total) {
  if (total < 0) {
    throw new Error(`shift moves timestamp before zero: ${total}ms`);
  }
  const millis = total % 1000;
  const allSeconds = (total - millis) / 1000;
  const seconds = allSeconds % 60;
  const allMinutes = (allSeconds - seconds) / 60;
  const minutes = allMinutes % 60;
  const hours = (allMinutes - minutes) / 60;
  const pad = (value, width) => String(value).padStart(width, '0');
  return `${pad(hours, 2)}:${pad(minutes, 2)}:${pad(seconds, 2)},${pad(millis, 3)}`;
}

function synchronize(subtitles, shift) {
  if (!Number.isInteger(shift)) {
    throw new Error('shift must be an integer number of milliseconds');
  }
  const result = [];
  for (const record of subtitles) {
    const [start, end, ...rest] = record;
    const newStart = formatTimestamp(parseTimestamp(start) + shift);
    const newEnd = formatTimestamp(parseTimestamp(end) + shift);
    result.push([newStart, newEnd, ...rest]);
  }
  return result;
}

function toSrt(subtitles) {
  const blocks = subtitles.map((record, index) => {
    const [start, end, text] = record;
    return `${index + 1}\n${start} --> ${end}\n${text}`;
  });
  return blocks.join('\n\n');
}

function main() {
  const subtitles = [
    ['00:00:01,000', '00:00:03,500', 'Good morning.'],
    ['00:59:59,800', '01:00:02,250', 'The hour is turning over.'],
    ['01:23:45,678', '01:23:47,000', 'Almost the end.'],
  ];
  const delayed = synchronize(subtitles, 1500);
  console.log(toSrt(delayed));
  console.log('---');
  const advanced = synchronize(subtitles, -500);
  console.log(toSrt(advanced));
  console.log('---');
  try {
    synchronize(subtitles, -2000);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { synchronize, parseTimestamp, formatTimestamp, toSrt };

