const FIELDS = [
  { name: 'minute', min: 0, max: 59 },
  { name: 'hour', min: 0, max: 23 },
  { name: 'day of month', min: 1, max: 31 },
  { name: 'month', min: 1, max: 12 },
  { name: 'day of week', min: 0, max: 6 }
];

function range(min, max) {
  const values = [];
  for (let value = min; value <= max; value += 1) {
    values.push(value);
  }
  return values;
}

function parseField(text, spec) {
  if (text === '*') {
    return range(spec.min, spec.max);
  }
  const parts = text.split(',');
  const values = [];
  for (const part of parts) {
    if (!/^\d+$/.test(part)) {
      throw new Error(`invalid ${spec.name} field: "${text}"`);
    }
    const value = Number(part);
    if (value < spec.min || value > spec.max) {
      throw new Error(`${spec.name} value ${value} outside ${spec.min}-${spec.max}`);
    }
    if (!values.includes(value)) {
      values.push(value);
    }
  }
  values.sort((a, b) => a - b);
  return values;
}

function parse(expression) {
  if (typeof expression !== 'string') {
    throw new TypeError('expression must be a string');
  }
  const fields = expression.trim().split(/\s+/);
  if (fields.length !== 5) {
    throw new Error(`expected 5 fields, got ${fields.length}`);
  }
  return FIELDS.map((spec, index) => parseField(fields[index], spec));
}

function describe(expression) {
  const parsed = parse(expression);
  const lines = parsed.map((values, index) => {
    const label = FIELDS[index].name.padEnd(12, ' ');
    return `${label} ${values.join(' ')}`;
  });
  return lines.join('\n');
}

const samples = ['* * * * *', '30 4 1,15 * 5', '0,15,30,45 9,17 * 1,6,12 1,2,3,4,5'];

for (const sample of samples) {
  console.log(`expression: ${sample}`);
  console.log(describe(sample));
  const counts = parse(sample).map((values) => values.length);
  console.log(`counts: ${counts.join(', ')}\n`);
}

try {
  parse('60 * * * *');
} catch (error) {
  console.log(`rejected: ${error.message}`);
}

module.exports = { parse, describe };

