function normalizeCalls(calls, current) {
  if (!Array.isArray(calls)) {
    throw new TypeError('calls must be an array of floor numbers');
  }
  const cleaned = [];
  for (const call of calls) {
    if (!Number.isInteger(call)) {
      throw new TypeError(`floor request ${String(call)} is not an integer`);
    }
    if (call !== current && !cleaned.includes(call)) {
      cleaned.push(call);
    }
  }
  return cleaned;
}

function splitByDirection(calls, current) {
  const above = calls.filter((floor) => floor > current);
  const below = calls.filter((floor) => floor < current);
  above.sort((a, b) => a - b);
  below.sort((a, b) => b - a);
  return { above, below };
}

function route(calls, current) {
  if (!Number.isInteger(current)) {
    throw new TypeError('current floor must be an integer');
  }
  const pending = normalizeCalls(calls, current);
  const { above, below } = splitByDirection(pending, current);
  if (above.length === 0) {
    return below;
  }
  return above.concat(below);
}

function travelDistance(order, current) {
  let position = current;
  let distance = 0;
  for (const floor of order) {
    distance += Math.abs(floor - position);
    position = floor;
  }
  return distance;
}

function describeRoute(calls, current) {
  const order = route(calls, current);
  const path = order.length === 0 ? 'idle' : order.join(' -> ');
  const travelled = travelDistance(order, current);
  return `from ${current} with [${calls.join(', ')}]: ${path} (${travelled} floors)`;
}

function main() {
  const scenarios = [
