function columnWidths(rows) {
  const widths = [];
  for (const row of rows) {
    row.forEach((cell, index) => {
      const length = String(cell).length;
      if (widths[index] === undefined || length > widths[index]) {
        widths[index] = length;
      }
    });
  }
  return widths;
}

function columnCount(rows) {
  let count = 0;
  for (const row of rows) {
    if (row.length > count) {
      count = row.length;
    }
  }
  return count;
}

function padCell(value, width) {
  const text = String(value);
  const missing = width - text.length;
  return text + " ".repeat(missing);
}

function formatRow(row, widths) {
  const cells = [];
  for (let i = 0; i < widths.length; i += 1) {
    const value = i < row.length ? row[i] : "";
    cells.push(padCell(value, widths[i]));
  }
  return cells.join("|");
}

function separatorLine(widths) {
  const segments = widths.map((width) => "-".repeat(width));
  return segments.join("+");
}

function format(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return "";
  }
  const count = columnCount(rows);
  if (count === 0) {
    return "";
  }
  const widths = columnWidths(rows);
  const lines = [formatRow(rows[0], widths)];
  lines.push(separatorLine(widths));
  for (let i = 1; i < rows.length; i += 1) {
