function buildGraph(packages) {
  const dependencies = new Map();
  const dependents = new Map();
  const ensure = (name) => {
    if (!dependencies.has(name)) {
      dependencies.set(name, new Set());
      dependents.set(name, new Set());
    }
  };
  for (const entry of packages) {
    if (!Array.isArray(entry) || entry.length === 0) {
      continue;
    }
    const [name, ...needs] = entry;
    ensure(name);
    for (const need of needs) {
      if (need === name) {
        continue;
      }
      ensure(need);
      dependencies.get(name).add(need);
      dependents.get(need).add(name);
    }
  }
  return { dependencies, dependents };
}

function resolve(packages) {
  const { dependencies, dependents } = buildGraph(packages);
  const remaining = new Map();
  const ready = [];
  for (const [name, needs] of dependencies) {
    remaining.set(name, needs.size);
    if (needs.size === 0) {
      ready.push(name);
    }
  }
  ready.sort();
  const order = [];
  while (ready.length > 0) {
    const name = ready.shift();
    order.push(name);
    const waiting = [...dependents.get(name)].sort();
    for (const consumer of waiting) {
      const left = remaining.get(consumer) - 1;
      remaining.set(consumer, left);
      if (left === 0) {
        ready.push(consumer);
      }
    }
  }
  if (order.length !== dependencies.size) {
    return [];
  }
  return order;
}

function report(label, packages) {
  const order = resolve(packages);
  const text = order.length === 0 ? "circular dependency detected" : order.join(" -> ");
  return `${label}: ${text}`;
}

const application = [
  ["alpha", "beta", "gamma"],
  ["beta", "delta"],
  ["gamma", "delta"],
  ["delta"],
  ["epsilon", "alpha"],
];
const broken = [
  ["one", "two"],
  ["two", "three"],
  ["three", "one"],
];
console.log(report("application", application));
console.log(report("broken", broken));
console.log(report("implicit", [["tools", "compiler"]]));
console.log(report("empty", []));

module.exports = { resolve, buildGraph, report };

