const BASE32 = '0123456789bcdefghjkmnpqrstuvwxyz';

function validate(latitude, longitude, precision) {
  if (typeof latitude !== 'number' || Number.isNaN(latitude)) {
    throw new TypeError('latitude must be a number');
  }
  if (typeof longitude !== 'number' || Number.isNaN(longitude)) {
    throw new TypeError('longitude must be a number');
  }
  if (latitude < -90 || latitude > 90) {
    throw new RangeError('latitude out of range: ' + latitude);
  }
  if (longitude < -180 || longitude > 180) {
    throw new RangeError('longitude out of range: ' + longitude);
  }
  if (!Number.isInteger(precision) || precision < 1) {
    throw new RangeError('precision must be a positive integer');
  }
}

function encode(latitude, longitude, precision) {
  validate(latitude, longitude, precision);
  const latRange = [-90, 90];
  const lonRange = [-180, 180];
  let hash = '';
  let bits = 0;
  let value = 0;
  let useLongitude = true;
  while (hash.length < precision) {
    const range = useLongitude ? lonRange : latRange;
    const coordinate = useLongitude ? longitude : latitude;
    const middle = (range[0] + range[1]) / 2;
    if (coordinate >= middle) {
      value = (value << 1) | 1;
      range[0] = middle;
    } else {
      value = value << 1;
      range[1] = middle;
    }
    useLongitude = !useLongitude;
    bits += 1;
    if (bits === 5) {
      hash += BASE32[value];
      bits = 0;
      value = 0;
    }
  }
  return hash;
}

function formatCoordinate(latitude, longitude) {
  const latText = Math.abs(latitude).toFixed(4) + (latitude < 0 ? 'S' : 'N');
  const lonText = Math.abs(longitude).toFixed(4) + (longitude < 0 ? 'W' : 'E');
  return latText + ' ' + lonText;
}

function report(places, precision) {
  const width = Math.max(...places.map((place) => place.name.length));
  const lines = places.map((place) => {
    const label = place.name.padEnd(width);
    const where = formatCoordinate(place.lat, place.lon);
    return label + '  ' + where.padEnd(22) + '  ' + encode(place.lat, place.lon, precision);
  });
  return lines.join('\n');
}

const places = [
  { name: 'Null Island', lat: 0, lon: 0 },
  { name: 'Paris', lat: 48.8566, lon: 2.3522 },
  { name: 'Sydney', lat: -33.8688, lon: 151.2093 },
  { name: 'Quito', lat: -0.1807, lon: -78.4678 },
];

console.log(encode(0, 0, 1));
console.log(report(places, 9));

module.exports = { encode, formatCoordinate, report };

