const VARIABLE_PATTERN = /\{\{([^{}]*)\}\}/g;

function buildContextMap(context) {
  if (!Array.isArray(context)) {
    throw new TypeError('context must be a list of [name, value] pairs');
  }
  const map = new Map();
  for (const entry of context) {
    if (!Array.isArray(entry) || entry.length !== 2) {
      throw new TypeError('each context entry must be a pair');
    }
    const name = String(entry[0]).trim();
    const value = String(entry[1]);
    map.set(name, value);
  }
  return map;
}

function render(template, context) {
  const map = buildContextMap(context);
  return String(template).replace(VARIABLE_PATTERN, (match, rawName) => {
    const name = rawName.trim();
    if (map.has(name)) {
      return map.get(name);
    }
    return match;
  });
}

function variableNames(template) {
  const names = [];
  for (const match of String(template).matchAll(VARIABLE_PATTERN)) {
    const name = match[1].trim();
    if (!names.includes(name)) {
      names.push(name);
    }
  }
  return names;
}

function missingVariables(template, context) {
  const map = buildContextMap(context);
  return variableNames(template).filter((name) => !map.has(name));
}

function report(template, context) {
  const lines = ['template: ' + template, 'output:   ' + render(template, context)];
  const missing = missingVariables(template, context);
  if (missing.length > 0) {
    lines.push('missing:  ' + missing.join(', '));
  }
  return lines.join('\n');
}

function main() {
  const people = [['name', 'Alice'], ['city', 'Paris']];
  console.log(report('hello {{  name  }}', people));
  console.log(report('Dear {{name}}, welcome to {{ city }} on {{date}}.', people));
  console.log(report('{{a}}+{{b}}={{sum}}', [['a', '2'], ['b', '3'], ['sum', '5']]));
}

main();

