const LINE_PATTERN = /^(\d{4}-\d{2}-\d{2})\s+(\d{2}):(\d{2}):(\d{2})\s+([A-Za-z]+)\s+(.*)$/;

const TRACKED_LEVELS = ['error', 'warning'];

function parseLine(line) {
  const match = LINE_PATTERN.exec(line.trim());
  if (match === null) {
    return null;
  }
  const hour = Number(match[2]);
  const minute = Number(match[3]);
  const second = Number(match[4]);
  if (hour > 23 || minute > 59 || second > 59) {
    return null;
  }
  const level = match[5].toLowerCase();
  return { date: match[1], hour: hour, level: level, message: match[6] };
}

function summarize(logs) {
  const counts = new Map();
  for (const line of logs) {
    const entry = parseLine(line);
    if (entry === null) {
      continue;
    }
    if (!TRACKED_LEVELS.includes(entry.level)) {
      continue;
    }
    if (!counts.has(entry.hour)) {
      counts.set(entry.hour, [0, 0]);
    }
    const bucket = counts.get(entry.hour);
    const index = entry.level === 'error' ? 0 : 1;
    bucket[index] += 1;
  }
  const result = [];
  for (let hour = 0; hour < 24; hour += 1) {
    const bucket = counts.get(hour);
    if (bucket === undefined) {
      continue;
    }
    result.push([hour, bucket[0], bucket[1]]);
  }
  return result;
}

function formatReport(summary) {
  if (summary.length === 0) {
    return 'no errors or warnings found';
  }
  const rows = summary.map(function (row) {
    const label = String(row[0]).padStart(2, '0') + ':00';
    return label + '  errors=' + row[1] + '  warnings=' + row[2];
  });
  return rows.join('\n');
}

const sampleLogs = [
  '2024-05-01 03:12:44 ERROR disk controller timeout',
  '2024-05-01 03:44:02 error failed to flush journal',
  '2024-05-01 03:50:10 INFO nightly backup started',
  '2024-05-01 09:05:00 WARNING cache hit ratio below target',
  '2024-05-01 09:31:18 warning retrying upstream request',
  '2024-05-01 09:32:01 ERROR upstream gave up after 3 tries',
  '2024-05-01 17:00:59 DEBUG scheduler tick',
  'malformed line without a timestamp',
  '2024-05-01 21:07:33 Error certificate expires in 2 days'
];

const summary = summarize(sampleLogs);
console.log(formatReport(summary));

module.exports = { summarize: summarize, parseLine: parseLine, formatReport: formatReport };

