function validateHex(hex, index) {
  if (!Array.isArray(hex) || hex.length !== 3) {
    throw new TypeError(`hexagon at index ${index} must be a list of three integers`);
  }
  for (const component of hex) {
    if (!Number.isInteger(component)) {
      throw new TypeError(`hexagon at index ${index} has a non-integer component: ${component}`);
    }
  }
  const sum = hex[0] + hex[1] + hex[2];
  if (sum !== 0) {
    throw new RangeError(`hexagon at index ${index} has components summing to ${sum}, not 0`);
  }
  return hex;
}

function hexDistance(a, b) {
  const dx = Math.abs(a[0] - b[0]);
  const dy = Math.abs(a[1] - b[1]);
  const dz = Math.abs(a[2] - b[2]);
  return (dx + dy + dz) / 2;
}

function distance(points) {
  if (!Array.isArray(points)) {
    throw new TypeError('points must be a list of cubic coordinates');
  }
  points.forEach(validateHex);
  if (points.length === 0) {
    return [];
  }
  const origin = points[0];
  const distances = [];
  for (let i = 1; i < points.length; i += 1) {
    distances.push(hexDistance(origin, points[i]));
  }
  return distances;
}

function formatHex(hex) {
  return `(${hex.join(', ')})`;
}

function report(points) {
  const distances = distance(points);
  const lines = distances.map((value, offset) => {
    const target = formatHex(points[offset + 1]);
    return `${formatHex(points[0])} -> ${target} = ${value}`;
  });
  return lines.join('\n');
}

function main() {
  const grid = [
    [0, 0, 0],
    [1, 0, -1],
    [0, 1, -1],
    [-2, 1, 1],
    [3, -3, 0],
    [-1, -2, 3],
  ];
  console.log(report(grid));
  console.log(`distances: [${distance(grid).join(', ')}]`);
  const shifted = grid.map((hex) => [hex[0] + 2, hex[1] - 5, hex[2] + 3]);
  console.log(`shifted distances: [${distance(shifted).join(', ')}]`);
  try {
    distance([[1, 1, 1]]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { distance, hexDistance, report, formatHex, validateHex };

