function buildDiscountMap(rules) {
  const map = new Map();
  for (const rule of rules) {
    const [category, percent] = rule;
    if (typeof category !== 'string') {
      throw new TypeError('rule category must be a string');
    }
    if (typeof percent !== 'number' || Number.isNaN(percent)) {
      throw new TypeError('rule percent must be a number');
    }
    const current = map.has(category) ? map.get(category) : 0;
    if (percent > current) {
      map.set(category, percent);
    }
  }
  return map;
}

function discountFor(category, discountMap) {
  const percent = discountMap.get(category);
  if (percent === undefined) {
    return 0;
  }
  return Math.min(Math.max(percent, 0), 100);
}

function discountedPrice(price, percent) {
  return price * (1 - percent / 100);
}

function roundMoney(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function evaluate(items, rules) {
  const discountMap = buildDiscountMap(rules);
  let total = 0;
  for (const item of items) {
    const [category, name, price] = item;
    if (typeof price !== 'number' || Number.isNaN(price)) {
      throw new TypeError(`price for ${name} must be a number`);
    }
    const percent = discountFor(category, discountMap);
    total += discountedPrice(price, percent);
  }
  return roundMoney(total);
}

function receiptLines(items, rules) {
  const discountMap = buildDiscountMap(rules);
  const lines = [];
  for (const [category, name, price] of items) {
    const percent = discountFor(category, discountMap);
    const paid = roundMoney(discountedPrice(price, percent));
    lines.push(`${name} (${category}): ${paid.toFixed(2)} after ${percent}% off`);
  }
  lines.push(`TOTAL: ${evaluate(items, rules).toFixed(2)}`);
  return lines;
}

const cart = [
  ['fruit', 'apple', 10.0],
  ['fruit', 'banana', 4.5],
  ['electronics', 'headphones', 89.99],
  ['stationery', 'notebook', 3.25],
];

const promotions = [
  ['fruit', 10],
  ['fruit', 20],
  ['electronics', 15],
];

for (const line of receiptLines(cart, promotions)) {
  console.log(line);
}

console.log(evaluate([['fruit', 'apple', 10.0]], [['fruit', 20]]));

