const SCALE = [' ', '.', '-'];
const DENSE = '*';

function validate(points, size) {
  if (!Number.isInteger(size) || size <= 0) {
    throw new RangeError('size must be a positive integer');
  }
  points.forEach(function (point, index) {
    if (!Array.isArray(point) || point.length !== 2) {
      throw new TypeError('point ' + index + ' must be a pair of coordinates');
    }
    const x = point[0];
    const y = point[1];
    if (!Number.isInteger(x) || !Number.isInteger(y)) {
      throw new TypeError('point ' + index + ' must hold integer coordinates');
    }
  });
}

function tally(points, size) {
  const counts = [];
  for (let row = 0; row < size; row += 1) {
    counts.push(new Array(size).fill(0));
  }
  points.forEach(function (point) {
    const x = point[0];
    const y = point[1];
    if (x >= 0 && x < size && y >= 0 && y < size) {
      counts[y][x] += 1;
    }
  });
  return counts;
}

function symbolFor(count) {
  if (count >= SCALE.length) {
    return DENSE;
  }
  return SCALE[count];
}

function generate(points, size) {
  validate(points, size);
  const counts = tally(points, size);
  return counts.map(function (row) {
    return row.map(symbolFor).join('');
  });
}

function frame(rows) {
  const width = rows.length > 0 ? rows[0].length : 0;
  const edge = '+' + '-'.repeat(width) + '+';
  const framed = rows.map(function (row) {
    return '|' + row + '|';
  });
  return [edge].concat(framed, [edge]);
}

function summarize(points, size) {
  const inside = points.filter(function (point) {
    return point[0] >= 0 && point[0] < size && point[1] >= 0 && point[1] < size;
  });
  return inside.length + ' of ' + points.length + ' points inside a ' + size + 'x' + size + ' grid';
}

