const NOTES = ['C', 'C sharp', 'D', 'D sharp', 'E', 'F', 'F sharp', 'G', 'G sharp', 'A', 'A sharp', 'B'];

const FLAT_EQUIVALENTS = {
  'D flat': 'C sharp',
  'E flat': 'D sharp',
  'G flat': 'F sharp',
  'A flat': 'G sharp',
  'B flat': 'A sharp'
};

function normalizeNote(name) {
  if (typeof name !== 'string') {
    throw new TypeError('note must be a string');
  }
  const cleaned = name.trim().replace(/\s+/g, ' ');
  const expanded = cleaned.replace(/^([A-Ga-g])#$/, '$1 sharp').replace(/^([A-Ga-g])b$/, '$1 flat');
  const parts = expanded.split(' ');
  let canonical = parts[0].toUpperCase();
  if (parts.length > 1) {
    canonical += ' ' + parts[1].toLowerCase();
  }
  if (Object.prototype.hasOwnProperty.call(FLAT_EQUIVALENTS, canonical)) {
    canonical = FLAT_EQUIVALENTS[canonical];
  }
  if (!NOTES.includes(canonical)) {
    throw new RangeError('unknown note: ' + name);
  }
  return canonical;
}

function normalizeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('intervals must be an array');
  }
  return intervals.map(function (step) {
    if (!Number.isInteger(step)) {
      throw new TypeError('interval must be an integer: ' + step);
    }
    return step;
  });
}

function build(root, intervals) {
  const start = normalizeNote(root);
  const steps = normalizeIntervals(intervals);
  let index = NOTES.indexOf(start);
  const sequence = [NOTES[index]];
  for (const step of steps) {
    index = (((index + step) % NOTES.length) + NOTES.length) % NOTES.length;
    sequence.push(NOTES[index]);
  }
  return sequence;
}

function describe(root, intervals) {
  const sequence = build(root, intervals);
  const label = intervals.length === 0 ? 'no intervals' : intervals.join('-');
  return normalizeNote(root) + ' [' + label + ']: ' + sequence.join(', ');
}

function main() {
  const requests = [
    ['C', [2, 2]],
    ['F sharp', [2, 2, 1, 2, 2, 2, 1]],
    ['B flat', [3, 4, 3]],
    ['a', [-2, -2, -1]]
  ];
  for (const [root, intervals] of requests) {
    console.log(describe(root, intervals));
  }
}

main();

