function validate(height, bounce, window) {
  if (typeof height !== 'number' || Number.isNaN(height)) {
    throw new TypeError('height must be a number');
  }
  if (typeof bounce !== 'number' || Number.isNaN(bounce)) {
    throw new TypeError('bounce must be a number');
  }
  if (typeof window !== 'number' || Number.isNaN(window)) {
    throw new TypeError('window must be a number');
  }
  if (height <= 0) {
    throw new RangeError('height must be greater than zero');
  }
  if (bounce <= 0 || bounce >= 1) {
    throw new RangeError('bounce must be a fraction strictly between 0 and 1');
  }
  if (window <= 0) {
    throw new RangeError('window must be greater than zero');
  }
}

function simulate(height, bounce, window) {
  validate(height, bounce, window);
  if (height <= window) {
    return 0;
  }
  let peak = height;
  let passes = 1;
  peak = peak * bounce;
  while (peak > window) {
    passes = passes + 2;
    peak = peak * bounce;
  }
  return passes;
}

function peakHeights(height, bounce, window) {
  validate(height, bounce, window);
  const peaks = [height];
  let peak = height * bounce;
  while (peak > window) {
    peaks.push(peak);
    peak = peak * bounce;
  }
  return peaks;
}

function report(height, bounce, window) {
  const passes = simulate(height, bounce, window);
  const peaks = peakHeights(height, bounce, window);
  const rounded = peaks.map((p) => p.toFixed(2));
  const list = rounded.join(' -> ');
  return `drop ${height}, bounce ${bounce}, window ${window}: ` +
    `${passes} pass(es) with peaks ${list}`;
}

function main() {
  const cases = [
    [10, 0.6, 1],
    [3, 0.66, 1.5],
    [30, 0.75, 1.5],
  ];
  for (const [height, bounce, window] of cases) {
    console.log(report(height, bounce, window));
  }
  try {
    simulate(10, 1.5, 1);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { simulate, peakHeights, report };

