function toMap(pairs) {
  const totals = new Map()
  for (const [name, qty] of pairs) {
    totals.set(name, (totals.get(name) || 0) + qty)
  }
  return totals
}

function validateOrder(order) {
  for (const [name, qty] of order) {
    if (typeof name !== "string" || name.length === 0) {
      throw new TypeError("item name must be a non-empty string")
    }
    if (!Number.isInteger(qty) || qty < 0) {
      throw new RangeError(`quantity for ${name} must be a non-negative integer`)
    }
  }
  return order
}

function allocate(order, warehouses) {
  const needed = toMap(validateOrder(order))
  const allocations = []
  for (const [warehouseName, inventory] of warehouses) {
    const stock = toMap(inventory)
    const taken = []
    for (const [item, want] of needed) {
      const have = stock.get(item) || 0
      const amount = Math.min(want, have)
      if (amount > 0) {
        taken.push([item, amount])
        needed.set(item, want - amount)
      }
    }
    if (taken.length > 0) {
      allocations.push([warehouseName, taken])
    }
  }
  return allocations
}

function shortfall(order, allocations) {
  const needed = toMap(order)
  for (const [, taken] of allocations) {
    for (const [item, qty] of taken) {
      needed.set(item, needed.get(item) - qty)
    }
  }
  return [...needed].filter(([, qty]) => qty > 0)
}

function formatReport(allocations, missing) {
  const lines = allocations.map(([warehouseName, taken]) => {
    const detail = taken.map(([item, qty]) => `${qty} x ${item}`).join(", ")
    return `${warehouseName}: ${detail}`
  })
  for (const [item, qty] of missing) {
    lines.push(`UNFILLED: ${qty} x ${item}`)
  }
  return lines.join("\n")
}

