function validateCoefficients(coefficients) {
  if (!Array.isArray(coefficients)) {
    throw new TypeError('coefficients must be an array of numbers');
  }
  for (let i = 0; i < coefficients.length; i += 1) {
    const term = coefficients[i];
    if (typeof term !== 'number' || !Number.isFinite(term)) {
      throw new TypeError(`coefficient at index ${i} is not a finite number`);
    }
  }
  return coefficients;
}

function differentiate(coefficients) {
  validateCoefficients(coefficients);
  const derived = [];
  for (let exponent = 1; exponent < coefficients.length; exponent += 1) {
    derived.push(coefficients[exponent] * exponent);
  }
  return derived;
}

function evaluatePolynomial(coefficients, point) {
  validateCoefficients(coefficients);
  if (typeof point !== 'number' || !Number.isFinite(point)) {
    throw new TypeError('point must be a finite number');
  }
  let total = 0;
  for (let index = coefficients.length - 1; index >= 0; index -= 1) {
    total = total * point + coefficients[index];
  }
  return total;
}

function evaluate(coefficients, point) {
  const derivative = differentiate(coefficients);
  return evaluatePolynomial(derivative, point);
}

function formatPolynomial(coefficients) {
  const parts = [];
  for (let exponent = coefficients.length - 1; exponent >= 0; exponent -= 1) {
    const factor = coefficients[exponent];
    if (factor === 0) {
      continue;
    }
    if (exponent === 0) {
      parts.push(String(factor));
    } else if (exponent === 1) {
      parts.push(`${factor}x`);
    } else {
      parts.push(`${factor}x^${exponent}`);
    }
  }
  if (parts.length === 0) {
    return '0';
  }
  return parts.join(' + ');
}

function report(coefficients, point) {
  const derivative = differentiate(coefficients);
  const slope = evaluatePolynomial(derivative, point);
  const original = formatPolynomial(coefficients);
  const derived = formatPolynomial(derivative);
  return `p(x) = ${original}; p'(x) = ${derived}; p'(${point}) = ${slope}`;
}

const samples = [
  { coefficients: [1, 2, 3], point: 2 },
  { coefficients: [5], point: 7 },
  { coefficients: [0, -4, 0, 1], point: -3 },
];

for (const sample of samples) {
  console.log(report(sample.coefficients, sample.point));
}

console.log(evaluate([1, 2, 3], 2));

module.exports = { evaluate, differentiate, evaluatePolynomial, formatPolynomial, report };

