const TYPES = ['credit', 'debit'];

function validateTransaction(entry, index) {
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError(`transaction ${index} must be [date, type, amount]`);
  }
  const [date, type, amount] = entry;
  if (typeof date !== 'string' || date.trim() === '') {
    throw new TypeError(`transaction ${index} has an empty date`);
  }
  if (!TYPES.includes(type)) {
    throw new TypeError(`transaction ${index} has unknown type "${type}"`);
  }
  if (typeof amount !== 'number' || !Number.isFinite(amount)) {
    throw new TypeError(`transaction ${index} has a non-numeric amount`);
  }
  return [date, type, amount];
}

function reconcile(transactions, balance) {
  if (!Array.isArray(transactions)) {
    throw new TypeError('transactions must be a list of lists');
  }
  if (typeof balance !== 'number' || !Number.isFinite(balance)) {
    throw new TypeError('balance must be a finite number');
  }
  const checked = transactions.map(validateTransaction);
  const ledger = new Array(checked.length);
  let running = balance;
  for (let i = checked.length - 1; i >= 0; i -= 1) {
    const [date, type, amount] = checked[i];
    ledger[i] = [date, type, amount, round(running)];
    running = type === 'debit' ? running + amount : running - amount;
  }
  return ledger;
}

function round(value) {
  return Math.round(value * 100) / 100;
}

function money(value) {
  const sign = value < 0 ? '-' : '';
  return `${sign}$${Math.abs(round(value)).toFixed(2)}`;
}

function formatLedger(ledger) {
  const header = ['DATE', 'TYPE', 'AMOUNT', 'BALANCE'];
  const rows = ledger.map(([date, type, amount, bal]) => [date, type, money(amount), money(bal)]);
  const widths = header.map((label, column) => {
    const cells = rows.map((row) => row[column].length);
    return Math.max(label.length, ...cells, 0);
  });
  const line = (cells) => cells.map((cell, i) => cell.padEnd(widths[i])).join('  ').trimEnd();
  const divider = widths.map((width) => '-'.repeat(width)).join('  ');
  return [line(header), divider, ...rows.map(line)].join('\n');
}

function openingBalance(ledger) {
  if (ledger.length === 0) {
    return 0;
  }
  const [, type, amount, bal] = ledger[0];
  return round(type === 'debit' ? bal + amount : bal - amount);
}

const history = [
  ['2024-01-03', 'credit', 250],
  ['2024-01-09', 'debit', 42.5],
  ['2024-01-15', 'debit', 10],
  ['2024-01-22', 'credit', 80.25],
];

const ledger = reconcile(history, 100);
console.log(formatLedger(ledger));
console.log(`Opening balance: ${money(openingBalance(ledger))}`);
console.log(`Closing balance: ${money(ledger[ledger.length - 1][3])}`);
console.log(reconcile([['2024-02-01', 'debit', 10]], 100));

