    return value;
  }
  return Math.round(value * 100) / 100;
}

function validateEntry(entry, index) {
  if (!Array.isArray(entry) || entry.length !== 2) {
    throw new TypeError("recipe entry " + index + " must be [name, quantity]");
  }
  const name = entry[0];
  const quantity = entry[1];
  if (typeof name !== "string" || name.length === 0) {
    throw new TypeError("ingredient name at index " + index + " must be a non-empty string");
  }
  if (typeof quantity !== "number" || !Number.isFinite(quantity)) {
    throw new TypeError("quantity for " + name + " must be a finite number");
  }
  return [name, quantity];
}

function scale(recipe, multiplier) {
  if (!Array.isArray(recipe)) {
    throw new TypeError("recipe must be an array of [name, quantity] pairs");
  }
  if (typeof multiplier !== "number" || !Number.isFinite(multiplier)) {
    throw new TypeError("multiplier must be a finite number");
  }
  return recipe.map(function (entry, index) {
    const pair = validateEntry(entry, index);
    const scaled = roundQuantity(pair[1] * multiplier);
    return [pair[0], scaled];
  });
}

function formatRecipe(recipe) {
  const width = recipe.reduce(function (longest, entry) {
    return Math.max(longest, entry[0].length);
  }, 0);
  const lines = recipe.map(function (entry) {
    const label = entry[0].padEnd(width, " ");
    return label + "  " + entry[1];
  });
  return lines.join("\n");
}

function report(recipe, multiplier) {
  const scaled = scale(recipe, multiplier);
  const header = "Scaled by " + multiplier + ":";
  return header + "\n" + formatRecipe(scaled);
}

