const PERMISSION_LETTERS = ['r', 'w', 'x'];

function validate(octal) {
  if (typeof octal !== 'string') {
    throw new TypeError('permissions must be given as a string');
  }
  const trimmed = octal.trim();
  if (!/^[0-7]{3}$/.test(trimmed)) {
    throw new RangeError(`invalid octal permission string: "${octal}"`);
  }
  return trimmed;
}

function decodeDigit(digit) {
  const value = Number(digit);
  let symbols = '';
  for (let bit = 0; bit < 3; bit += 1) {
    const mask = 1 << (2 - bit);
    symbols += (value & mask) ? PERMISSION_LETTERS[bit] : '-';
  }
  return symbols;
}

function decode(octal) {
  const digits = validate(octal);
  let symbolic = '';
  for (const digit of digits) {
    symbolic += decodeDigit(digit);
  }
  return symbolic;
}

function encode(symbolic) {
  if (!/^[r-][w-][x-][r-][w-][x-][r-][w-][x-]$/.test(symbolic)) {
    throw new RangeError(`invalid symbolic permission string: "${symbolic}"`);
  }
  let octal = '';
  for (let group = 0; group < 3; group += 1) {
    const chunk = symbolic.slice(group * 3, group * 3 + 3);
    let value = 0;
    for (let bit = 0; bit < 3; bit += 1) {
      if (chunk[bit] !== '-') {
        value += 1 << (2 - bit);
      }
    }
    octal += String(value);
  }
  return octal;
}

function describe(octal) {
  const symbolic = decode(octal);
  const classes = ['user', 'group', 'others'];
  const parts = classes.map((name, index) => {
    const chunk = symbolic.slice(index * 3, index * 3 + 3);
    return `${name}=${chunk}`;
  });
  return `${octal} -> ${symbolic} (${parts.join(', ')})`;
}

function main() {
  const samples = ['754', '000', '777', '644', '007'];
  for (const sample of samples) {
    console.log(describe(sample));
  }
  const roundTrip = encode(decode('640'));
  console.log(`round trip 640 -> ${roundTrip}`);
  try {
    decode('8x9');
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { decode, encode, describe };

