function validateLegs(passes) {
  if (!Array.isArray(passes)) {
    throw new TypeError('passes must be an array of legs')
  }
  passes.forEach((leg, index) => {
    if (!Array.isArray(leg) || leg.length !== 2) {
      throw new TypeError(`leg ${index} must be a [from, to] pair`)
    }
    if (typeof leg[0] !== 'string' || typeof leg[1] !== 'string') {
      throw new TypeError(`leg ${index} must contain two city names`)
    }
    if (leg[0] === leg[1]) {
      throw new Error(`leg ${index} departs and arrives in ${leg[0]}`)
    }
  })
}

function buildRoute(passes) {
  const next = new Map()
  passes.forEach(([from, to]) => {
    if (next.has(from)) {
      throw new Error(`two legs depart from ${from}`)
    }
    next.set(from, to)
  })
  return next
}

function findStart(passes, next) {
  const arrivals = new Set(passes.map((leg) => leg[1]))
  const origins = [...next.keys()].filter((city) => !arrivals.has(city))
  if (origins.length !== 1) {
    throw new Error('the legs do not form a single continuous journey')
  }
  return origins[0]
}

function sort(passes) {
  validateLegs(passes)
  if (passes.length === 0) {
    return []
  }
  const next = buildRoute(passes)
  let city = findStart(passes, next)
  const itinerary = [city]
  while (next.has(city)) {
    city = next.get(city)
    if (itinerary.includes(city)) {
      throw new Error(`the journey loops back to ${city}`)
    }
    itinerary.push(city)
  }
  if (itinerary.length !== passes.length + 1) {
    throw new Error('some legs are disconnected from the journey')
  }
  return itinerary
}

function formatItinerary(cities) {
  if (cities.length === 0) {
    return '(no legs booked)'
  }
  return cities.join(' -> ')
}

function main() {
  const trips = [
    [['paris', 'rome'], ['london', 'paris']],
    [['Chicago', 'Denver'], ['Denver', 'Reno'], ['Austin', 'Chicago']],
    [['Oslo', 'Bergen']],
  ]
  trips.forEach((legs) => {
    const itinerary = sort(legs)
    console.log(`${legs.length} legs: ${formatItinerary(itinerary)}`)
  })
  try {
    sort([['Kyoto', 'Osaka'], ['Lima', 'Cusco']])
  } catch (error) {
    console.log(`rejected: ${error.message}`)
  }
}

main()

module.exports = { sort, formatItinerary }

