function normalizeName(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Customer names must be strings, received ' + typeof name);
  }
  const trimmed = name.trim();
  if (trimmed.length === 0) {
    throw new Error('Customer names must not be empty');
  }
  return trimmed;
}

function letterPrefix(name) {
  const letters = name.replace(/[^A-Za-z]/g, '');
  const padded = (letters + 'XXX').slice(0, 3);
  return padded.toUpperCase();
}

function sequenceLabel(position) {
  return String(position).padStart(2, '0');
}

function buildCode(name, position) {
  const prefix = letterPrefix(name);
  return prefix + name.length + sequenceLabel(position);
}

function generate(names) {
  if (!Array.isArray(names)) {
    throw new TypeError('generate expects an array of names');
  }
  return names.map(function (name, index) {
    const clean = normalizeName(name);
    return buildCode(clean, index + 1);
  });
}

