function validatePlant(requirement) {
  if (!Array.isArray(requirement) || requirement.length !== 3) {
    throw new TypeError('each requirement must be [name, frequencyDays, gallons]');
  }
  const [name, frequency, gallons] = requirement;
  if (typeof name !== 'string' || name.length === 0) {
    throw new TypeError('plant name must be a non-empty string');
  }
  if (!Number.isInteger(frequency) || frequency < 1) {
    throw new RangeError(`frequency for ${name} must be a positive whole number of days`);
  }
  if (typeof gallons !== 'number' || !Number.isFinite(gallons) || gallons < 0) {
    throw new RangeError(`gallons for ${name} must be a non-negative number`);
  }
  return { name, frequency, gallons };
}

const DAYS_IN_MONTH = 30;

function wateringDays(frequency) {
  const days = [];
  for (let day = 1; day <= DAYS_IN_MONTH; day += frequency) {
    days.push(day);
  }
  return days;
}

function plantUsage(requirement) {
  const { name, frequency, gallons } = validatePlant(requirement);
  const days = wateringDays(frequency);
  return { name, days, total: days.length * gallons };
}

function water(plants) {
  if (!Array.isArray(plants)) {
    throw new TypeError('plants must be an array of requirements');
  }
  let total = 0;
  for (const requirement of plants) {
    total += plantUsage(requirement).total;
  }
  return total;
}

function formatSchedule(plants) {
  const lines = plants.map((requirement) => {
    const usage = plantUsage(requirement);
    const times = usage.days.length;
    return `${usage.name}: watered ${times}x (days ${usage.days.join(', ')}) = ${usage.total} gal`;
  });
  lines.push(`month total: ${water(plants)} gal`);
  return lines.join('\n');
}

function main() {
  const garden = [
    ['tomato', 3, 2],
    ['basil', 1, 0.5],
    ['cactus', 14, 1],
    ['fern', 7, 3],
  ];
  console.log(formatSchedule(garden));
  try {
    water([['mint', 0, 1]]);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { water, wateringDays, plantUsage, formatSchedule };

