const VOWEL_SEQUENCE = 'aeiou';

function isVowel(ch) {
  return VOWEL_SEQUENCE.indexOf(ch.toLowerCase()) !== -1;
}

function shiftVowel(ch) {
  const lower = ch.toLowerCase();
  const index = VOWEL_SEQUENCE.indexOf(lower);
  if (index === -1) {
    return ch;
  }
  const next = VOWEL_SEQUENCE[(index + 1) % VOWEL_SEQUENCE.length];
  return ch === lower ? next : next.toUpperCase();
}

function shift(text) {
  if (typeof text !== 'string') {
    throw new TypeError('shift expects a string');
  }
  let result = '';
  for (const ch of text) {
    result += shiftVowel(ch);
  }
  return result;
}

function countVowels(text) {
  let total = 0;
  for (const ch of text) {
    if (isVowel(ch)) {
      total += 1;
    }
  }
  return total;
}

function shiftWords(text) {
  const words = text.split(' ');
  return words.map(shift);
}

function formatReport(text) {
  const shifted = shift(text);
  const vowels = countVowels(text);
  const lines = [];
  lines.push('input   : ' + text);
  lines.push('shifted : ' + shifted);
  lines.push('vowels  : ' + vowels);
  lines.push('by word : ' + shiftWords(text).join(' | '));
  return lines.join('\n');
}

function main() {
  const samples = ['hello world', 'Quick Brown Fox', 'Aeiou, unicorn!', 'rhythm'];
  for (const sample of samples) {
    console.log(formatReport(sample));
    console.log('');
  }
  const roundTrip = shift(shift(shift(shift(shift('hello world')))));
  console.log('five shifts return the original: ' + (roundTrip === 'hello world'));
}

main();

module.exports = { shift, shiftVowel, countVowels, shiftWords, formatReport };

