function validateVisit(visit, index) {
  if (!Array.isArray(visit) || visit.length !== 2) {
    throw new TypeError(`visit at index ${index} must be a [member, day] pair`);
  }
  const [member, day] = visit;
  if (typeof member !== 'string' && typeof member !== 'number') {
    throw new TypeError(`member at index ${index} must be a string or number`);
  }
  if (!Number.isInteger(day) || day < 1 || day > 365) {
    throw new RangeError(`day at index ${index} must be an integer from 1 to 365`);
  }
  return [member, day];
}

function attendance(visits) {
  if (!Array.isArray(visits)) {
    throw new TypeError('visits must be an array of [member, day] pairs');
  }
  const daysByMember = new Map();
  const order = [];
  visits.forEach((visit, index) => {
    const [member, day] = validateVisit(visit, index);
    const key = String(member);
    if (!daysByMember.has(key)) {
      daysByMember.set(key, new Set());
      order.push([key, member]);
    }
    daysByMember.get(key).add(day);
  });
  const counted = order.map(([key, member]) => [member, daysByMember.get(key).size]);
  counted.sort((a, b) => {
    if (b[1] !== a[1]) {
      return b[1] - a[1];
    }
    return String(a[0]).localeCompare(String(b[0]));
  });
  return counted;
}

function busiestDay(visits) {
  const perDay = new Map();
  visits.forEach((visit, index) => {
    const [member, day] = validateVisit(visit, index);
    if (!perDay.has(day)) {
      perDay.set(day, new Set());
    }
    perDay.get(day).add(String(member));
  });
  let best = null;
  perDay.forEach((members, day) => {
    if (best === null || members.size > best.count || (members.size === best.count && day < best.day)) {
      best = { day, count: members.size };
    }
  });
  return best;
}

function formatReport(rows) {
  const width = rows.reduce((max, [member]) => Math.max(max, String(member).length), 6);
  const lines = rows.map(([member, count]) => `${String(member).padEnd(width)}  ${String(count).padStart(3)}`);
  lines.unshift(`${'member'.padEnd(width)}  ${'day'.padStart(3)}`);
  return lines.join('\n');
}

const log = [
  ['1', 10], ['1', 10], ['1', 11], ['2', 10],
  ['2', 200], ['2', 365], ['3', 7], ['1', 11],
];
const ranking = attendance(log);
console.log(formatReport(ranking));
const peak = busiestDay(log);
console.log(`busiest day: ${peak.day} with ${peak.count} members`);

module.exports = { attendance, busiestDay, formatReport };

