'use strict';

const WORD_VALUES = {
  half: 0.5,
  quarter: 0.25,
  third: 1 / 3,
  one: 1,
  two: 2,
  three: 3,
  four: 4,
  five: 5,
  six: 6,
  seven: 7,
  eight: 8,
};

const GRAMS_PER_CUP = { flour: 120, sugar: 200 };
const DEFAULT_GRAMS_PER_CUP = 150;
const CUP_WORDS = new Set(['cup', 'cups', 'cupful', 'cupfuls']);

function parseNumber(token) {
  if (/^\d+(?:\.\d+)?$/.test(token)) {
    return Number(token);
  }
  const fraction = /^(\d+)\/(\d+)$/.exec(String(token));
  if (fraction) {
    return Number(fraction[1]) / Number(fraction[2]);
  }
  if (Object.prototype.hasOwnProperty.call(WORD_VALUES, token)) {
    return WORD_VALUES[token];
  }
  return null;
}

function parseIngredient(text) {
  const tokens = text.toLowerCase().trim().split(/\s+/);
  let quantity = 0;
  let index = 0;
  let sawQuantity = false;
  while (index < tokens.length) {
    const token = tokens[index];
    if (token === 'and' && sawQuantity) {
      index += 1;
      continue;
    }
    if ((token === 'a' || token === 'an') && parseNumber(tokens[index + 1]) !== null) {
      index += 1;
      continue;
    }
    const value = parseNumber(token);
    if (value === null) {
      break;
    }
    quantity += value;
    sawQuantity = true;
    index += 1;
  }
  if (!sawQuantity) {
    quantity = 1;
  }
  while (index < tokens.length && CUP_WORDS.has(tokens[index])) {
    index += 1;
  }
  const name = tokens.slice(index).join(' ');
  if (name === '') {
    throw new Error(`cannot find an ingredient name in "${text}"`);
  }
  return { quantity, name };
}

function gramsPerCup(name) {
  if (Object.prototype.hasOwnProperty.call(GRAMS_PER_CUP, name)) {
    return GRAMS_PER_CUP[name];
  }
  return DEFAULT_GRAMS_PER_CUP;
}

function convert(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('convert expects an array of measurement strings');
  }
  return ingredients.map((entry) => {
    if (typeof entry !== 'string') {
      throw new TypeError(`measurement must be a string, got ${typeof entry}`);
    }
    const { quantity, name } = parseIngredient(entry);
    const grams = Math.round(quantity * gramsPerCup(name));
    return `${grams} grams ${name}`;
  });
}

const recipe = [
  'two cups flour',
  'half cup sugar',
  '1.5 cups cocoa powder',
  'a cup ground almonds',
  'one and a half cups flour',
  '3/4 cup sugar',
];

convert(recipe).forEach((line) => {
  console.log(line);
});

