function validateTimes(times) {
  if (!Array.isArray(times)) {
    throw new TypeError('times must be an array of cumulative seconds');
  }
  if (times.length === 0) {
    throw new RangeError('times must contain at least one turn');
  }
  let previous = 0;
  for (const value of times) {
    if (!Number.isInteger(value)) {
      throw new TypeError(`cumulative time ${value} is not an integer`);
    }
    if (value <= previous) {
      throw new RangeError(`cumulative time ${value} does not increase past ${previous}`);
    }
    previous = value;
  }
  return times;
}

function computeSplits(times) {
  validateTimes(times);
  const segments = [];
  let previous = 0;
  for (const value of times) {
    segments.push(value - previous);
    previous = value;
  }
  return segments;
}

function roundOne(value) {
  return Math.round(value * 10) / 10;
}

function splits(times) {
  const segments = computeSplits(times);
  let fastest = segments[0];
  let total = 0;
  for (const segment of segments) {
    if (segment < fastest) {
      fastest = segment;
    }
    total += segment;
  }
  const average = total / segments.length;
  return [roundOne(fastest), roundOne(average)];
}

function formatReport(times) {
  const segments = computeSplits(times);
  const [fastest, average] = splits(times);
  const distance = segments.length * 50;
  const lines = [`Race over ${distance} m`];
  segments.forEach((segment, index) => {
    lines.push(`  ${(index + 1) * 50} m turn: split ${segment.toFixed(1)} s`);
  });
  lines.push(`  fastest split: ${fastest.toFixed(1)} s`);
  lines.push(`  average split: ${average.toFixed(1)} s`);
  return lines.join('\n');
}

