function validateInputs(inventory, thresholds) {
  if (!Array.isArray(inventory) || !Array.isArray(thresholds)) {
    throw new TypeError('inventory and thresholds must both be arrays');
  }
  if (inventory.length !== thresholds.length) {
    throw new RangeError('inventory and thresholds must have equal length');
  }
  for (let i = 0; i < inventory.length; i += 1) {
    const stock = inventory[i];
    const minimum = thresholds[i];
    if (!Number.isFinite(stock) || !Number.isFinite(minimum)) {
      throw new TypeError(`stock and threshold at index ${i} must be finite numbers`);
    }
    if (stock < 0 || minimum < 0) {
      throw new RangeError(`stock and threshold at index ${i} must not be negative`);
    }
  }
}

function restock(inventory, thresholds) {
  validateInputs(inventory, thresholds);
  const orders = [];
  for (let i = 0; i < inventory.length; i += 1) {
    const shortfall = thresholds[i] - inventory[i];
    orders.push(shortfall > 0 ? shortfall : 0);
  }
  return orders;
}

function totalUnitsOrdered(orders) {
  return orders.reduce((sum, quantity) => sum + quantity, 0);
}

function itemsNeedingRestock(names, orders) {
  const needed = [];
  orders.forEach((quantity, i) => {
    if (quantity > 0) {
      needed.push(names[i]);
    }
  });
  return needed;
}

function buildReport(names, inventory, thresholds) {
  const orders = restock(inventory, thresholds);
  const lines = orders.map((quantity, i) => {
    const label = names[i].padEnd(10, ' ');
    return `${label} stock=${inventory[i]} min=${thresholds[i]} order=${quantity}`;
  });
  lines.push(`Total units to order: ${totalUnitsOrdered(orders)}`);
  const flagged = itemsNeedingRestock(names, orders);
  const summary = flagged.length > 0 ? flagged.join(', ') : 'nothing';
  lines.push(`Restock required for: ${summary}`);
  return lines.join('\n');
}

function main() {
  const names = ['bolts', 'nuts', 'washers', 'screws'];
  const inventory = [10, 20, 0, 7];
  const thresholds = [15, 15, 50, 7];
  console.log(restock([10, 20], [15, 15]).join(' '));
  console.log(buildReport(names, inventory, thresholds));
}

main();

module.exports = { restock, totalUnitsOrdered, itemsNeedingRestock, buildReport };

