const QUALIFYING_SCORE = 1000;

function validateScores(scores) {
  if (!Array.isArray(scores)) {
    throw new TypeError('scores must be an array of numbers');
  }
  const cleaned = [];
  for (const score of scores) {
    if (typeof score !== 'number' || Number.isNaN(score)) {
      throw new TypeError(`invalid score: ${String(score)}`);
    }
    cleaned.push(score);
  }
  return cleaned;
}

function validateLimit(limit) {
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
    throw new RangeError('limit must be a non-negative integer');
  }
  return limit;
}

function qualifies(score) {
  return score >= QUALIFYING_SCORE;
}

function highscores(scores, limit) {
  const values = validateScores(scores);
  const cap = validateLimit(limit);
  const qualified = values.filter(qualifies);
  qualified.sort((a, b) => b - a);
  return qualified.slice(0, cap);
}

function formatBoard(board) {
  if (board.length === 0) {
    return 'no qualifying scores';
  }
  const lines = board.map((score, index) => {
    const rank = String(index + 1).padStart(2, ' ');
    const points = score.toLocaleString('en-US');
    return `${rank}. ${points} pts`;
  });
  return lines.join('\n');
}

function report(label, scores, limit) {
  const board = highscores(scores, limit);
  const header = `${label} (limit ${limit}, ${board.length} shown)`;
  return `${header}\n${formatBoard(board)}`;
}

function main() {
  console.log(report('Arcade night', [500, 2000, 3000], 1));
  console.log(report('Weekend tournament', [1200, 999, 4500, 1200, 8000, 300], 3));
  console.log(report('Beginner lobby', [100, 250, 999], 5));
  console.log(report('Short list', [1500, 2500], 10));
  try {
    highscores([1000, 'oops'], 2);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { highscores, formatBoard, report };

