const BASE_PRICE = 50;
const EARLY_WINDOW = 30;
const LATE_WINDOW = 10;
const EARLY_DISCOUNT = 0.2;
const LATE_PREMIUM = 0.1;

function priceFor(day) {
  if (day > EARLY_WINDOW) {
    return BASE_PRICE * (1 - EARLY_DISCOUNT);
  }
  if (day >= LATE_WINDOW) {
    return BASE_PRICE;
  }
  return BASE_PRICE * (1 + LATE_PREMIUM);
}

function validate(days) {
  if (!Array.isArray(days)) {
    throw new TypeError('pricing expects an array of integers');
  }
  days.forEach((day, index) => {
    if (!Number.isInteger(day)) {
      throw new TypeError(`entry ${index} is not an integer: ${day}`);
    }
    if (day < 0) {
      throw new RangeError(`entry ${index} is negative: ${day}`);
    }
  });
}

function pricing(days) {
  validate(days);
  return days.map(priceFor);
}

function formatMoney(amount) {
  const rounded = Math.round(amount * 100) / 100;
  return `$${rounded.toFixed(2)}`;
}

function tierOf(day) {
  if (day > EARLY_WINDOW) {
    return 'early-bird';
  }
  if (day >= LATE_WINDOW) {
    return 'standard';
  }
  return 'last-minute';
}

function report(days) {
  const prices = pricing(days);
  const lines = days.map((day, index) => {
    const label = `${day} day(s) out`.padEnd(16);
    return `${label} ${tierOf(day).padEnd(12)} ${formatMoney(prices[index])}`;
  });
  const total = prices.reduce((sum, price) => sum + price, 0);
  lines.push(`${'TOTAL'.padEnd(29)} ${formatMoney(total)}`);
  return lines.join('\n');
}

function main() {
  const purchases = [40, 20, 5];
  console.log(pricing(purchases).join(', '));
  console.log(report([45, 31, 30, 10, 9, 0]));
  try {
    pricing([12, -3]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { pricing, report, formatMoney, tierOf };

