const DAILY_GOAL = 10000;

function validateSteps(steps) {
  if (!Array.isArray(steps)) {
    throw new TypeError('steps must be an array of daily step counts');
  }
  steps.forEach((count, index) => {
    if (typeof count !== 'number' || !Number.isFinite(count)) {
      throw new TypeError(`step count at day ${index + 1} is not a finite number`);
    }
    if (count < 0) {
      throw new RangeError(`step count at day ${index + 1} is negative`);
    }
  });
  return steps;
}

function streaks(steps) {
  validateSteps(steps);
  let maxStreak = 0;
  let current = 0;
  let goalDays = 0;
  for (const count of steps) {
    if (count >= DAILY_GOAL) {
      current += 1;
      goalDays += 1;
      if (current > maxStreak) {
        maxStreak = current;
      }
    } else {
      current = 0;
    }
  }
  return [maxStreak, goalDays];
}

function goalRate(steps) {
  if (steps.length === 0) {
    return 0;
  }
  const [, goalDays] = streaks(steps);
  return goalDays / steps.length;
}

function formatReport(label, steps) {
  const [maxStreak, goalDays] = streaks(steps);
  const percent = (goalRate(steps) * 100).toFixed(1);
  const dayWord = goalDays === 1 ? 'day' : 'days';
  return `${label}: longest streak ${maxStreak}, goal met on ${goalDays} ${dayWord} (${percent}%)`;
}

function main() {
  const week = [9000, 11000, 12000, 8000];
  console.log(formatReport('Sample week', week));
  const fortnight = [10000, 10500, 9999, 15000, 14000, 13000, 100, 12000, 12000];
  console.log(formatReport('Fortnight', fortnight));
  const restWeek = [3000, 4500, 2000];
  console.log(formatReport('Rest week', restWeek));
  try {
    streaks([10000, -5]);
  } catch (err) {
    console.log(`Rejected input: ${err.message}`);
  }
}

main();

module.exports = { streaks, goalRate, formatReport, DAILY_GOAL };

