const DELTAS = {
  sunny: 2,
  cloudy: 1,
  rainy: -0.5,
};

function validateInitial(initial) {
  if (typeof initial !== 'number' || Number.isNaN(initial)) {
    throw new TypeError('initial height must be a number');
  }
  if (initial < 0) {
    throw new RangeError('initial height cannot be negative');
  }
  return initial;
}

function deltaFor(condition) {
  const key = String(condition).trim().toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(DELTAS, key)) {
    throw new Error(`unknown condition: ${condition}`);
  }
  return DELTAS[key];
}

function growth(initial, conditions) {
  let height = validateInitial(initial);
  const days = Array.isArray(conditions) ? conditions : [];
  for (const condition of days) {
    height += deltaFor(condition);
    if (height < 0) {
      height = 0;
    }
  }
  return height;
}

function formatHeight(height) {
  const rounded = Math.round(height * 100) / 100;
  return `${rounded} cm`;
}

function dailyLog(initial, conditions) {
  const entries = [];
  let height = validateInitial(initial);
  conditions.forEach((condition, index) => {
    height = growth(height, [condition]);
    entries.push(`Day ${index + 1} (${condition}): ${formatHeight(height)}`);
  });
  return entries;
}

function report(initial, conditions) {
  const lines = [`Start: ${formatHeight(initial)}`];
  lines.push(...dailyLog(initial, conditions));
  lines.push(`Final: ${formatHeight(growth(initial, conditions))}`);
  return lines.join('\n');
}

function main() {
  console.log(report(5, ['sunny', 'rainy']));
  console.log('---');
  console.log(report(1, ['rainy', 'rainy', 'rainy', 'cloudy']));
  console.log('---');
  console.log(report(0, ['sunny', 'cloudy', 'sunny', 'rainy', 'sunny']));
}

main();

module.exports = { growth, formatHeight, dailyLog, report };

