const INTERVALS = {
  1: 1,
  2: 1,
  3: 3,
  4: 7,
  5: 7,
};

function intervalForRating(rating) {
  if (!Number.isInteger(rating)) {
    throw new TypeError(`rating must be an integer, got ${rating}`);
  }
  const days = INTERVALS[rating];
  if (days === undefined) {
    throw new RangeError(`rating must be between 1 and 5, got ${rating}`);
  }
  return days;
}

function review(cards, ratings) {
  if (!Array.isArray(cards) || !Array.isArray(ratings)) {
    throw new TypeError('cards and ratings must both be arrays');
  }
  if (cards.length !== ratings.length) {
    throw new Error(`cards (${cards.length}) and ratings (${ratings.length}) must have equal length`);
  }
  const schedule = [];
  for (let i = 0; i < cards.length; i += 1) {
    const days = intervalForRating(ratings[i]);
    schedule.push([cards[i], days]);
  }
  return schedule;
}

function groupByInterval(schedule) {
  const groups = new Map();
  for (const [card, days] of schedule) {
    if (!groups.has(days)) {
      groups.set(days, []);
    }
    groups.get(days).push(card);
  }
  return groups;
}

function formatEntry(card, days) {
  const unit = days === 1 ? 'day' : 'days';
  return `${card} in ${days} ${unit}`;
}

function report(schedule) {
  const groups = groupByInterval(schedule);
  const intervals = [...groups.keys()].sort((a, b) => a - b);
  const lines = intervals.map((days) => {
    const cards = groups.get(days).join(', ');
    return `${String(days).padStart(2)}d: ${cards}`;
  });
  return lines.join('\n');
}

function main() {
  const cards = ['A', 'B', 'C', 'D', 'E'];
  const ratings = [2, 5, 3, 1, 4];
  const schedule = review(cards, ratings);
  for (const [card, days] of schedule) {
    console.log(formatEntry(card, days));
  }
  console.log('--- grouped ---');
  console.log(report(schedule));
  try {
    review(['X'], [6]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { review, intervalForRating, groupByInterval, formatEntry, report };

