const RATE = 2;
const DAILY_CAP = 15;

function validateTrips(trips) {
  if (!Array.isArray(trips)) {
    throw new TypeError('trips must be an array of zone distances');
  }
  trips.forEach((zones, index) => {
    if (!Number.isInteger(zones) || zones < 0) {
      throw new RangeError(`trip ${index + 1} has an invalid zone distance: ${zones}`);
    }
  });
  return trips;
}

function fare(trips) {
  validateTrips(trips);
  const costs = [];
  let spent = 0;
  for (const zones of trips) {
    const normal = zones * RATE;
    const remaining = DAILY_CAP - spent;
    const charged = normal > remaining ? remaining : normal;
    costs.push(charged);
    spent += charged;
  }
  return costs;
}

function totalFare(trips) {
  return fare(trips).reduce((sum, cost) => sum + cost, 0);
}

function capReachedAt(trips) {
  const costs = fare(trips);
  let spent = 0;
  for (let i = 0; i < costs.length; i += 1) {
    spent += costs[i];
    if (spent === DAILY_CAP) {
      return i + 1;
    }
  }
  return null;
}

function formatReport(trips) {
  const costs = fare(trips);
  const lines = costs.map((cost, i) => `  trip ${i + 1}: ${trips[i]} zone(s) -> ${cost} unit(s)`);
  lines.push(`  total: ${totalFare(trips)} unit(s)`);
  const capTrip = capReachedAt(trips);
  if (capTrip !== null) {
    lines.push(`  daily cap of ${DAILY_CAP} reached on trip ${capTrip}`);
  }
  return lines.join('\n');
}

function main() {
  const days = [
    [3, 2, 4],
    [1, 1, 1],
    [9, 4, 2, 5],
    [],
  ];
  days.forEach((trips, index) => {
    console.log(`Day ${index + 1} zones [${trips.join(', ')}]`);
    console.log(`  costs [${fare(trips).join(', ')}]`);
    console.log(formatReport(trips));
  });
  try {
    fare([2, -1]);
  } catch (err) {
    console.log(`Rejected input: ${err.message}`);
  }
}

main();

module.exports = { fare, totalFare, capReachedAt, formatReport };

