const SEATS_PER_ROW = 10;

function createTheater(rowCount) {
  if (!Number.isInteger(rowCount) || rowCount < 0) {
    throw new TypeError('rows must be a non-negative integer');
  }
  const theater = [];
  for (let row = 0; row < rowCount; row += 1) {
    theater.push(new Array(SEATS_PER_ROW).fill(false));
  }
  return theater;
}

function findOpening(row, size) {
  let run = 0;
  for (let seat = 0; seat < row.length; seat += 1) {
    if (row[seat]) {
      run = 0;
      continue;
    }
    run += 1;
    if (run === size) {
      return seat - size + 1;
    }
  }
  return -1;
}

function occupySeats(row, start, size) {
  for (let seat = start; seat < start + size; seat += 1) {
    row[seat] = true;
  }
}

function planSeating(rows, requests) {
  if (!Array.isArray(requests)) {
    throw new TypeError('requests must be an array of group sizes');
  }
  const theater = createTheater(rows);
  const plan = [];
  for (const size of requests) {
    if (!Number.isInteger(size) || size < 1) {
      throw new TypeError('each request must be a positive integer');
    }
    let seat = null;
    for (let row = 0; row < theater.length && seat === null; row += 1) {
      const start = findOpening(theater[row], size);
      if (start !== -1) {
        occupySeats(theater[row], start, size);
        seat = [row, start];
      }
    }
    plan.push({ size, seat });
  }
  return plan;
}

function reserve(rows, requests) {
  const plan = planSeating(rows, requests);
  return plan.filter((entry) => entry.seat !== null).map((entry) => entry.seat);
}

function describeEntry(entry) {
  if (entry.seat === null) {
    return `group of ${entry.size}: turned away`;
  }
  const [row, start] = entry.seat;
  return `group of ${entry.size}: row ${row + 1}, seats ${start + 1}-${start + entry.size}`;
}

function main() {
  const rows = 5;
  const requests = [3, 8, 4, 10, 2, 12];
  for (const entry of planSeating(rows, requests)) {
    console.log(describeEntry(entry));
  }
  console.log(JSON.stringify(reserve(rows, requests)));
}

main();

