function validateInput(tasks, workers) {
  if (!Array.isArray(tasks)) {
    throw new TypeError('tasks must be an array of durations');
  }
  if (!Number.isInteger(workers) || workers < 1) {
    throw new RangeError('workers must be a positive integer');
  }
  for (const duration of tasks) {
    if (typeof duration !== 'number' || !Number.isFinite(duration) || duration < 0) {
      throw new RangeError(`invalid task duration: ${duration}`);
    }
  }
}

function earliestWorker(completions) {
  let best = 0;
  for (let i = 1; i < completions.length; i += 1) {
    if (completions[i] < completions[best]) {
      best = i;
    }
  }
  return best;
}

function schedule(tasks, workers) {
  validateInput(tasks, workers);
  const completions = new Array(workers).fill(0);
  const assignments = Array.from({ length: workers }, () => []);
  for (const duration of tasks) {
    const index = earliestWorker(completions);
    const start = completions[index];
    completions[index] = start + duration;
    assignments[index].push({ duration, start, end: completions[index] });
  }
  return { completions, assignments };
}

function assemble(tasks, workers) {
  const { completions } = schedule(tasks, workers);
  return Math.max(...completions);
}

function formatReport(tasks, workers) {
  const { completions, assignments } = schedule(tasks, workers);
  const lines = [];
  assignments.forEach((jobs, index) => {
    const detail = jobs.map((job) => `${job.duration}min (${job.start}-${job.end})`).join(', ');
    lines.push(`Worker ${index + 1}: ${detail || 'idle'} | finishes at ${completions[index]}`);
  });
  lines.push(`Total assembly time: ${Math.max(...completions)} minutes`);
  return lines.join('\n');
}

function main() {
  const jobs = [10, 20, 15];
  console.log(formatReport(jobs, 2));
  console.log(assemble(jobs, 2));
  const bigBatch = [5, 8, 12, 3, 7, 20, 1];
  console.log(formatReport(bigBatch, 3));
  try {
    assemble(bigBatch, 0);
  } catch (err) {
    console.log(`Rejected: ${err.message}`);
  }
}

main();

module.exports = { assemble, schedule, formatReport };

