const PANEL_WATTS = 250;
const LOW_LIGHT_HOURS = 4;
const LOW_LIGHT_PENALTY = 0.1;

function roundHalfEven(value, digits) {
  const factor = 10 ** digits;
  const scaled = value * factor;
  const lower = Math.floor(scaled);
  const remainder = scaled - lower;
  if (remainder > 0.5) {
    return (lower + 1) / factor;
  }
  if (remainder < 0.5) {
    return lower / factor;
  }
  const even = lower % 2 === 0 ? lower : lower + 1;
  return even / factor;
}

function validateHours(hours) {
  if (typeof hours !== "number" || !Number.isFinite(hours)) {
    throw new TypeError("each sunlight entry must be a finite number of hours");
  }
  if (hours < 0 || hours > 24) {
    throw new RangeError("sunlight hours must lie between 0 and 24");
  }
  return hours;
}

function validateEfficiency(efficiency) {
  if (typeof efficiency !== "number" || !Number.isFinite(efficiency)) {
    throw new TypeError("efficiency must be a finite decimal");
  }
  if (efficiency <= 0 || efficiency > 1) {
    throw new RangeError("efficiency must be a decimal in the range (0, 1]");
  }
  return efficiency;
}

function dailyEfficiency(hours, efficiency) {
  if (hours < LOW_LIGHT_HOURS) {
    return efficiency - efficiency * LOW_LIGHT_PENALTY;
  }
  return efficiency;
}

function dailyWatts(hours, efficiency) {
  return hours * dailyEfficiency(hours, efficiency) * PANEL_WATTS;
}

function predict(sunlight, efficiency) {
  if (!Array.isArray(sunlight)) {
    throw new TypeError("sunlight must be a list of daily hour readings");
  }
  validateEfficiency(efficiency);
  let totalWatts = 0;
  for (const hours of sunlight) {
    validateHours(hours);
    totalWatts += dailyWatts(hours, efficiency);
  }
  return roundHalfEven(totalWatts / 1000, 2);
}

function report(sunlight, efficiency) {
  const kilowatts = predict(sunlight, efficiency);
  const lines = sunlight.map((hours, index) => {
    const applied = dailyEfficiency(hours, efficiency) * 100;
    const watts = dailyWatts(hours, efficiency);
    return `Day ${index + 1}: ${hours.toFixed(1)} h at ${applied.toFixed(2)}% -> ${watts.toFixed(2)} W`;
  });
  lines.push(`Period total: ${kilowatts.toFixed(2)} kW`);
  return lines.join("\n");
}

console.log(predict([3, 5], 0.2));
console.log(report([2, 4.5, 6, 3.5, 7], 0.18));

