'use strict';

function validateInputs(crops, rainfall) {
  if (!Array.isArray(crops)) {
    throw new TypeError('crops must be an array of gallon requirements');
  }
  if (typeof rainfall !== 'number' || !Number.isFinite(rainfall)) {
    throw new TypeError('rainfall must be a finite number of gallons');
  }
  if (rainfall < 0) {
    throw new RangeError('rainfall cannot be negative');
  }
  crops.forEach(function (need, index) {
    if (typeof need !== 'number' || !Number.isFinite(need)) {
      throw new TypeError('crop ' + index + ' has a non-numeric requirement');
    }
    if (need < 0) {
      throw new RangeError('crop ' + index + ' has a negative requirement');
    }
  });
}

const EVAPORATION_FACTOR = 1.1;

function pumpedForCrop(need, rainfall) {
  const deficit = need - rainfall;
  if (deficit <= 0) {
    return 0;
  }
  return deficit * EVAPORATION_FACTOR;
}

function irrigate(crops, rainfall) {
  validateInputs(crops, rainfall);
  let total = 0;
  for (const need of crops) {
    total += pumpedForCrop(need, rainfall);
  }
  return Math.ceil(total);
}

function irrigationPlan(crops, rainfall) {
  validateInputs(crops, rainfall);
  const rows = crops.map(function (need, index) {
    const pumped = pumpedForCrop(need, rainfall);
    return { crop: index + 1, required: need, pumped: pumped };
  });
  return { rows: rows, total: irrigate(crops, rainfall) };
}

function formatPlan(plan) {
  const lines = plan.rows.map(function (row) {
    if (row.pumped === 0) {
      return 'Crop ' + row.crop + ': needs ' + row.required + ' gal, rainfall covers it';
    }
    return 'Crop ' + row.crop + ': needs ' + row.required + ' gal, pump ' + row.pumped.toFixed(1) + ' gal';
  });
  lines.push('Total to pump: ' + plan.total + ' gal');
  return lines.join('\n');
}

