function manhattan(a, b) {
  return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
}

function validatePoint(point, label) {
  if (!Array.isArray(point) || point.length !== 2) {
    throw new TypeError(label + ' must be a list of two numbers');
  }
  const [x, y] = point;
  if (typeof x !== 'number' || typeof y !== 'number' || !isFinite(x) || !isFinite(y)) {
    throw new TypeError(label + ' must contain finite numbers');
  }
  return [x, y];
}

function nearestIndex(current, deliveries, visited) {
  let best = -1;
  let bestDistance = Infinity;
  for (let i = 0; i < deliveries.length; i += 1) {
    if (visited[i]) {
      continue;
    }
    const distance = manhattan(current, deliveries[i]);
    if (distance < bestDistance) {
      bestDistance = distance;
      best = i;
    }
  }
  return best;
}

function plan(deliveries, start) {
  const origin = validatePoint(start, 'start');
  const stops = deliveries.map((point, i) => validatePoint(point, 'delivery ' + i));
  const visited = new Array(stops.length).fill(false);
  const order = [];
  let current = origin;
  let total = 0;
  for (let step = 0; step < stops.length; step += 1) {
    const next = nearestIndex(current, stops, visited);
    visited[next] = true;
    total += manhattan(current, stops[next]);
    current = stops[next];
    order.push(stops[next]);
  }
  total += manhattan(current, origin);
  order.push(origin);
  return { order, total };
}

function route(deliveries, start) {
  return plan(deliveries, start).total;
}

function describe(deliveries, start) {
  const result = plan(deliveries, start);
  const labels = [start].concat(result.order).map((p) => '(' + p[0] + ',' + p[1] + ')');
  return labels.join(' -> ') + ' = ' + result.total;
}

const parcels = [[1, 1], [2, 2]];
const depot = [0, 0];
console.log(route(parcels, depot));
console.log(describe(parcels, depot));
console.log(describe([[4, 0], [0, 4], [2, 2], [-3, 1]], depot));
console.log(route([], depot));

module.exports = { route, manhattan, describe };

