function parseTracks(text) {
  const parts = text.split(',');
  const tracks = [];
  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed.length === 0) {
      continue;
    }
    const value = Number(trimmed);
    if (!Number.isFinite(value)) {
      throw new Error(`invalid track duration: "${trimmed}"`);
    }
    tracks.push(value);
  }
  return tracks;
}

function measure(tracks, speed) {
  if (!Array.isArray(tracks)) {
    throw new TypeError('tracks must be an array of durations in seconds');
  }
  if (!Number.isFinite(speed) || speed <= 0) {
    throw new RangeError('speed must be a positive decimal multiplier');
  }
  let total = 0;
  for (const duration of tracks) {
    if (!Number.isFinite(duration) || duration < 0) {
      throw new RangeError(`track duration out of range: ${duration}`);
    }
    total += duration / speed;
  }
  if (tracks.length > 1) {
    total += 2 * (tracks.length - 1);
  }
  const minutes = Math.floor(total / 60);
  const seconds = Math.floor(total - minutes * 60);
  return [minutes, seconds];
}

function formatRuntime(runtime) {
  const [minutes, seconds] = runtime;
  const padded = String(seconds).padStart(2, '0');
  return `${minutes}:${padded}`;
}

function report(text, speed) {
  const tracks = parseTracks(text);
  const runtime = measure(tracks, speed);
  const label = `${tracks.length} track(s) at ${speed}x`;
  return `${label} -> ${formatRuntime(runtime)} (${runtime[0]} min, ${runtime[1]} s)`;
}

function main() {
  const records = [
    ['120, 120', 1.5],
    ['200, 200, 200, 200', 1],
    ['180, 240, 195, 210, 175', 1.25],
    ['300', 0.75],
  ];
  for (const [text, speed] of records) {
    console.log(report(text, speed));
  }
  try {
    console.log(report('180, fast', 1));
  } catch (err) {
    console.error(`skipped record: ${err.message}`);
  }
}

main();

module.exports = { measure, parseTracks, formatRuntime, report };

