function validateScores(systems) {
  if (!Array.isArray(systems)) {
    throw new TypeError('systems must be an array of scores');
  }
  if (systems.length === 0) {
    throw new RangeError('systems must contain at least one score');
  }
  for (const score of systems) {
    if (typeof score !== 'number' || Number.isNaN(score)) {
      throw new TypeError(`invalid score: ${score}`);
    }
    if (score < 0 || score > 100) {
      throw new RangeError(`score out of range 0..100: ${score}`);
    }
  }
  return systems;
}

function validateThreshold(threshold) {
  if (typeof threshold !== 'number' || Number.isNaN(threshold)) {
    throw new TypeError('threshold must be a number');
  }
  if (threshold < 0 || threshold > 100) {
    throw new RangeError(`threshold out of range 0..100: ${threshold}`);
  }
  return threshold;
}

function average(values) {
  const total = values.reduce((sum, value) => sum + value, 0);
  return total / values.length;
}

function verify(systems, threshold) {
  validateScores(systems);
  validateThreshold(threshold);
  const failing = systems.filter((score) => score < threshold);
  if (failing.length === 0) {
    return 'go';
  }
  if (failing.length > 1) {
    return 'abort';
  }
  const anomaly = failing[0];
  if (threshold - anomaly > 5) {
    return 'abort';
  }
  const others = systems.filter((score) => score >= threshold);
  if (others.length === 0) {
    return 'abort';
  }
  return average(others) >= 90 ? 'go' : 'abort';
}

function report(systems, threshold) {
  const decision = verify(systems, threshold);
  const scores = systems.join(', ');
  return `[${scores}] @ ${threshold} -> ${decision.toUpperCase()}`;
}

function main() {
  const runs = [
    { systems: [95, 92, 86], threshold: 90 },
    { systems: [95, 92, 80], threshold: 90 },
    { systems: [88, 89, 97], threshold: 90 },
    { systems: [100, 99, 98], threshold: 95 },
    { systems: [91, 85, 87], threshold: 90 },
  ];
  for (const run of runs) {
    console.log(report(run.systems, run.threshold));
  }
}

main();

module.exports = { verify, report, average, validateScores, validateThreshold };

