      throw new TypeError(`invalid wind speed: ${speed}`)
    }
    if (speed < 0) {
      throw new RangeError(`wind speed cannot be negative: ${speed}`)
    }
  }
  if (typeof hours !== 'number' || !(hours > 0)) {
    throw new RangeError('hours must be a positive number')
  }
}

function spin(speeds, hours) {
  validate(speeds, hours)
  const intervalMinutes = (hours * 60) / speeds.length
  let revolutions = 0
  for (const speed of speeds) {
    revolutions += rpmFor(speed) * intervalMinutes
  }
  return revolutions
}

function describe(speeds, hours) {
  validate(speeds, hours)
  const intervalMinutes = (hours * 60) / speeds.length
  const lines = []
  speeds.forEach((speed, index) => {
    const rpm = rpmFor(speed)
    let state = 'spinning'
    if (rpm === 0 && speed > 25) {
      state = 'braked'
    } else if (rpm === 0) {
      state = 'stationary'
    }
    const turns = rpm * intervalMinutes
    lines.push(`interval ${index + 1}: ${speed} mph -> ${state}, ${turns} revolutions`)
  })
  lines.push(`total over ${hours} h: ${spin(speeds, hours)} revolutions`)
  return lines.join('\n')
}

