function validateResults(results, players) {
  if (!Number.isInteger(players) || players < 0) {
    throw new RangeError('players must be a non-negative integer');
  }
  for (const result of results) {
    if (!Array.isArray(result) || result.length !== 3) {
      throw new TypeError('each result must be [first, second, outcome]');
    }
    const [first, second, outcome] = result;
    if (!Number.isInteger(first) || first < 0 || first >= players) {
      throw new RangeError(`invalid first player index: ${first}`);
    }
    if (!Number.isInteger(second) || second < 0 || second >= players) {
      throw new RangeError(`invalid second player index: ${second}`);
    }
    if (outcome !== 0 && outcome !== 0.5 && outcome !== 1) {
      throw new RangeError(`invalid outcome: ${outcome}`);
    }
  }
}

function tally(results, players) {
  const points = new Array(players).fill(0);
  for (const [first, second, outcome] of results) {
    points[first] += outcome;
    points[second] += 1 - outcome;
  }
  return points;
}

function rank(results, players) {
  validateResults(results, players);
  const points = tally(results, players);
  const order = points.map((_, index) => index);
  order.sort((a, b) => points[b] - points[a] || a - b);
  return order;
}

function standings(results, players) {
  const points = tally(results, players);
  const order = rank(results, players);
  const rows = [];
  let place = 0;
  let previous = null;
  order.forEach((player, position) => {
    if (points[player] !== previous) {
      place = position + 1;
      previous = points[player];
    }
    rows.push({ place, player, points: points[player] });
  });
  return rows;
}

function formatStandings(rows) {
  const lines = rows.map((row) => {
    const score = Number.isInteger(row.points) ? `${row.points}` : row.points.toFixed(1);
    return `${row.place}. player ${row.player} — ${score}`;
  });
  return lines.join('\n');
}

