const BASELINE_SPEED = 1500;
const REFERENCE_SALINITY = 35;
const SPEED_PER_PERCENT = 3;

function speedOfSound(salinity) {
  if (typeof salinity !== "number" || Number.isNaN(salinity)) {
    throw new TypeError("salinity must be a number");
  }
  const excess = salinity - REFERENCE_SALINITY;
  return BASELINE_SPEED + excess * SPEED_PER_PERCENT;
}

function depth(pings, salinity) {
  if (!Array.isArray(pings)) {
    throw new TypeError("pings must be an array of round-trip times");
  }
  const speed = speedOfSound(salinity);
  return pings.map(function (ping) {
    if (typeof ping !== "number" || Number.isNaN(ping) || ping < 0) {
      throw new RangeError("each ping must be a non-negative number of seconds");
    }
    const oneWayTime = ping / 2;
    return Math.round(speed * oneWayTime);
  });
}

function profileStats(depths) {
  if (depths.length === 0) {
    return { count: 0, shallowest: null, deepest: null, mean: null };
  }
  let total = 0;
  let shallowest = depths[0];
  let deepest = depths[0];
  for (const value of depths) {
    total += value;
    if (value < shallowest) {
      shallowest = value;
    }
    if (value > deepest) {
      deepest = value;
    }
  }
  return {
    count: depths.length,
    shallowest: shallowest,
    deepest: deepest,
    mean: Math.round(total / depths.length),
  };
}

function formatSurvey(pings, salinity) {
  const depths = depth(pings, salinity);
  const stats = profileStats(depths);
  const lines = [];
  lines.push("Speed of sound: " + speedOfSound(salinity) + " m/s");
  depths.forEach(function (value, index) {
    lines.push("  ping " + (index + 1) + ": " + pings[index] + " s -> " + value + " m");
  });
  if (stats.count === 0) {
    lines.push("No pings recorded.");
  } else {
    lines.push("Range: " + stats.shallowest + " m to " + stats.deepest + " m, mean " + stats.mean + " m");
  }
  return lines.join("\n");
}

function main() {
  console.log(depth([2, 4], 40).join(", "));
  console.log(formatSurvey([1.5, 2, 3.25, 4], 38));
  console.log(formatSurvey([0.8, 0.8, 1.2], 35));
}

main();

