function arrowScore(distance, width) {
  const ringIndex = Math.floor(distance / width);
  const points = 10 - ringIndex;
  if (points < 0) {
    return 0;
  }
  return points;
}

function validateInput(distances, width) {
  if (!Array.isArray(distances)) {
    throw new TypeError('distances must be an array of numbers');
  }
  if (typeof width !== 'number' || !Number.isFinite(width) || width <= 0) {
    throw new RangeError('width must be a positive finite number');
  }
  for (const distance of distances) {
    if (typeof distance !== 'number' || !Number.isFinite(distance) || distance < 0) {
      throw new RangeError(`invalid distance: ${distance}`);
    }
  }
}

function score(distances, width) {
  validateInput(distances, width);
  let total = 0;
  for (const distance of distances) {
    total += arrowScore(distance, width);
  }
  return total;
}

function breakdown(distances, width) {
  validateInput(distances, width);
  return distances.map(function (distance) {
    const points = arrowScore(distance, width);
    const ring = points > 0 ? String(11 - points) : 'miss';
    return { distance: distance, ring: ring, points: points };
  });
}

function formatRound(distances, width) {
  const rows = breakdown(distances, width);
  const lines = rows.map(function (row) {
    const where = row.points > 0 ? `ring ${row.ring}` : 'off target';
    return `  ${row.distance.toFixed(1)} cm -> ${where}: ${row.points} pts`;
  });
  lines.push(`  total: ${score(distances, width)} pts`);
  return lines.join('\n');
}

function main() {
  const rounds = [
    { distances: [1.5, 4.0, 25.0], width: 2 },
    { distances: [0.0, 9.9, 10.0, 19.9], width: 1 },
    { distances: [12.5, 3.3, 7.0], width: 2.5 }
  ];
  rounds.forEach(function (round, index) {
    console.log(`Round ${index + 1} (ring width ${round.width} cm):`);
    console.log(formatRound(round.distances, round.width));
  });
  const grand = rounds.reduce(function (sum, round) {
    return sum + score(round.distances, round.width);
  }, 0);
  console.log(`Grand total: ${grand} pts`);
}

main();

module.exports = { score, arrowScore, breakdown, formatRound };

