const HEAT_RATE = 100;
const COOL_RATE = 50;
const HOLD_HOURS = 2;

function validateStages(stages) {
  if (!Array.isArray(stages)) {
    throw new TypeError('stages must be an array of target temperatures');
  }
  for (const target of stages) {
    if (typeof target !== 'number' || !Number.isFinite(target)) {
      throw new TypeError(`invalid target temperature: ${target}`);
    }
  }
}

function transitionHours(from, to) {
  const delta = to - from;
  if (delta > 0) {
    return delta / HEAT_RATE;
  }
  return -delta / COOL_RATE;
}

function fire(stages, ambient) {
  validateStages(stages);
  if (typeof ambient !== 'number' || !Number.isFinite(ambient)) {
    throw new TypeError(`invalid ambient temperature: ${ambient}`);
  }
  let current = ambient;
  let total = 0;
  for (const target of stages) {
    total += transitionHours(current, target);
    total += HOLD_HOURS;
    current = target;
  }
  return total;
}

function schedule(stages, ambient) {
  validateStages(stages);
  const rows = [];
  let current = ambient;
  let clock = 0;
  for (const target of stages) {
    const ramp = transitionHours(current, target);
    const mode = target > current ? 'heat' : 'cool';
    clock += ramp;
    const reached = clock;
    clock += HOLD_HOURS;
    rows.push({ target, mode, ramp, reached, done: clock });
    current = target;
  }
  return rows;
}

function formatSchedule(stages, ambient) {
  const lines = [`ambient: ${ambient}\u00b0`];
  for (const row of schedule(stages, ambient)) {
    const ramp = row.ramp.toFixed(2);
    lines.push(
      `${row.mode} to ${row.target}\u00b0 in ${ramp}h, reached at ${row.reached.toFixed(2)}h, ` +
      `held until ${row.done.toFixed(2)}h`
    );
  }
  lines.push(`total: ${fire(stages, ambient).toFixed(2)}h`);
  return lines.join('\n');
}

const bisqueStages = [200, 100];
console.log(formatSchedule(bisqueStages, 0));
console.log(fire(bisqueStages, 0));

const glazeStages = [600, 1250, 900];
console.log(formatSchedule(glazeStages, 20));
console.log(fire(glazeStages, 20));

