const YIELD_RATES = { sunny: 1 / 100, cloudy: 0.5 / 100, rain: -1 / 500 };

function totalBees(hives) {
  if (!Array.isArray(hives)) {
    throw new TypeError('hives must be an array of bee populations');
  }
  let total = 0;
  for (const population of hives) {
    if (typeof population !== 'number' || !Number.isFinite(population) || population < 0) {
      throw new RangeError(`invalid hive population: ${population}`);
    }
    total += population;
  }
  return total;
}

function normalizeWeather(weather) {
  if (!Array.isArray(weather)) {
    throw new TypeError('weather must be an array of condition words');
  }
  return weather.map((day) => {
    const condition = String(day).trim().toLowerCase();
    if (!Object.prototype.hasOwnProperty.call(YIELD_RATES, condition)) {
      throw new RangeError(`unknown weather condition: ${day}`);
    }
    return condition;
  });
}

function harvest(hives, weather) {
  const bees = totalBees(hives);
  const days = normalizeWeather(weather);
  let reserves = 0;
  for (const condition of days) {
    reserves += bees * YIELD_RATES[condition];
  }
  return reserves < 0 ? 0 : reserves;
}

function dailyLog(hives, weather) {
  const bees = totalBees(hives);
  const days = normalizeWeather(weather);
  let reserves = 0;
  return days.map((condition, index) => {
    const change = bees * YIELD_RATES[condition];
    reserves += change;
    return { day: index + 1, condition, change, reserves };
  });
}

function formatReport(hives, weather) {
  const bees = totalBees(hives);
  const lines = [`Apiary of ${hives.length} hive(s), ${bees} bees total`];
  for (const entry of dailyLog(hives, weather)) {
    const sign = entry.change < 0 ? '' : '+';
    lines.push(
      `Day ${entry.day} (${entry.condition}): ${sign}${entry.change.toFixed(2)} g` +
        ` -> running ${entry.reserves.toFixed(2)} g`
    );
  }
  lines.push(`Net harvest: ${harvest(hives, weather).toFixed(2)} g`);
  return lines.join('\n');
}

function main() {
  console.log(formatReport([1000, 2000], ['sunny', 'rain']));
  console.log('');
  console.log(formatReport([500, 500, 1200], ['cloudy', 'sunny', 'rain', 'rain']));
  console.log('');
  console.log(formatReport([800], ['rain', 'rain']));
}

main();

module.exports = { harvest, totalBees, dailyLog, formatReport };

