function validateInput(arrivals, capacity) {
  if (!Array.isArray(arrivals)) {
    throw new TypeError('arrivals must be an array of guest counts');
  }
  arrivals.forEach((count, minute) => {
    if (!Number.isInteger(count) || count < 0) {
      throw new RangeError(`arrival at minute ${minute + 1} must be a non-negative integer`);
    }
  });
  if (!Number.isInteger(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive integer');
  }
}

function queue(arrivals, capacity) {
  validateInput(arrivals, capacity);
  let line = 0;
  let maxLine = 0;
  let minutes = 0;
  while (minutes < arrivals.length || line > 0) {
    const arriving = minutes < arrivals.length ? arrivals[minutes] : 0;
    line += arriving;
    line -= Math.min(capacity, line);
    minutes += 1;
    if (line > maxLine) {
      maxLine = line;
    }
  }
  return [maxLine, minutes];
}

function minuteByMinute(arrivals, capacity) {
  validateInput(arrivals, capacity);
  const history = [];
  let line = 0;
  for (let minute = 0; minute < arrivals.length || line > 0; minute += 1) {
    const arriving = minute < arrivals.length ? arrivals[minute] : 0;
    line += arriving;
    const served = Math.min(capacity, line);
    line -= served;
    history.push({ minute: minute + 1, arriving, served, waiting: line });
  }
  return history;
}

function formatReport(arrivals, capacity) {
  const [maxLine, minutes] = queue(arrivals, capacity);
  const lines = [`arrivals: [${arrivals.join(', ')}]  capacity: ${capacity}/min`];
  minuteByMinute(arrivals, capacity).forEach((row) => {
    const label = `minute ${String(row.minute).padStart(2, ' ')}`;
    lines.push(`${label}: +${row.arriving} arrived, -${row.served} served, ${row.waiting} waiting`);
  });
  lines.push(`peak line: ${maxLine} guests, cleared after ${minutes} minutes`);
  return lines.join('\n');
}

