const CAR_CAPACITY = 100;

function validate(weights) {
  if (!Array.isArray(weights)) {
    throw new TypeError('weights must be an array of numbers');
  }
  weights.forEach(function (weight, index) {
    if (typeof weight !== 'number' || Number.isNaN(weight)) {
      throw new TypeError('crate ' + index + ' is not a number');
    }
    if (weight <= 0 || weight > CAR_CAPACITY) {
      throw new RangeError('crate ' + index + ' has invalid weight ' + weight);
    }
  });
  return weights;
}

function loadCars(weights) {
  const cars = [];
  let current = [];
  let load = 0;
  validate(weights).forEach(function (weight) {
    if (load + weight > CAR_CAPACITY) {
      cars.push(current);
      current = [];
      load = 0;
    }
    current.push(weight);
    load += weight;
  });
  if (current.length > 0) {
    cars.push(current);
  }
  return cars;
}

function plan(weights) {
  return loadCars(weights).length;
}

function carLoad(car) {
  return car.reduce(function (sum, weight) {
    return sum + weight;
  }, 0);
}

function describe(weights) {
  const cars = loadCars(weights);
  const lines = cars.map(function (car, index) {
    const load = carLoad(car);
    const free = CAR_CAPACITY - load;
    return 'Car ' + (index + 1) + ': [' + car.join(', ') + '] = ' + load + ' used, ' + free + ' free';
  });
  lines.push('Total cars needed: ' + cars.length);
  return lines.join('\n');
}

function main() {
  const shipments = [
    [50, 60, 40, 30],
    [100, 1, 99, 2],
    [10, 10, 10, 10, 10],
    []
  ];
  shipments.forEach(function (shipment) {
    console.log('Crates: [' + shipment.join(', ') + '] -> ' + plan(shipment) + ' car(s)');
    if (shipment.length > 0) {
      console.log(describe(shipment));
    }
  });
  try {
    plan([20, 150]);
  } catch (error) {
    console.log('Rejected shipment: ' + error.message);
  }
}

main();

