function validateDownloads(downloads) {
  if (!Array.isArray(downloads)) {
    throw new TypeError('downloads must be an array of daily counts');
  }
  if (downloads.length === 0) {
    throw new RangeError('downloads must contain at least one day');
  }
  const cleaned = downloads.map((value, index) => {
    const count = Number(value);
    if (!Number.isFinite(count) || count < 0) {
      throw new RangeError(`day ${index + 1} has an invalid download count: ${value}`);
    }
    return Math.trunc(count);
  });
  return cleaned;
}

function track(downloads) {
  const days = validateDownloads(downloads);
  let max = days[0];
  let min = days[0];
  let sum = 0;
  for (const count of days) {
    if (count > max) {
      max = count;
    }
    if (count < min) {
      min = count;
    }
    sum += count;
  }
  const average = Math.floor(sum / days.length);
  return [max, min, average];
}

function trendDirection(downloads) {
  const days = validateDownloads(downloads);
  const first = days[0];
  const last = days[days.length - 1];
  if (last > first) {
    return 'rising';
  }
  if (last < first) {
    return 'falling';
  }
  return 'flat';
}

function report(name, downloads) {
  const [max, min, average] = track(downloads);
  const trend = trendDirection(downloads);
  const lines = [
    `Podcast: ${name}`,
    `Days tracked: ${downloads.length}`,
    `Peak day: ${max} downloads`,
    `Quietest day: ${min} downloads`,
    `Average per day: ${average} downloads`,
    `Trend: ${trend}`,
  ];
  return lines.join('\n');
}

