function validatePercentages(percentages) {
  if (!Array.isArray(percentages)) {
    throw new TypeError('percentages must be an array of numbers');
  }
  return percentages.map((value, index) => {
    const drain = Number(value);
    if (!Number.isFinite(drain) || drain < 0) {
      throw new RangeError(`invalid drain at index ${index}: ${value}`);
    }
    return drain;
  });
}

function estimate(percentages) {
  const drains = validatePercentages(percentages);
  let level = 100;
  let warnings = 0;
  for (const drain of drains) {
    level -= drain;
    if (level <= 0) {
      level = 0;
      break;
    }
    if (level <= 20) {
      warnings += 1;
    }
  }
  return [level, warnings];
}

function describe(percentages) {
  const [level, warnings] = estimate(percentages);
  const consumed = percentages.reduce((sum, drain) => sum + Number(drain), 0);
  const parts = [
    `drains: ${percentages.join(', ') || 'none'}`,
    `requested: ${consumed}%`,
    `remaining: ${level}%`,
    `warnings: ${warnings}`,
  ];
  if (level === 0) {
    parts.push('status: depleted');
  } else if (warnings > 0) {
    parts.push('status: critical');
  } else {
    parts.push('status: healthy');
  }
  return parts.join(' | ');
}

function safestOrder(percentages) {
  const sorted = validatePercentages(percentages).slice().sort((a, b) => a - b);
  const [, warnings] = estimate(sorted);
  return { order: sorted, warnings };
}

function main() {
  const days = [
    [30, 60, 15],
    [5, 10, 20, 25],
    [70, 12, 3],
    [],
  ];
  for (const day of days) {
    console.log(describe(day));
  }
  const heavy = [45, 25, 18, 7];
  const best = safestOrder(heavy);
  console.log(`reordering ${heavy.join(', ')} -> ${best.order.join(', ')}`);
  console.log(`warnings after reordering: ${best.warnings}`);
  console.log(`direct result: ${JSON.stringify(estimate(heavy))}`);
}

main();

module.exports = { estimate, describe, safestOrder };

