const TARGET_PACE = 5;

function validateSplits(splits) {
  if (!Array.isArray(splits)) {
    throw new TypeError('splits must be an array of split times');
  }
  const cleaned = [];
  for (const split of splits) {
    const value = typeof split === 'string' ? parseSplit(split) : split;
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError(`invalid split time: ${String(split)}`);
    }
    if (value <= 0) {
      throw new RangeError(`split time must be positive: ${value}`);
    }
    cleaned.push(value);
  }
  return cleaned;
}

function parseSplit(text) {
  const parts = text.trim().split(':');
  if (parts.length === 1) {
    return Number(parts[0]);
  }
  const minutes = Number(parts[0]);
  const seconds = Number(parts[1]);
  if (Number.isNaN(minutes) || Number.isNaN(seconds)) {
    return NaN;
  }
  return minutes + seconds / 60;
}

function pace(splits) {
  const times = validateSplits(splits);
  let fast = 0;
  let onPace = 0;
  let slow = 0;
  for (const time of times) {
    if (time < TARGET_PACE) {
      fast += 1;
    } else if (time === TARGET_PACE) {
      onPace += 1;
    } else {
      slow += 1;
    }
  }
  return [fast, onPace, slow];
}

function formatReport(splits) {
  const [fast, onPace, slow] = pace(splits);
  const total = fast + onPace + slow;
  const kept = fast + onPace;
  const share = total === 0 ? 0 : (kept / total) * 100;
  return `${total} km: ${fast} fast, ${onPace} on pace, ${slow} slow (${share.toFixed(1)}% at target)`;
}

function main() {
  const sessions = [
    [4, 5, 6, 4],
    ['4:30', '5:00', '5:15', '4:45', '5:00'],
    [],
  ];
  for (const session of sessions) {
    console.log(formatReport(session));
  }
  try {
    pace([5, -1]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

