const WORDS_PER_MINUTE = 250;

function validateChapters(words) {
  if (!Array.isArray(words)) {
    throw new TypeError('chapter list must be an array');
  }
  const cleaned = [];
  for (let i = 0; i < words.length; i += 1) {
    const count = words[i];
    if (typeof count !== 'number' || !Number.isFinite(count)) {
      throw new TypeError(`chapter ${i + 1} has a non-numeric word count`);
    }
    if (count < 0) {
      throw new RangeError(`chapter ${i + 1} has a negative word count`);
    }
    cleaned.push(count);
  }
  return cleaned;
}

function chapterTime(wordCount) {
  return Math.ceil(wordCount / WORDS_PER_MINUTE);
}

function read(words) {
  const chapters = validateChapters(words);
  let total = 0;
  for (const count of chapters) {
    total += chapterTime(count);
  }
  return total;
}

function formatDuration(minutes) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours === 0) {
    return `${rest} min`;
  }
  return `${hours} h ${rest} min`;
}

function report(title, words) {
  const chapters = validateChapters(words);
  const lines = [`${title} (${chapters.length} chapters)`];
  chapters.forEach((count, index) => {
    const minutes = chapterTime(count);
    lines.push(`  Chapter ${index + 1}: ${count} words -> ${minutes} min`);
  });
  const total = read(chapters);
  lines.push(`  Total: ${total} min (${formatDuration(total)})`);
  return lines.join('\n');
}

function main() {
  console.log(read([250, 501]));
  console.log(report('Short Story', [250, 501]));
  console.log(report('Novel', [4200, 3800, 5100, 2750, 6300]));
  try {
    read([300, -10]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { read, chapterTime, formatDuration, report, validateChapters };

