const PELLETS_BY_SIZE = {
  1: 2,
  2: 5,
  3: 10,
};

const FISH_PER_SET = 5;
const WASTE_PELLETS_PER_SET = 3;

function sizeName(size) {
  const names = { 1: 'small', 2: 'medium', 3: 'large' };
  return names[size];
}

function validateSizes(fishes) {
  if (!Array.isArray(fishes)) {
    throw new TypeError('fishes must be an array of fish sizes');
  }
  fishes.forEach((size, index) => {
    if (!Object.prototype.hasOwnProperty.call(PELLETS_BY_SIZE, size)) {
      throw new RangeError(`fish at index ${index} has invalid size: ${size}`);
    }
  });
}

function pelletsForFish(size) {
  return PELLETS_BY_SIZE[size];
}

function wastePellets(count) {
  const completeSets = Math.floor(count / FISH_PER_SET);
  return completeSets * WASTE_PELLETS_PER_SET;
}

function feed(fishes) {
  validateSizes(fishes);
  let total = 0;
  for (const size of fishes) {
    total += pelletsForFish(size);
  }
  return total + wastePellets(fishes.length);
}

function countBySize(fishes) {
  const counts = { 1: 0, 2: 0, 3: 0 };
  for (const size of fishes) {
    counts[size] += 1;
  }
  return counts;
}

