    if (many > 0) {
      lines.push(`${many} ${sizeName(size)} fish -> ${many * pelletsForFish(size)} pellets`);
    }
  }
  const waste = wastePellets(fishes.length);
  if (waste > 0) {
    lines.push(`waste allowance -> ${waste} pellets`);
  }
  lines.push(`total -> ${feed(fishes)} pellets`);
  return lines.join('\n');
}

