function validateTeeth(teeth) {
  if (!Array.isArray(teeth)) {
    throw new TypeError('gear expects an array of tooth counts');
  }
  if (teeth.length % 2 !== 0) {
    throw new RangeError('tooth counts must alternate front/rear in pairs');
  }
  for (const count of teeth) {
    if (typeof count !== 'number' || !Number.isFinite(count) || count <= 0) {
      throw new RangeError(`invalid tooth count: ${count}`);
    }
  }
  return teeth;
}

function ratioOf(front, rear) {
  return Math.floor(front / rear);
}

function gear(teeth) {
  validateTeeth(teeth);
  let hard = 0;
  let easy = 0;
  for (let i = 0; i < teeth.length; i += 2) {
    const ratio = ratioOf(teeth[i], teeth[i + 1]);
    if (ratio >= 3) {
      hard += 1;
    } else if (ratio <= 1) {
      easy += 1;
    }
  }
  return [hard, easy];
}

function describePairs(teeth) {
  validateTeeth(teeth);
  const lines = [];
  for (let i = 0; i < teeth.length; i += 2) {
    const front = teeth[i];
    const rear = teeth[i + 1];
    const ratio = ratioOf(front, rear);
    let label = 'normal';
    if (ratio >= 3) {
      label = 'hard';
    } else if (ratio <= 1) {
      label = 'easy';
    }
    lines.push(`${front}/${rear} -> ratio ${ratio} (${label})`);
  }
  return lines;
}

function report(teeth) {
  const [hard, easy] = gear(teeth);
  const body = describePairs(teeth).join('\n');
  return `${body}\nhard: ${hard}, easy: ${easy}`;
}

function main() {
  const drivetrains = [
    [50, 15, 30, 30],
    [40, 20, 52, 11, 34, 34, 48, 12],
  ];
  for (const teeth of drivetrains) {
    console.log(report(teeth));
    console.log('---');
  }
  try {
    gear([50, 15, 30]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { gear, describePairs, report };

