function classifyNight(cover) {
  if (cover < 10) {
    return 'excellent';
  }
  if (cover <= 30) {
    return 'acceptable';
  }
  return 'poor';
}

function parseCover(value) {
  const cover = typeof value === 'string' ? Number(value.trim()) : value;
  if (typeof cover !== 'number' || Number.isNaN(cover)) {
    throw new TypeError(`cloud cover must be numeric, got ${JSON.stringify(value)}`);
  }
  if (cover < 0 || cover > 100) {
    throw new RangeError(`cloud cover must be a percentage in 0..100, got ${cover}`);
  }
  return cover;
}

function schedule(clouds) {
  if (!Array.isArray(clouds)) {
    throw new TypeError('schedule expects a list of cloud cover percentages');
  }
  let longestExcellent = 0;
  let currentExcellent = 0;
  let acceptableCount = 0;
  for (const raw of clouds) {
    const cover = parseCover(raw);
    const kind = classifyNight(cover);
    if (kind === 'excellent') {
      currentExcellent += 1;
      if (currentExcellent > longestExcellent) {
        longestExcellent = currentExcellent;
      }
    } else {
      currentExcellent = 0;
    }
    if (kind === 'acceptable') {
      acceptableCount += 1;
    }
  }
  return [longestExcellent, acceptableCount];
}

function describe(clouds) {
  const [streak, acceptable] = schedule(clouds);
  const nights = clouds.map((raw, index) => `night ${index + 1}: ${classifyNight(parseCover(raw))}`);
  const lines = nights.slice();
  lines.push(`longest excellent streak: ${streak}`);
  lines.push(`acceptable nights: ${acceptable}`);
  return lines.join('\n');
}

function main() {
  const season = [5, 5, 15, 40, 5];
  console.log(describe(season));
  console.log(schedule(season).join(', '));
  const cloudy = [55, 60, 31, 30, 10, 9, 8, 7, 80];
  console.log(describe(cloudy));
  try {
    schedule([10, 'heavy']);
  } catch (err) {
    console.log(`rejected input: ${err.message}`);
  }
}

main();

module.exports = { schedule, classifyNight, parseCover, describe };

