const MAIN_RATE = 10;
const MANEUVER_RATE = 3;

function validateDurations(durations) {
  if (!Array.isArray(durations)) {
    throw new TypeError('durations must be an array of numbers');
  }
  durations.forEach((duration, index) => {
    if (typeof duration !== 'number' || !Number.isFinite(duration)) {
      throw new TypeError(`duration at index ${index} is not a finite number`);
    }
  });
  return durations;
}

function burnFuel(duration) {
  if (duration < 0) {
    return Math.abs(duration) * MANEUVER_RATE;
  }
  return duration * MAIN_RATE;
}

function thrust(durations) {
  validateDurations(durations);
  let totalFuel = 0;
  let maneuverCount = 0;
  for (const duration of durations) {
    totalFuel += burnFuel(duration);
    if (duration < 0) {
      maneuverCount += 1;
    }
  }
  return [totalFuel, maneuverCount];
}

function describeBurn(duration) {
  const kind = duration < 0 ? 'maneuvering' : 'main';
  const seconds = Math.abs(duration);
  return `${kind} burn of ${seconds}s uses ${burnFuel(duration)} units`;
}

function report(durations) {
  const [totalFuel, maneuverCount] = thrust(durations);
  const lines = durations.map(describeBurn);
  lines.push(`total fuel: ${totalFuel} units`);
  lines.push(`maneuvering burns: ${maneuverCount}`);
  return lines.join('\n');
}

function main() {
  const flightPlans = [
    [5, -10, 2],
    [-1, -2, -3],
    [12],
    [],
  ];
  for (const plan of flightPlans) {
    console.log(`plan [${plan.join(', ')}]`);
    console.log(report(plan));
    console.log('');
  }
  try {
    thrust([4, 'boost']);
  } catch (error) {
    console.log(`rejected plan: ${error.message}`);
  }
}

main();

module.exports = { thrust, burnFuel, report };

