const MILES_PER_GALLON = 20;

function validateDistances(distances) {
  if (!Array.isArray(distances)) {
    throw new TypeError('route expects an array of distances in miles');
  }
  distances.forEach((leg, index) => {
    if (typeof leg !== 'number' || !Number.isFinite(leg)) {
      throw new TypeError(`leg ${index} is not a finite number: ${leg}`);
    }
    if (leg < 0) {
      throw new RangeError(`leg ${index} is negative: ${leg}`);
    }
  });
  return distances;
}

function totalDistance(distances) {
  return distances.reduce((sum, leg) => sum + leg, 0);
}

function gallonsNeeded(miles) {
  return Math.ceil(miles / MILES_PER_GALLON);
}

function route(distances) {
  validateDistances(distances);
  const miles = totalDistance(distances);
  const gallons = gallonsNeeded(miles);
  return [miles, gallons];
}

function cumulativeStops(distances) {
  const stops = [];
  let running = 0;
  distances.forEach((leg) => {
    running += leg;
    stops.push(running);
  });
  return stops;
}

function describeRoute(distances) {
  const [miles, gallons] = route(distances);
  const lines = [];
  cumulativeStops(distances).forEach((mark, index) => {
    lines.push(`Stop ${index + 1}: ${distances[index]} mi (${mark} mi from shop)`);
  });
  lines.push(`Total: ${miles} miles, ${gallons} gallon(s) of gas`);
  return lines.join('\n');
}

function main() {
  const shift = [
    [10, 15, 8],
    [20, 20, 20, 20],
