const DISQUALIFICATION_POINTS = 20;

function pointsFor(position) {
  if (!Number.isInteger(position)) {
    throw new TypeError(`finishing position must be an integer, got ${position}`);
  }
  if (position < 0) {
    throw new RangeError(`finishing position cannot be negative, got ${position}`);
  }
  if (position === 0) {
    return DISQUALIFICATION_POINTS;
  }
  return position;
}

function score(finishes) {
  if (!Array.isArray(finishes)) {
    throw new TypeError('finishes must be an array of finishing positions');
  }
  if (finishes.length === 0) {
    return 0;
  }
  const values = finishes.map(pointsFor);
  let total = 0;
  let worst = values[0];
  for (const value of values) {
    total += value;
    if (value > worst) {
      worst = value;
    }
  }
  return total - worst;
}

function describeRace(position) {
  if (position === 0) {
    return `DSQ (${DISQUALIFICATION_POINTS} pts)`;
  }
  return `place ${position} (${pointsFor(position)} pts)`;
}

function report(boatName, finishes) {
  const lines = [`${boatName}:`];
  finishes.forEach((position, index) => {
    lines.push(`  race ${index + 1}: ${describeRace(position)}`);
  });
  const raw = finishes.map(pointsFor).reduce((sum, value) => sum + value, 0);
  const adjusted = score(finishes);
  lines.push(`  raw total: ${raw}`);
  lines.push(`  dropped worst: ${raw - adjusted}`);
  lines.push(`  final score: ${adjusted}`);
  return lines.join('\n');
}

function standings(fleet) {
  const ranked = Object.entries(fleet).map(([name, finishes]) => ({
    name,
    total: score(finishes),
  }));
  ranked.sort((a, b) => a.total - b.total || a.name.localeCompare(b.name));
  return ranked;
}

function main() {
  const fleet = {
    Windrose: [1, 2, 0, 4],
    Kestrel: [3, 1, 2, 2],
