function parsePairs(ingredients) {
  if (!Array.isArray(ingredients)) {
    throw new TypeError('ingredients must be an array of weights in grams');
  }
  if (ingredients.length % 2 !== 0) {
    throw new RangeError('ingredients must contain a flour weight for every water weight');
  }
  const batches = [];
  for (let i = 0; i < ingredients.length; i += 2) {
    const flour = Number(ingredients[i]);
    const water = Number(ingredients[i + 1]);
    if (!Number.isFinite(flour) || !Number.isFinite(water)) {
      throw new TypeError(`batch ${i / 2 + 1} has a non-numeric weight`);
    }
    if (flour <= 0) {
      throw new RangeError(`batch ${i / 2 + 1} must use a positive flour weight`);
    }
    batches.push({ flour, water });
  }
  return batches;
}

function hydrationPercent(flour, water) {
  const ratio = (water / flour) * 100;
  return Math.round(ratio);
}

function hydration(ingredients) {
  const batches = parsePairs(ingredients);
  let highCount = 0;
  for (const batch of batches) {
    const percent = hydrationPercent(batch.flour, batch.water);
    if (percent > 75) {
      highCount += 1;
    }
  }
  return highCount;
}

function describeBatches(ingredients) {
  const batches = parsePairs(ingredients);
  const lines = batches.map((batch, index) => {
    const percent = hydrationPercent(batch.flour, batch.water);
    const label = percent > 75 ? 'high hydration' : 'standard';
    return `batch ${index + 1}: ${batch.flour}g flour, ${batch.water}g water -> ${percent}% (${label})`;
  });
  return lines.join('\n');
}

function report(ingredients) {
  const detail = describeBatches(ingredients);
  const total = hydration(ingredients);
  if (detail.length > 0) {
    console.log(detail);
  }
  console.log(`high hydration batches: ${total}`);
  return total;
}

