const MAX_LOAD = 800;

function validateWeights(weights) {
  if (!Array.isArray(weights)) {
    throw new TypeError('weights must be an array');
  }
  const cleaned = [];
  for (const raw of weights) {
    const value = Number(raw);
    if (!Number.isFinite(value) || value <= 0) {
      throw new RangeError(`invalid passenger weight: ${raw}`);
    }
    if (value > MAX_LOAD) {
      throw new RangeError(`passenger of ${value} exceeds the limit of ${MAX_LOAD}`);
    }
    cleaned.push(value);
  }
  return cleaned;
}

function elevator(weights) {
  const queue = validateWeights(weights);
  let trips = 0;
  let load = 0;
  for (const weight of queue) {
    if (load + weight > MAX_LOAD) {
      trips += 1;
      load = weight;
    } else {
      load += weight;
    }
  }
  if (load > 0) {
    trips += 1;
  }
  return trips;
}

function tripManifest(weights) {
  const queue = validateWeights(weights);
  const trips = [];
  let current = [];
  let load = 0;
  for (const weight of queue) {
    if (load + weight > MAX_LOAD) {
      trips.push(current);
      current = [weight];
      load = weight;
    } else {
      current.push(weight);
      load += weight;
    }
  }
  if (load > 0) {
    trips.push(current);
  }
  return trips;
}

function formatReport(weights) {
  const manifest = tripManifest(weights);
  const lines = manifest.map((group, index) => {
    const total = group.reduce((sum, weight) => sum + weight, 0);
    return `trip ${index + 1}: [${group.join(', ')}] = ${total}`;
  });
  lines.push(`total trips: ${elevator(weights)}`);
  return lines.join('\n');
}

function main() {
  const queue = [300, 400, 200, 500];
  console.log(formatReport(queue));
  console.log(elevator(queue));
  console.log(elevator([]));
  console.log(formatReport([800, 100, 700, 50, 50, 600]));
}

main();

