const SCALE_PER_SIZE = { 1: 10, 2: 20, 3: 30 };

const ALERT_THRESHOLD = 500;

function scaleFor(size) {
  const units = SCALE_PER_SIZE[size];
  if (units === undefined) {
    throw new RangeError(`unknown coffee size: ${size}`);
  }
  return units;
}

function validateCoffees(coffees) {
  if (!Array.isArray(coffees)) {
    throw new TypeError('coffees must be an array of cup sizes');
  }
  const cleaned = coffees.map((size, index) => {
    if (!Number.isInteger(size)) {
      throw new TypeError(`coffee at position ${index} is not an integer`);
    }
    return size;
  });
  return cleaned;
}

function descale(coffees) {
  const cups = validateCoffees(coffees);
  let buildup = 0;
  let alerts = 0;
  for (const size of cups) {
    buildup += scaleFor(size);
    while (buildup >= ALERT_THRESHOLD) {
      buildup -= ALERT_THRESHOLD;
      alerts += 1;
    }
  }
  return alerts;
}

function residualScale(coffees) {
  const cups = validateCoffees(coffees);
  const total = cups.reduce((sum, size) => sum + scaleFor(size), 0);
  return total % ALERT_THRESHOLD;
}

function usageReport(label, coffees) {
  const alerts = descale(coffees);
  const remaining = residualScale(coffees);
  const parts = [
    `${label}: ${coffees.length} cups`,
    `${alerts} descaling alert${alerts === 1 ? '' : 's'}`,
    `${remaining} units of scale remaining`,
  ];
  return parts.join(', ');
}

function main() {
  const morningRush = new Array(50).fill(1);
  const mixedDay = [3, 3, 2, 1, 3, 2, 2, 1, 1, 3];
  const heavyWeek = new Array(20).fill(3).concat(new Array(15).fill(2));
  console.log(usageReport('fifty small cups', morningRush));
  console.log(usageReport('mixed day', mixedDay));
  console.log(usageReport('heavy week', heavyWeek));
  try {
    descale([1, 4, 2]);
  } catch (error) {
    console.log(`rejected input: ${error.message}`);
  }
}

main();

module.exports = { descale, residualScale, usageReport };

