const HOUR_SECONDS = 3600;

function validateSongs(songs) {
  if (!Array.isArray(songs)) {
    throw new TypeError('playlist expects an array of durations in seconds');
  }
  const cleaned = [];
  for (const song of songs) {
    const duration = Number(song);
    if (!Number.isFinite(duration) || duration <= 0) {
      throw new RangeError(`invalid song duration: ${String(song)}`);
    }
    cleaned.push(duration);
  }
  return cleaned;
}

function playlist(songs) {
  const durations = validateSongs(songs);
  let hours = 0;
  let block = 0;
  for (const duration of durations) {
    if (block + duration > HOUR_SECONDS) {
      hours += 1;
      block = duration;
    } else {
      block += duration;
    }
  }
  if (block > 0) {
    hours += 1;
  }
  return hours;
}

function blockSizes(songs) {
  const durations = validateSongs(songs);
  const blocks = [];
  let current = [];
  for (const duration of durations) {
    const used = current.reduce((sum, value) => sum + value, 0);
    if (used + duration > HOUR_SECONDS) {
      blocks.push(current);
      current = [duration];
    } else {
      current.push(duration);
    }
  }
  if (current.length > 0) {
    blocks.push(current);
  }
  return blocks;
}

function describeSchedule(songs) {
  const blocks = blockSizes(songs);
  const lines = blocks.map((block, index) => {
    const filled = block.reduce((sum, value) => sum + value, 0);
    const idle = HOUR_SECONDS - filled;
    return `hour ${index + 1}: ${block.length} song(s), ${filled}s used, ${idle}s idle`;
  });
  lines.push(`total hours: ${playlist(songs)}`);
  return lines.join('\n');
}

function main() {
  const sample = [2000, 2000];
  console.log(playlist(sample));
  const mixed = [1200, 1200, 1200, 600, 3000, 400, 300];
  console.log(describeSchedule(mixed));
}

main();

module.exports = { playlist, blockSizes, describeSchedule, HOUR_SECONDS };

