const STANDARD_RATE = 0.35;
const HALLWAY_RATE = 0.20;
const BASE_FEE = 50;
const DISCOUNT_THRESHOLD = 500;
const DISCOUNT_RATE = 0.10;

function rateFor(roomType) {
  const normalized = String(roomType).trim().toLowerCase();
  return normalized === "hallway" ? HALLWAY_RATE : STANDARD_RATE;
}

function validateRoom(room) {
  if (!Array.isArray(room) || room.length !== 4) {
    throw new Error("each room needs [type, length, width, stained]");
  }
  const [type, length, width] = room;
  if (typeof type !== "string" || type.trim() === "") {
    throw new Error("room type must be a non-empty string");
  }
  if (!Number.isFinite(length) || !Number.isFinite(width)) {
    throw new Error(`bad dimensions for room "${type}"`);
  }
  if (length <= 0 || width <= 0) {
    throw new Error(`dimensions for room "${type}" must be positive`);
  }
}

function roomArea(room) {
  validateRoom(room);
  return room[1] * room[2];
}

function roomCharge(room) {
  const area = roomArea(room);
  const stained = Boolean(room[3]);
  const multiplier = stained ? 2 : 1;
  return area * rateFor(room[0]) * multiplier;
}

function estimate(rooms) {
  if (!Array.isArray(rooms)) {
    throw new Error("rooms must be a list of room details");
  }
  let totalArea = 0;
  let charges = 0;
  for (const room of rooms) {
    totalArea += roomArea(room);
    charges += roomCharge(room);
  }
  if (totalArea > DISCOUNT_THRESHOLD) {
    charges *= 1 - DISCOUNT_RATE;
  }
  const total = charges + BASE_FEE;
  return Math.round(total * 100) / 100;
}

function formatReport(rooms) {
  const lines = rooms.map((room) => {
    const area = roomArea(room);
    const charge = roomCharge(room);
    const flag = room[3] ? " (heavy stains)" : "";
    return `${room[0]}: ${area} sq ft${flag} -> $${charge.toFixed(2)}`;
  });
  lines.push(`TOTAL (incl. $${BASE_FEE} fee): $${estimate(rooms).toFixed(2)}`);
  return lines.join("\n");
}

const smallJob = [["hallway", 10, 5, false], ["bedroom", 20, 20, true]];
const largeJob = [["living room", 25, 18, false], ["hallway", 30, 4, true], ["den", 15, 12, false]];
console.log(formatReport(smallJob));
console.log("");
console.log(formatReport(largeJob));

