const MIN_AGE = 4;
const AGING_AGE = 20;
const AGING_PENALTY = 0.15;

function validateTree(tree, index) {
  if (!Array.isArray(tree) || tree.length !== 3) {
    throw new TypeError(`tree ${index} must be [age, diameter, health]`);
  }
  const [age, diameter, health] = tree;
  for (const value of [age, diameter, health]) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError(`tree ${index} has a non-numeric field`);
    }
  }
  if (age < 0 || diameter < 0) {
    throw new RangeError(`tree ${index} has a negative age or diameter`);
  }
  if (health < 1 || health > 10) {
    throw new RangeError(`tree ${index} health must be between 1 and 10`);
  }
  return { age, diameter, health };
}

function treeYield(tree, index) {
  const { age, diameter, health } = validateTree(tree, index);
  if (age < MIN_AGE) {
    return 0;
  }
  const base = 20 * age + 5 * diameter;
  let yieldValue = base * (health / 10);
  if (age > AGING_AGE) {
    yieldValue *= 1 - AGING_PENALTY;
  }
  return yieldValue;
}

function harvest(trees) {
  if (!Array.isArray(trees)) {
    throw new TypeError("trees must be a list of lists");
  }
  const total = trees.reduce((sum, tree, index) => sum + treeYield(tree, index), 0);
  return Math.floor(total);
}

function harvestReport(trees) {
  const lines = trees.map((tree, index) => {
    const apples = treeYield(tree, index);
    const label = `tree ${index + 1} (age ${tree[0]}, ${tree[1]}in, health ${tree[2]})`;
    return `${label}: ${apples.toFixed(2)} apples`;
  });
  lines.push(`total: ${harvest(trees)} apples`);
  return lines.join("\n");
}

function main() {
  const orchard = [[5, 10, 8], [3, 5, 9], [25, 14, 10], [12, 8, 5]];
  console.log(harvestReport(orchard));
  console.log(`sample: ${harvest([[5, 10, 8], [3, 5, 9]])}`);
  try {
    harvest([[6, 9, 12]]);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { harvest, treeYield, harvestReport };

