const COVERAGE_PER_GALLON = 350;
const COATS = 2;

function validateWall(wall, index) {
  if (!Array.isArray(wall) || wall.length !== 3) {
    throw new TypeError(`wall ${index} must be [width, height, openings]`);
  }
  const [width, height, openings] = wall;
  for (const value of [width, height, openings]) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`wall ${index} has an invalid measurement: ${value}`);
    }
  }
  return { width, height, openings };
}

function paintableArea(wall, index) {
  const { width, height, openings } = validateWall(wall, index);
  const gross = width * height;
  const net = gross - openings;
  return net < 0 ? 0 : net;
}

function totalPaintableArea(walls) {
  if (!Array.isArray(walls)) {
    throw new TypeError('walls must be a list of walls');
  }
  let total = 0;
  walls.forEach((wall, index) => {
    total += paintableArea(wall, index);
  });
  return total;
}

function gallons(walls) {
  const surface = totalPaintableArea(walls) * COATS;
  return Math.ceil(surface / COVERAGE_PER_GALLON);
}

function wallReport(walls) {
  return walls.map((wall, index) => {
    const area = paintableArea(wall, index);
    return `wall ${index + 1}: ${wall[0]}ft x ${wall[1]}ft minus ${wall[2]}sqft = ${area} sqft`;
  });
}

function describeJob(walls) {
  const lines = wallReport(walls);
  const surface = totalPaintableArea(walls);
  const cans = gallons(walls);
  lines.push(`paintable surface: ${surface} sqft`);
  lines.push(`with ${COATS} coats: ${surface * COATS} sqft`);
  lines.push(`gallons to buy: ${cans}`);
  return lines.join('\n');
}

function main() {
  const smallRoom = [[10, 8, 15], [12, 8, 20]];
  const bigRoom = [[20, 12, 40], [20, 12, 0], [14, 12, 30], [14, 12, 0]];
  const closet = [[3, 8, 24], [2, 8, 0]];
