  console.log(describeJob(bigRoom));
  console.log('');
  console.log(describeJob(closet));
  console.log('');
  console.log(`empty room needs ${gallons([])} gallons`);
}

main();

module.exports = { gallons, paintableArea, totalPaintableArea, describeJob };

