const BATTERY_MINUTES_PER_MAH = 1 / 100;
const PAYLOAD_STEP_GRAMS = 50;
const PAYLOAD_PENALTY_MINUTES = 2;
const WIND_THRESHOLD_KNOTS = 10;
const WIND_PENALTY_PER_KNOT = 0.05;
const WIND_ABORT_KNOTS = 20;

function validateFlight(flight, index) {
  if (!Array.isArray(flight) || flight.length !== 3) {
    throw new TypeError(`flight ${index} must be a list of three numbers`);
  }
  const labels = ['capacity', 'payload', 'wind'];
  for (let i = 0; i < flight.length; i += 1) {
    const value = flight[i];
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`flight ${index}: ${labels[i]} must be a non-negative number`);
    }
  }
}

function baseFlightTime(capacityMah) {
  return capacityMah * BATTERY_MINUTES_PER_MAH;
}

function payloadPenalty(payloadGrams) {
  const steps = Math.floor(payloadGrams / PAYLOAD_STEP_GRAMS);
  return steps * PAYLOAD_PENALTY_MINUTES;
}

function windFactor(windKnots) {
  if (windKnots >= WIND_ABORT_KNOTS) {
    return 0;
  }
  const excess = Math.max(0, windKnots - WIND_THRESHOLD_KNOTS);
  return Math.max(0, 1 - excess * WIND_PENALTY_PER_KNOT);
}

function predict(flights) {
  if (!Array.isArray(flights)) {
    throw new TypeError('flights must be a list of flight parameter lists');
  }
  const estimates = [];
  flights.forEach((flight, index) => {
    validateFlight(flight, index);
    const [capacity, payload, wind] = flight;
    const afterPayload = baseFlightTime(capacity) - payloadPenalty(payload);
    const minutes = Math.max(0, afterPayload) * windFactor(wind);
    estimates.push(Math.round(minutes * 10) / 10);
  });
  return estimates;
}

function formatReport(flights, estimates) {
  const lines = flights.map((flight, index) => {
    const [capacity, payload, wind] = flight;
    const minutes = estimates[index].toFixed(1);
    const status = estimates[index] > 0 ? 'cleared' : 'grounded';
    return `${capacity} mAh / ${payload} g / ${wind} kt -> ${minutes} min (${status})`;
  });
  return lines.join('\n');
}

function main() {
  const missions = [[5000, 200, 12], [4000, 0, 25], [3000, 125, 8], [6000, 500, 19]];
  const estimates = predict(missions);
  console.log(formatReport(missions, estimates));
  const total = estimates.reduce((sum, minutes) => sum + minutes, 0);
  console.log(`total airtime: ${total.toFixed(1)} min`);
}

main();

module.exports = { predict, baseFlightTime, payloadPenalty, windFactor, formatReport };

