const GRADE_TABLE = {
  1: '4a',
  2: '4a',
  3: '4a',
  4: '4a',
  5: '4b',
  6: '4b',
  7: '5a',
  8: '5a',
  9: '5c',
  10: '6a',
  11: '6b',
  12: '6c',
  13: '7a',
  14: '7b',
};

const UNKNOWN = 'unknown';

function translateOne(suffix) {
  if (!Number.isInteger(suffix)) {
    return UNKNOWN;
  }
  const european = GRADE_TABLE[suffix];
  if (european === undefined) {
    return UNKNOWN;
  }
  return european;
}

function convert(climbs) {
  if (!Array.isArray(climbs)) {
    throw new TypeError('convert expects an array of grade suffixes');
  }
  const translated = [];
  for (const suffix of climbs) {
    translated.push(translateOne(suffix));
  }
  return translated;
}

function americanName(suffix) {
  return `5.${suffix}`;
}

function buildReport(climbs) {
  const european = convert(climbs);
  const lines = [];
  for (let i = 0; i < climbs.length; i += 1) {
    lines.push(`${americanName(climbs[i])} -> ${european[i]}`);
  }
  return lines.join('\n');
}

function countUnknown(climbs) {
  let unknowns = 0;
  for (const grade of convert(climbs)) {
    if (grade === UNKNOWN) {
      unknowns += 1;
    }
  }
  return unknowns;
}

const route = [8, 10, 15];

console.log(convert(route));
console.log(buildReport(route));
console.log(`untranslatable grades: ${countUnknown(route)}`);

module.exports = { convert, buildReport, countUnknown };

