const CUPS_PER_UNIT_PER_GALLON = 500;
const GRAVITY_STEP = 0.001;
const CUPS_PER_STEP = 0.5;

function validateTank(tank, index) {
  if (!Array.isArray(tank) || tank.length !== 3) {
    throw new TypeError(`tank ${index} must be [volume, current, target]`);
  }
  const [volume, current, target] = tank;
  for (const value of [volume, current, target]) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError(`tank ${index} contains a non-numeric entry`);
    }
  }
  if (volume < 0) {
    throw new RangeError(`tank ${index} has a negative volume`);
  }
  return { volume, current, target };
}

function cupsForTank(tank, index) {
  const { volume, current, target } = validateTank(tank, index);
  const rise = target - current;
  if (rise <= 0) {
    return 0;
  }
  const steps = rise / GRAVITY_STEP;
  return volume * steps * CUPS_PER_STEP;
}

function roundToTenth(value) {
  return Math.round(value * 10) / 10;
}

function prepare(tanks) {
  if (!Array.isArray(tanks)) {
    throw new TypeError("tanks must be a list of tank descriptions");
  }
  return tanks.map((tank, index) => roundToTenth(cupsForTank(tank, index)));
}

function describe(tanks, cups) {
  const lines = [];
  let total = 0;
  tanks.forEach((tank, index) => {
    const [volume, current, target] = tank;
    const amount = cups[index];
    total += amount;
    const arrow = amount > 0 ? `${current} -> ${target}` : `${current} (no change)`;
    lines.push(`Tank ${index + 1}: ${volume} gal, ${arrow}: ${amount.toFixed(1)} cups`);
  });
  lines.push(`Total salt mix: ${roundToTenth(total).toFixed(1)} cups`);
  return lines.join("\n");
