'use strict';

const round2 = (value) => Math.round(value * 100) / 100;

function validateRecipe(recipe, index) {
  if (!Array.isArray(recipe) || recipe.length !== 3) {
    throw new TypeError(`recipe ${index} must be [volume, concentration, alcoholFree]`);
  }
  const [volume, concentration, alcoholFree] = recipe;
  if (typeof volume !== 'number' || !Number.isFinite(volume) || volume < 0) {
    throw new RangeError(`recipe ${index} has an invalid total volume: ${volume}`);
  }
  if (typeof concentration !== 'number' || concentration < 0 || concentration > 100) {
    throw new RangeError(`recipe ${index} has an invalid concentration: ${concentration}`);
  }
  if (typeof alcoholFree !== 'boolean') {
    throw new TypeError(`recipe ${index} must flag alcohol free with a boolean`);
  }
  return { volume, concentration, alcoholFree };
}

function blend(recipes) {
  if (!Array.isArray(recipes)) {
    throw new TypeError('recipes must be an array of recipe arrays');
  }
  return recipes.map((recipe, index) => {
    const { volume, concentration, alcoholFree } = validateRecipe(recipe, index);
    const oil = volume * concentration / 100;
    const carrier = volume - oil;
    const alcohol = alcoholFree ? 0 : carrier * 0.9;
    const water = carrier - alcohol;
    return [round2(oil), round2(alcohol), round2(water)];
  });
}

function describeBlend(recipe, amounts) {
  const [volume, concentration, alcoholFree] = recipe;
  const [oil, alcohol, water] = amounts;
  const kind = alcoholFree ? 'alcohol free' : 'alcohol based';
  const parts = [`oil ${oil.toFixed(2)} ml`];
  if (alcohol > 0) {
    parts.push(`alcohol ${alcohol.toFixed(2)} ml`);
  }
  parts.push(`water ${water.toFixed(2)} ml`);
  return `${volume} ml at ${concentration}% (${kind}): ${parts.join(', ')}`;
}

function report(recipes) {
  const results = blend(recipes);
  const lines = recipes.map((recipe, index) => describeBlend(recipe, results[index]));
  const totalOil = results.reduce((sum, amounts) => sum + amounts[0], 0);
  lines.push(`total fragrance oil required: ${round2(totalOil).toFixed(2)} ml`);
  return lines.join('\n');
}

