  console.log(JSON.stringify(blend(recipes)));
  console.log(report(recipes));
  try {
    blend([[100, 120, false]]);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { blend, report, describeBlend };

