function mean(values) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total / values.length;
}

function spread(values) {
  let highest = values[0];
  let lowest = values[0];
  for (const value of values) {
    if (value > highest) {
      highest = value;
    }
    if (value < lowest) {
      lowest = value;
    }
  }
  return highest - lowest;
}

function roundTo1(number) {
  const scaled = Math.round(Math.abs(number) * 10) / 10;
  return number < 0 ? -scaled : scaled;
}

function inspect(log) {
  if (!Array.isArray(log) || log.length === 0) {
    throw new Error('each watch log must be a non-empty list of deviations');
  }
  const average = mean(log);
  const variance = spread(log);
  const certified = average >= -4 && average <= 6 && variance <= 10;
  return { average, variance, certified };
}

function accuracy(logs) {
  let certifiedCount = 0;
  let certifiedTotal = 0;
  for (const log of logs) {
    const report = inspect(log);
    if (report.certified) {
      certifiedCount += 1;
      certifiedTotal += report.average;
    }
  }
  const certifiedAverage = certifiedCount === 0 ? 0 : certifiedTotal / certifiedCount;
  return [certifiedCount, roundTo1(certifiedAverage)];
}

function describe(logs) {
  const lines = logs.map((log, index) => {
    const report = inspect(log);
    const status = report.certified ? 'CERTIFIED' : 'REJECTED';
    const avg = roundTo1(report.average).toFixed(1);
    return `Watch ${index + 1}: avg ${avg}s, variance ${report.variance}s -> ${status}`;
  });
  const [count, average] = accuracy(logs);
  lines.push(`Certified: ${count}, mean deviation ${average.toFixed(1)}s`);
  return lines.join('\n');
}

function main() {
  const batch = [
    [-2, 1, 0],
    [-10, 5, 8],
    [3, 4, 6, 5],
    [0, 0, -1, 1, 0],
  ];
  console.log(describe(batch));
  console.log(accuracy([[-2, 1, 0], [-10, 5, 8]]));
}

main();

