'use strict';

const TURNAROUND_MILES = 0.2;

function validateStreet(street, index) {
  if (!Array.isArray(street) || street.length !== 3) {
    throw new TypeError(`street ${index} must be [length, lanes, priority]`);
  }
  const [length, lanes, priority] = street;
  if (typeof length !== 'number' || !isFinite(length) || length < 0) {
    throw new TypeError(`street ${index} has an invalid length: ${length}`);
  }
  if (!Number.isInteger(lanes) || lanes < 1) {
    throw new TypeError(`street ${index} has an invalid lane count: ${lanes}`);
  }
  if (typeof priority !== 'boolean') {
    throw new TypeError(`street ${index} has a non-boolean priority flag`);
  }
  return { length, lanes, priority };
}

function passesFor(street) {
  const salting = street.priority ? 1 : 0;
  return street.lanes + salting;
}

function streetDistance(street) {
  const passes = passesFor(street);
  return street.length * passes + TURNAROUND_MILES * passes;
}

function plow(routes) {
  if (!Array.isArray(routes)) {
    throw new TypeError('routes must be a list of streets');
  }
  let total = 0;
  for (let i = 0; i < routes.length; i += 1) {
    const street = validateStreet(routes[i], i);
    total += streetDistance(street);
  }
  return Math.round(total * 10) / 10;
}

function routeReport(routes) {
  const lines = [];
  routes.forEach((raw, index) => {
    const street = validateStreet(raw, index);
    const passes = passesFor(street);
    const miles = streetDistance(street).toFixed(1);
    const tag = street.priority ? 'priority' : 'standard';
    lines.push(`street ${index + 1}: ${passes} passes, ${miles} mi (${tag})`);
  });
  lines.push(`total: ${plow(routes).toFixed(1)} mi`);
  return lines.join('\n');
}

function main() {
  const routes = [[2, 2, false], [1.5, 3, true]];
  console.log(routeReport(routes));
  const downtown = [[0.8, 4, true], [1.2, 2, false], [3, 1, true]];
  console.log(routeReport(downtown));
  try {
    plow([[1, 0, true]]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { plow, routeReport, streetDistance };

