const SPEED_OF_SOUND_IN_METAL = 5100;
const NODE_FRACTION = 0.224;
const MOUNTING_LOSS = 0.05;
const HEARING_LIMIT = 20000;

function validateLengths(tubes) {
  if (!Array.isArray(tubes)) {
    throw new TypeError('tubes must be an array of lengths in meters');
  }
  const cleaned = [];
  for (const length of tubes) {
    if (typeof length !== 'number' || !Number.isFinite(length)) {
      throw new TypeError(`invalid tube length: ${String(length)}`);
    }
    if (length <= 0) {
      throw new RangeError(`tube length must be positive, got ${length}`);
    }
    cleaned.push(length);
  }
  return cleaned;
}

function fundamentalFrequency(length) {
  return SPEED_OF_SOUND_IN_METAL / (2 * length);
}

function adjustedFrequency(length) {
  const open = fundamentalFrequency(length);
  return open * (1 - MOUNTING_LOSS);
}

function nodePosition(length) {
  return length * NODE_FRACTION;
}

function chime(tubes) {
  const lengths = validateLengths(tubes);
  const audible = [];
  for (const length of lengths) {
    const frequency = adjustedFrequency(length);
    if (frequency <= HEARING_LIMIT) {
      audible.push(Math.round(frequency));
    }
  }
  return audible;
}

function describeTube(length) {
  const frequency = adjustedFrequency(length);
  const hanging = nodePosition(length);
  const status = frequency <= HEARING_LIMIT ? 'audible' : 'ultrasonic';
  const pitch = Math.round(frequency);
  return `${length.toFixed(3)} m  hang at ${hanging.toFixed(4)} m  ${pitch} Hz  (${status})`;
}

function buildReport(tubes) {
  const lengths = validateLengths(tubes);
  const lines = lengths.map(describeTube);
  const audible = chime(lengths);
  lines.push(`audible frequencies: [${audible.join(', ')}]`);
  return lines.join('\n');
}

function main() {
  const set = [0.5, 0.1, 0.05];
  console.log(buildReport(set));
  const wideSet = [1.2, 0.9, 0.75, 0.6, 0.02];
  console.log(buildReport(wideSet));
  console.log(chime(set));
  console.log(chime(wideSet));
}

main();

module.exports = { chime, adjustedFrequency, fundamentalFrequency, nodePosition, buildReport };

