'use strict';

const BAG_GRAMS = 1000;
const NUTRIENT_NAMES = ['nitrogen', 'phosphorus', 'potassium'];

function validateZone(zone, index) {
  if (!Array.isArray(zone)) {
    throw new TypeError(`zone ${index} must be an array of four numbers`);
  }
  if (zone.length !== 4) {
    throw new RangeError(`zone ${index} must contain area plus three rates`);
  }
  for (const value of zone) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`zone ${index} contains an invalid value: ${value}`);
    }
  }
}

function nutrientGrams(zones, nutrientIndex) {
  let grams = 0;
  for (const zone of zones) {
    grams += zone[0] * zone[nutrientIndex + 1];
  }
  return grams;
}

function bagsFor(grams) {
  return Math.ceil(grams / BAG_GRAMS);
}

function fertilize(zones) {
  if (!Array.isArray(zones)) {
    throw new TypeError('zones must be an array of zone descriptions');
  }
  zones.forEach(validateZone);
  const totals = [];
  for (let nutrient = 0; nutrient < NUTRIENT_NAMES.length; nutrient += 1) {
    const grams = nutrientGrams(zones, nutrient);
    totals.push(bagsFor(grams));
  }
  return totals;
}

function shoppingReport(zones) {
  const bags = fertilize(zones);
  const area = zones.reduce((sum, zone) => sum + zone[0], 0);
  const lines = [`Garden area: ${area} m2`];
  bags.forEach((count, index) => {
    const label = NUTRIENT_NAMES[index];
    lines.push(`${label}: ${count} bag(s)`);
  });
  const total = bags.reduce((sum, count) => sum + count, 0);
  lines.push(`total bags to buy: ${total}`);
  return lines.join('\n');
}

function main() {
  const sample = [[50, 10, 5, 20], [100, 15, 0, 10]];
  console.log(fertilize(sample).join(', '));
  console.log(shoppingReport(sample));
  const bigGarden = [[220, 12, 4, 6], [75, 30, 12, 0], [410, 8, 8, 8]];
  console.log(shoppingReport(bigGarden));
  try {
    fertilize([[10, 5, 5]]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { fertilize, shoppingReport };

