const PI = 3.14159;
const GRAVITY = 9.8;
const AIR_DENSITY = 1.225;
const DRAG_COEFFICIENT = 1.5;

function canopyArea(diameter) {
  const radius = diameter / 2;
  return radius * radius * PI;
}

function dragForce(mass) {
  return mass * GRAVITY;
}

function terminalSpeed(mass, diameter) {
  const area = canopyArea(diameter);
  const resistance = 0.5 * AIR_DENSITY * DRAG_COEFFICIENT * area;
  const speedSquared = dragForce(mass) / resistance;
  return Math.sqrt(speedSquared);
}

function validateJumper(jumper, index) {
  if (!Array.isArray(jumper) || jumper.length !== 2) {
    throw new TypeError(`jumper ${index} must be a [mass, diameter] pair`);
  }
  const [mass, diameter] = jumper;
  if (typeof mass !== 'number' || typeof diameter !== 'number') {
    throw new TypeError(`jumper ${index} must hold numeric values`);
  }
  if (mass <= 0 || diameter <= 0) {
    throw new RangeError(`jumper ${index} needs a positive mass and diameter`);
  }
  return [mass, diameter];
}

function descent(jumpers) {
  if (!Array.isArray(jumpers)) {
    throw new TypeError('jumpers must be a list of [mass, diameter] pairs');
  }
  const speeds = [];
  jumpers.forEach((jumper, index) => {
    const [mass, diameter] = validateJumper(jumper, index);
    const speed = terminalSpeed(mass, diameter);
    speeds.push(Math.round(speed * 100) / 100);
  });
  return speeds;
}

function describeDescents(jumpers) {
  const speeds = descent(jumpers);
  return speeds.map((speed, index) => {
    const [mass, diameter] = jumpers[index];
    const verdict = speed <= 5 ? 'safe' : 'too fast';
    return `${mass} kg under a ${diameter} m canopy lands at ${speed.toFixed(2)} m/s (${verdict})`;
  });
}

