const PI = 3.14159;
const INCHES_PER_FOOT = 12;

function validateReel(reel, index) {
  if (!Array.isArray(reel) || reel.length !== 4) {
    throw new TypeError(`reel ${index} must be a list of four numbers`);
  }
  const labels = ['outer radius', 'core radius', 'width', 'wire diameter'];
  for (let i = 0; i < reel.length; i += 1) {
    const value = reel[i];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`reel ${index}: ${labels[i]} must be a finite number`);
    }
  }
  const [outer, core, width, wire] = reel;
  if (wire <= 0) {
    throw new RangeError(`reel ${index}: wire diameter must be positive`);
  }
  if (width <= 0) {
    throw new RangeError(`reel ${index}: spool width must be positive`);
  }
  if (outer < core) {
    throw new RangeError(`reel ${index}: outer radius is smaller than core radius`);
  }
}

function layerCount(outer, core, wire) {
  return (outer - core) / wire;
}

function wrapsPerLayer(width, wire) {
  return width / wire;
}

function averageRadius(outer, core) {
  return (outer + core) / 2;
}

function reelLengthFeet(reel) {
  const [outer, core, width, wire] = reel;
  const layers = layerCount(outer, core, wire);
  const perLayer = wrapsPerLayer(width, wire);
  const totalWraps = layers * perLayer;
  const inches = totalWraps * averageRadius(outer, core) * 2 * PI;
  return inches / INCHES_PER_FOOT;
}

function spools(reels) {
  if (!Array.isArray(reels)) {
    throw new TypeError('reels must be a list of reel descriptions');
  }
  return reels.map((reel, index) => {
    validateReel(reel, index);
    const feet = reelLengthFeet(reel);
    return Math.round(feet * 10) / 10;
  });
}

function describeSpools(reels) {
  const lengths = spools(reels);
  return lengths.map((feet, index) => {
    const [outer, core, width, wire] = reels[index];
    const shape = `outer ${outer}" core ${core}" width ${width}" wire ${wire}"`;
    return `${shape} -> ${feet.toFixed(1)} ft`;
  });
}

function main() {
  const inventory = [[10, 4, 5, 0.5], [12, 6, 10, 1], [6.5, 1.25, 3, 0.125]];
  console.log(spools(inventory));
  for (const line of describeSpools(inventory)) {
    console.log(line);
  }
}

main();

