const WATER_DENSITY = 1000;
const GRAVITY = 9.8;
const MIN_HEAD = 10;

function validateDam(dam, index) {
  if (!Array.isArray(dam) || dam.length !== 3) {
    throw new TypeError(`dam ${index} must be [flow, head, efficiency]`);
  }
  const [flow, head, efficiency] = dam;
  if (![flow, head, efficiency].every((v) => typeof v === 'number' && Number.isFinite(v))) {
    throw new TypeError(`dam ${index} has a non-numeric entry`);
  }
  if (flow < 0 || head < 0) {
    throw new RangeError(`dam ${index} has a negative flow or head`);
  }
  if (efficiency < 0 || efficiency > 1) {
    throw new RangeError(`dam ${index} efficiency must be between 0 and 1`);
  }
  return { flow, head, efficiency };
}

function damPower(flow, head, efficiency) {
  if (head < MIN_HEAD) {
    return 0;
  }
  const watts = flow * head * efficiency * WATER_DENSITY * GRAVITY;
  return watts / 1e6;
}

function hydro(dams) {
  if (!Array.isArray(dams)) {
    throw new TypeError('dams must be a list of lists');
  }
  return dams.map((dam, index) => {
    const { flow, head, efficiency } = validateDam(dam, index);
    const megawatts = damPower(flow, head, efficiency);
    return Math.round(megawatts * 100) / 100;
  });
}

function report(dams) {
  const outputs = hydro(dams);
  const lines = outputs.map((mw, index) => {
    const [flow, head] = dams[index];
    const status = mw === 0 ? 'idle (head too low)' : 'generating';
    return `Dam ${index + 1}: ${flow} m3/s at ${head} m -> ${mw.toFixed(2)} MW, ${status}`;
  });
  const total = outputs.reduce((sum, mw) => sum + mw, 0);
  lines.push(`Total: ${(Math.round(total * 100) / 100).toFixed(2)} MW`);
  return lines.join('\n');
}

function main() {
  const fleet = [
    [50, 20, 0.85],
    [10, 5, 0.9],
    [120, 45, 0.92],
    [8, 60, 0.78],
  ];
  console.log(hydro(fleet).join(', '));
  console.log(report(fleet));
  try {
    hydro([[10, 20, 1.5]]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { hydro, damPower, report };

