function validate(items) {
  if (items === null || typeof items !== 'object') {
    throw new TypeError('split expects an object with tax, tipPercent and prices');
  }
  const prices = items.prices;
  if (!Array.isArray(prices) || prices.length === 0) {
    throw new TypeError('prices must be a non-empty array of meal costs');
  }
  for (const price of prices) {
    if (typeof price !== 'number' || !Number.isFinite(price) || price < 0) {
      throw new RangeError(`invalid meal price: ${price}`);
    }
  }
  const tax = items.tax === undefined ? 0 : items.tax;
  const tipPercent = items.tipPercent === undefined ? 0 : items.tipPercent;
  if (typeof tax !== 'number' || !Number.isFinite(tax) || tax < 0) {
    throw new RangeError(`invalid tax amount: ${tax}`);
  }
  if (typeof tipPercent !== 'number' || !Number.isFinite(tipPercent) || tipPercent < 0) {
    throw new RangeError(`invalid tip percentage: ${tipPercent}`);
  }
  return { prices, tax, tipPercent };
}

function round2(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function split(items) {
  const { prices, tax, tipPercent } = validate(items);
  const subtotal = prices.reduce((sum, price) => sum + price, 0);
  const tipRate = 1 + tipPercent / 100;
  if (subtotal === 0) {
    const evenTax = tax / prices.length;
    return prices.map(() => round2(evenTax * tipRate));
  }
  return prices.map((price) => {
    const share = price / subtotal;
    const withTax = price + tax * share;
    return round2(withTax * tipRate);
  });
}

function report(items, names) {
  const owed = split(items);
  const lines = owed.map((amount, index) => {
    const label = names && names[index] ? names[index] : `Person ${index + 1}`;
    return `${label}: $${amount.toFixed(2)}`;
  });
  const total = owed.reduce((sum, amount) => sum + amount, 0);
  lines.push(`Total collected: $${round2(total).toFixed(2)}`);
  return lines.join('\n');
}

function main() {
  const dinner = {
    prices: [18.5, 24.0, 12.25, 30.75],
    tax: 7.15,
    tipPercent: 18,
  };
  console.log(report(dinner, ['Ana', 'Ben', 'Cleo', 'Dan']));
  const coffee = { prices: [4.5, 4.5, 3.0], tax: 0.96, tipPercent: 10 };
  console.log(split(coffee).join(' | '));
}

main();

module.exports = { split, report, round2 };

