const MOTIF = 'kpkp';
const ALLOWED = 'kpt';

function validate(pattern) {
  if (typeof pattern !== 'string') {
    throw new TypeError('knit: pattern must be a string');
  }
  const bad = [];
  for (const ch of pattern) {
    if (!ALLOWED.includes(ch)) {
      bad.push(ch);
    }
  }
  if (bad.length > 0) {
    throw new Error(`knit: unknown instruction(s) ${bad.join(', ')}`);
  }
  return pattern;
}

function splitRows(pattern) {
  return validate(pattern).split('t');
}

function countMotif(fabric, motif) {
  let found = 0;
  let index = fabric.indexOf(motif);
  while (index !== -1) {
    found += 1;
    index = fabric.indexOf(motif, index + 1);
  }
  return found;
}

function knit(pattern) {
  const rows = splitRows(pattern);
  const fabric = rows.join('');
  return [rows.length, fabric.length, countMotif(fabric, MOTIF)];
}

function describeRows(pattern) {
  const widths = splitRows(pattern).map((row) => row.length);
  return widths.map((width, i) => `row ${i + 1}: ${width} st`).join(', ');
}

function formatReport(pattern) {
  const [rows, stitches, motifs] = knit(pattern);
  const lines = [];
  lines.push(`rows: ${rows}`);
  lines.push(`stitches: ${stitches}`);
  lines.push(`"${MOTIF}" motifs: ${motifs}`);
  lines.push(describeRows(pattern));
  return lines.join('\n');
}

function withTurns(stitches, breaks) {
  let out = '';
  let start = 0;
  for (const point of breaks) {
    out += stitches.slice(start, point) + 't';
    start = point;
  }
  return out + stitches.slice(start);
}

function main() {
  const fabric = withTurns('kp'.repeat(25), [20, 30, 40]);
  console.log(formatReport(fabric));
  console.log(knit(fabric).join(' '));
}

main();

