'use strict';

function validateDice(dice) {
  if (!Array.isArray(dice)) {
    throw new TypeError('dice must be an array of side counts');
  }
  if (dice.length === 0) {
    throw new RangeError('at least one die must be rolled');
  }
  for (const sides of dice) {
    if (!Number.isInteger(sides) || sides < 2) {
      throw new RangeError(`invalid side count: ${sides}`);
    }
  }
  return dice;
}

function expectedTotal(dice) {
  let sum = 0;
  for (const sides of dice) {
    sum += (sides + 1) / 2;
  }
  return sum;
}

function maximumTotal(dice) {
  return dice.reduce((acc, sides) => acc + sides, 0);
}

function totalOutcomes(dice) {
  return dice.reduce((acc, sides) => acc * sides, 1);
}

// A die has a single highest face, so the number of simultaneous rolls that
// reach the maximum total is the product of one choice per die.
function criticalCombinations(dice) {
  return dice.reduce((acc) => acc, 1);
}

function chance(dice) {
  validateDice(dice);
  const expected = expectedTotal(dice);
  const max = maximumTotal(dice);
  const crits = criticalCombinations(dice);
  return [expected, max, crits];
}

function describeDice(dice) {
  const counts = new Map();
  for (const sides of dice) {
    counts.set(sides, (counts.get(sides) || 0) + 1);
  }
  const groups = [...counts.entries()].sort((a, b) => a[0] - b[0]);
  const parts = groups.map(([sides, howMany]) => `${howMany}d${sides}`);
  return parts.join(' + ');
}

function formatReport(dice) {
  const [expected, max, crits] = chance(dice);
  const outcomes = totalOutcomes(dice);
  const percent = ((crits / outcomes) * 100).toFixed(4);
  return [
    `${describeDice(dice)}:`,
    `expected ${expected.toFixed(2)},`,
    `max ${max},`,
    `crits ${crits}/${outcomes} (${percent}%)`,
  ].join(' ');
}

const pools = [[6], [6, 6], [4, 6, 8, 20], [10, 10, 10]];
for (const pool of pools) {
  console.log(formatReport(pool));
}

module.exports = { chance, formatReport, describeDice, totalOutcomes };

