const BASE_DOTS = ['1', '12', '14', '145', '15', '124', '1245', '125', '24', '245'];
const CAPITAL_CELL = '000001';
const RAISED = '*';
const FLAT = '.';

function dotsToCell(dots) {
    const cell = ['0', '0', '0', '0', '0', '0'];
    for (const digit of dots) {
        cell[Number(digit) - 1] = '1';
    }
    return cell.join('');
}

function letterDots(letter) {
    const index = letter.charCodeAt(0) - 97;
    if (index < 10) {
        return BASE_DOTS[index];
    }
    if (index < 20) {
        return BASE_DOTS[index - 10] + '3';
    }
    if (letter === 'w') {
        return '2456';
    }
    const shifted = index < 23 ? index - 20 : index - 21;
    return BASE_DOTS[shifted] + '36';
}

function braille(text) {
    if (typeof text !== 'string') {
        throw new TypeError('braille expects a string of letters');
    }
    const cells = [];
    for (const character of text) {
        const lower = character.toLowerCase();
        if (lower < 'a' || lower > 'z') {
            throw new RangeError('unsupported character: ' + character);
        }
        if (character !== lower) {
            cells.push(CAPITAL_CELL);
        }
        cells.push(dotsToCell(letterDots(lower)));
    }
    return cells;
}

function renderRows(cells) {
    const rows = ['', '', ''];
    for (const cell of cells) {
        for (let row = 0; row < 3; row += 1) {
            const left = cell[row] === '1' ? RAISED : FLAT;
            const right = cell[row + 3] === '1' ? RAISED : FLAT;
            rows[row] += left + right + ' ';
        }
    }
    return rows.map((row) => row.trimEnd());
}

function describe(message) {
    const cells = braille(message);
    const lines = [message + ' -> ' + cells.length + ' cells', cells.join(' ')];
    for (const row of renderRows(cells)) {
        lines.push(row);
    }
    return lines.join('\n');
}

console.log(describe('Hello'));
console.log(describe('braille'));
console.log(describe('WxyZ'));

module.exports = { braille, renderRows, describe };

