const SPECIES_FACTORS = {
  dog: { high: 2.0, normal: 1.6, senior: 1.4, weight_loss: 1.0 },
  cat: { high: 1.6, normal: 1.2, senior: 1.1, weight_loss: 0.8 },
  rabbit: { high: 1.6, normal: 1.4, senior: 1.2, weight_loss: 1.0 },
};

function restingEnergy(weightKg) {
  const rer = 70 * Math.pow(weightKg, 0.75);
  return rer;
}

function activityFactor(species, activity) {
  const table = SPECIES_FACTORS[species];
  if (!table) {
    throw new Error(`unsupported species: ${species}`);
  }
  const factor = table[activity];
  if (factor === undefined) {
    throw new Error(`unsupported activity level for ${species}: ${activity}`);
  }
  return factor;
}

function validateProfile(pet, index) {
  const species = String(pet.species || '').toLowerCase();
  const activity = String(pet.activity || '').toLowerCase().replace(/[\s-]+/g, '_');
  const weight = Number(pet.weight);
  if (!Number.isFinite(weight) || weight <= 0) {
    throw new Error(`profile ${index} has an invalid weight: ${pet.weight}`);
  }
  return { species, activity, weight };
}

function dailyCalories(pet, index) {
  const profile = validateProfile(pet, index);
  const base = restingEnergy(profile.weight);
  const factor = activityFactor(profile.species, profile.activity);
  return Math.round(base * factor);
}

function feed(pets) {
  if (!Array.isArray(pets)) {
    throw new TypeError('feed expects a list of animal profiles');
  }
  return pets.map(dailyCalories);
}

function report(pets) {
  const calories = feed(pets);
  const lines = pets.map((pet, i) => {
    const label = `${pet.species} (${pet.weight} kg, ${pet.activity})`;
    return `${label.padEnd(34)} ${String(calories[i]).padStart(5)} kcal/day`;
  });
  return lines.join('\n');
}

const kennel = [
  { species: 'dog', weight: 30, activity: 'high' },
  { species: 'dog', weight: 12, activity: 'weight loss' },
  { species: 'cat', weight: 4.5, activity: 'normal' },
  { species: 'cat', weight: 6, activity: 'senior' },
  { species: 'rabbit', weight: 2, activity: 'normal' },
];

console.log(report(kennel));
console.log(feed(kennel));

module.exports = { feed, restingEnergy, activityFactor, report };

