const NOTE_INDEX = { C: 0, 'C#': 1, Db: 1, D: 2, 'D#': 3, Eb: 3, E: 4, F: 5, 'F#': 6, Gb: 6, G: 7, 'G#': 8, Ab: 8, A: 9, 'A#': 10, Bb: 10, B: 11 };
const PITCH_NAMES = ['C', 'C#', 'D', 'Eb', 'E', 'F', 'F#', 'G', 'Ab', 'A', 'Bb', 'B'];
const QUALITY_INTERVALS = {
  '': [0, 4, 7],
  m: [0, 3, 7],
  min: [0, 3, 7],
  7: [0, 4, 7, 10],
  m7: [0, 3, 7, 10],
  maj7: [0, 4, 7, 11],
  dim: [0, 3, 6],
  aug: [0, 4, 8],
  sus4: [0, 5, 7],
};
const OPEN_STRINGS = [40, 45, 50, 55, 59, 64];
const SPAN = 3;
const HIGHEST_BASE = 9;

function parseChord(name) {
  const match = /^([A-G][#b]?)(.*)$/.exec(name.trim());
  if (!match) throw new Error(`unrecognised chord name: ${name}`);
  const root = NOTE_INDEX[match[1]];
  const intervals = QUALITY_INTERVALS[match[2]];
  if (!intervals) throw new Error(`unsupported chord quality: ${match[2]}`);
  return { root, tones: intervals.map((step) => (root + step) % 12) };
}

function lowestUsableFret(openPitch, tones, base) {
  for (let candidate = 0; candidate <= base + SPAN; candidate += 1) {
    if (candidate > 0 && candidate < base) continue;
    if (tones.includes((openPitch + candidate) % 12)) return candidate;
  }
  return -1;
}

function voiceChord(chord) {
  let best = null;
  for (let base = 0; base <= HIGHEST_BASE; base += 1) {
    const frets = OPEN_STRINGS.map((open) => lowestUsableFret(open, chord.tones, base));
    const bass = frets.findIndex((f, i) => f >= 0 && (OPEN_STRINGS[i] + f) % 12 === chord.root);
    if (bass < 0) continue;
    for (let i = 0; i < bass; i += 1) frets[i] = -1;
    const sounding = new Set(frets.map((f, i) => (f < 0 ? -1 : (OPEN_STRINGS[i] + f) % 12)));
    if (!chord.tones.every((tone) => sounding.has(tone))) continue;
    const muted = frets.filter((f) => f < 0).length;
    const cost = muted * 12 + base + Math.max(...frets);
    if (!best || cost < best.cost) best = { frets, bass, cost };
  }
  if (!best) throw new Error('no playable voicing found within the first twelve frets');
  return { frets: best.frets, bass: best.bass };
}

function fret(chords) {
  return chords.map((name) => {
    const voicing = voiceChord(parseChord(name));
    return { name, frets: voicing.frets, bassString: 6 - voicing.bass };
  });
}

function formatVoicing(config) {
  const shape = config.frets.map((f) => (f < 0 ? 'x' : String(f))).join('-');
  const bassIndex = 6 - config.bassString;
  const bassPitch = (OPEN_STRINGS[bassIndex] + config.frets[bassIndex]) % 12;
  return `${config.name.padEnd(6)} ${shape.padEnd(16)} bass: string ${config.bassString} (${PITCH_NAMES[bassPitch]})`;
}

const requested = ['E', 'Am', 'D7', 'G', 'Cmaj7', 'F#m7', 'Bdim', 'Csus4', 'Ebaug'];
for (const config of fret(requested)) {
  console.log(formatVoicing(config));
}

module.exports = { fret, parseChord, formatVoicing };

