function validateVolumes(colors) {
  if (!Array.isArray(colors) || colors.length !== 3) {
    throw new TypeError('mix expects a list of three volumes: [red, yellow, blue]');
  }
  const cleaned = colors.map(function (volume, index) {
    const value = Number(volume);
    if (!Number.isFinite(value) || value < 0) {
      throw new RangeError('volume at index ' + index + ' must be a finite, non-negative number');
    }
    return value;
  });
  return cleaned;
}

function totalVolume(volumes) {
  return volumes.reduce(function (sum, volume) {
    return sum + volume;
  }, 0);
}

function proportions(volumes, total) {
  if (total === 0) {
    return [0, 0, 0];
  }
  return volumes.map(function (volume) {
    return volume / total;
  });
}

function classify(shares) {
  const dominantShare = Math.max.apply(null, shares);
  if (dominantShare === 0) {
    return 'empty';
  }
  const dominantIndex = shares.indexOf(dominantShare);
  if (dominantShare < 0.4) {
    return 'neutral brown';
  }
  if (dominantIndex === 2) {
    return 'cool tone';
  }
  return 'warm tone';
}

function mix(colors) {
  const volumes = validateVolumes(colors);
  const total = totalVolume(volumes);
  const shares = proportions(volumes, total);
  const tone = classify(shares);
  return [total, tone];
}

function describeMix(colors) {
  const result = mix(colors);
  const labels = ['red', 'yellow', 'blue'];
  const parts = colors.map(function (volume, index) {
    return volume + ' ' + labels[index];
  });
  return parts.join(' + ') + ' -> ' + result[0] + ' units, ' + result[1];
}

