const SIDE_LIMIT_SECONDS = 30 * 60;

function validateTracks(tracks) {
  if (!Array.isArray(tracks)) {
    throw new TypeError('tracks must be an array of durations in seconds');
  }
  tracks.forEach(function (duration, index) {
    if (typeof duration !== 'number' || !Number.isFinite(duration) || duration <= 0) {
      throw new RangeError('track ' + (index + 1) + ' is not a positive duration');
    }
    if (duration > SIDE_LIMIT_SECONDS) {
      throw new RangeError('track ' + (index + 1) + ' is longer than one tape side');
    }
  });
  return tracks;
}

function splitSides(tracks) {
  const sideA = [];
  const sideB = [];
  let usedA = 0;
  let usedB = 0;
  tracks.forEach(function (duration) {
    if (sideB.length === 0 && usedA + duration <= SIDE_LIMIT_SECONDS) {
      sideA.push(duration);
      usedA += duration;
      return;
    }
    if (usedB + duration > SIDE_LIMIT_SECONDS) {
      throw new RangeError('the track list does not fit on a single cassette');
    }
    sideB.push(duration);
    usedB += duration;
  });
  return { sideA: sideA, sideB: sideB, usedA: usedA, usedB: usedB };
}

function formatDuration(seconds) {
  const minutes = Math.floor(seconds / 60);
  const rest = Math.round(seconds - minutes * 60);
  return minutes + ':' + String(rest).padStart(2, '0');
}

function record(tracks) {
  validateTracks(tracks);
  const layout = splitSides(tracks);
  return [layout.usedA, layout.usedB];
}

function report(tracks) {
  const layout = splitSides(validateTracks(tracks));
  const sides = [
    { label: 'A', tracks: layout.sideA, used: layout.usedA },
    { label: 'B', tracks: layout.sideB, used: layout.usedB }
  ];
  const lines = [];
  sides.forEach(function (side) {
    const silence = SIDE_LIMIT_SECONDS - side.used;
    lines.push('Side ' + side.label + ' (' + side.tracks.length + ' tracks, ' + formatDuration(side.used) + ')');
    side.tracks.forEach(function (duration, index) {
      lines.push('  ' + (index + 1) + '. ' + formatDuration(duration));
    });
    lines.push('  silence: ' + formatDuration(silence));
  });
  return lines.join('\n');
}

function main() {
  const album = [283, 194, 351, 412, 276, 198, 330, 247, 305, 188, 401, 222];
  const totals = record(album);
  console.log(report(album));
  console.log('Totals: ' + totals.map(formatDuration).join(' / '));
}

main();

