const BASE_CYCLE_MINUTES = {
  cotton: 45,
  delicates: 30,
  synthetic: 40,
  towels: 50,
  wool: 35,
};

const THICK_FABRICS = ["towels", "cotton"];

const SOIL_EXTRA_MINUTES = {
  light: 0,
  normal: 5,
  heavy: 20,
};

function normalize(value, label) {
  if (typeof value !== "string") {
    throw new TypeError(`${label} must be a string`);
  }
  return value.trim().toLowerCase();
}

function baseTime(fabric) {
  const key = normalize(fabric, "fabric");
  const minutes = BASE_CYCLE_MINUTES[key];
  if (minutes === undefined) {
    throw new RangeError(`unknown fabric type: ${fabric}`);
  }
  return minutes;
}

function soilExtra(soil) {
  const key = normalize(soil, "soil level");
  const extra = SOIL_EXTRA_MINUTES[key];
  if (extra === undefined) {
    throw new RangeError(`unknown soil level: ${soil}`);
  }
  return extra;
}

function rinseExtra(temperature) {
  const key = normalize(temperature, "temperature");
  if (key === "cold") {
    return 8;
  }
  if (key !== "warm" && key !== "hot") {
    throw new RangeError(`unknown water temperature: ${temperature}`);
  }
  return 0;
}

function spinExtra(fabric, soil) {
  const thick = THICK_FABRICS.includes(normalize(fabric, "fabric"));
  const dirty = normalize(soil, "soil level") === "heavy";
  return thick && dirty ? 10 : 0;
}

function washTime(load) {
  const { fabric, temperature, soil } = load;
  let total = baseTime(fabric);
  total += soilExtra(soil);
  total += rinseExtra(temperature);
  total += spinExtra(fabric, soil);
  return total;
}

function wash(loads) {
  if (!Array.isArray(loads)) {
    throw new TypeError("loads must be an array");
  }
  return loads.map(washTime);
}

function report(loads) {
  const times = wash(loads);
  const lines = loads.map((load, i) => `${load.fabric}/${load.temperature}/${load.soil}: ${times[i]} min`);
  const total = times.reduce((sum, minutes) => sum + minutes, 0);
  lines.push(`total: ${total} min`);
  return lines.join("\n");
}

const laundry = [
  { fabric: "towels", temperature: "hot", soil: "heavy" },
  { fabric: "delicates", temperature: "cold", soil: "light" },
  { fabric: "synthetic", temperature: "warm", soil: "normal" },
  { fabric: "cotton", temperature: "cold", soil: "heavy" },
];

console.log(report(laundry));

