const FOLD_POINTS = {
  valley: 1,
  mountain: 1,
  book: 1,
  cupboard: 2,
  inside_reverse: 4,
  outside_reverse: 4,
  squash: 5,
  petal: 6,
  rabbit_ear: 3,
  pleat: 3,
  sink: 7,
};

const TIERS = [
  { name: 'beginner', limit: 8 },
  { name: 'intermediate', limit: 20 },
  { name: 'complex', limit: 40 },
  { name: 'advanced', limit: Infinity },
];

function normalize(name) {
  const trimmed = String(name).trim().toLowerCase();
  return trimmed.replace(/[\s-]+/g, '_');
}

function pointsFor(name) {
  const key = normalize(name);
  const value = FOLD_POINTS[key];
  if (value === undefined) {
    throw new Error(`unknown fold type: ${name}`);
  }
  return value;
}

function classify(score) {
  const tier = TIERS.find((t) => score <= t.limit);
  return tier.name;
}

function tally(instructions) {
  const counts = new Map();
  for (const step of instructions) {
    const key = normalize(step);
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  return counts;
}

function fold(instructions) {
  if (!Array.isArray(instructions)) {
    throw new TypeError('instructions must be an array of fold names');
  }
  let score = 0;
  for (const step of instructions) {
    score += pointsFor(step);
  }
  const tier = classify(score);
  return { score, tier, steps: instructions.length, breakdown: tally(instructions) };
}

function report(instructions) {
  const result = fold(instructions);
  const lines = [`steps: ${result.steps}`];
  for (const [name, count] of result.breakdown) {
    lines.push(`  ${name} x${count} = ${count * FOLD_POINTS[name]} pts`);
  }
  lines.push(`total score: ${result.score}`);
  lines.push(`difficulty: ${result.tier}`);
  return lines.join('\n');
}

const crane = ['book', 'book', 'valley', 'mountain', 'petal', 'petal', 'inside reverse', 'valley'];
const boat = ['valley', 'Valley', 'mountain', 'cupboard'];
const dragon = ['book', 'squash', 'squash', 'petal', 'petal', 'sink', 'outside-reverse', 'pleat', 'pleat', 'rabbit ear'];

console.log(report(boat));
console.log('---');
console.log(report(crane));
console.log('---');
console.log(report(dragon));

