const STANDARD_TEMP = 21;
const MIN_MINUTES = 20;
const COLD_FACTOR = 0.15;
const WARM_FACTOR = 0.10;

function validateDough(dough) {
  if (typeof dough.name !== 'string' || dough.name.trim() === '') {
    throw new TypeError('each dough needs a non-empty name');
  }
  const base = Number(dough.baseMinutes);
  const temp = Number(dough.temperature);
  if (!Number.isFinite(base) || base <= 0) {
    throw new RangeError(`invalid base proofing time for ${dough.name}`);
  }
  if (!Number.isFinite(temp)) {
    throw new RangeError(`invalid kitchen temperature for ${dough.name}`);
  }
  return { name: dough.name.trim(), baseMinutes: base, temperature: temp };
}

function adjustmentRatio(temperature) {
  const delta = temperature - STANDARD_TEMP;
  if (delta < 0) {
    return 1 + COLD_FACTOR * -delta;
  }
  return Math.max(0, 1 - WARM_FACTOR * delta);
}

function adjustedMinutes(baseMinutes, temperature) {
  const raw = baseMinutes * adjustmentRatio(temperature);
  const rounded = Math.round(raw);
  return Math.max(MIN_MINUTES, rounded);
}

function proof(doughs) {
  if (!Array.isArray(doughs)) {
    throw new TypeError('proof() expects an array of doughs');
  }
  return doughs.map((entry) => {
    const clean = validateDough(entry);
    return adjustedMinutes(clean.baseMinutes, clean.temperature);
  });
}

function describe(dough, minutes) {
  const clean = validateDough(dough);
  const drift = clean.temperature - STANDARD_TEMP;
  let note = 'at standard temperature';
  if (drift < 0) {
    note = `${Math.abs(drift).toFixed(1)}\u00B0 cold, rising slowed`;
  } else if (drift > 0) {
    note = `${drift.toFixed(1)}\u00B0 warm, rising sped up`;
  }
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  const clock = hours > 0 ? `${hours}h ${rest}m` : `${rest}m`;
  return `${clean.name.padEnd(16)} ${clock.padStart(7)}  (${note})`;
}

function report(doughs) {
  const times = proof(doughs);
  return doughs.map((dough, index) => describe(dough, times[index])).join('\n');
}

const kitchen = [
  { name: 'Ciabatta', baseMinutes: 90, temperature: 18 },
  { name: 'Brioche', baseMinutes: 120, temperature: 21 },
  { name: 'Pizza base', baseMinutes: 60, temperature: 27 },
  { name: 'Sourdough', baseMinutes: 240, temperature: 15 },
  { name: 'Quick rolls', baseMinutes: 30, temperature: 30 },
];

console.log(report(kitchen));
console.log('minutes:', proof(kitchen).join(', '));

