const SAG_TARGETS = {
  'cross country': 0.20,
  'downhill': 0.30,
};

const REFERENCE_SAG = 0.20;

function normalizeStyle(style) {
  if (typeof style !== 'string') {
    throw new TypeError('riding style must be a string');
  }
  const key = style.trim().toLowerCase().replace(/[-_]+/g, ' ');
  if (!Object.prototype.hasOwnProperty.call(SAG_TARGETS, key)) {
    throw new RangeError(`unsupported riding style: ${style}`);
  }
  return key;
}

function validateWeight(weight) {
  if (typeof weight !== 'number' || !Number.isFinite(weight)) {
    throw new TypeError('rider weight must be a finite number');
  }
  if (weight <= 0) {
    throw new RangeError('rider weight must be positive');
  }
  return weight;
}

function baselinePressure(weight) {
  return 2 * validateWeight(weight);
}

function sagTarget(style) {
  return SAG_TARGETS[normalizeStyle(style)];
}

function pressureForRider(weight, style) {
  const baseline = baselinePressure(weight);
  const target = sagTarget(style);
  const scaled = baseline * (REFERENCE_SAG / target);
  return Math.round(scaled * 10) / 10;
}

function sag(riders) {
  if (!Array.isArray(riders)) {
    throw new TypeError('riders must be a list');
  }
  return riders.map((rider) => {
    const { weight, style } = Array.isArray(rider)
      ? { weight: rider[0], style: rider[1] }
      : rider;
    return pressureForRider(weight, style);
  });
}

function report(riders, pressures) {
  const lines = riders.map((rider, index) => {
    const weight = Array.isArray(rider) ? rider[0] : rider.weight;
    const style = Array.isArray(rider) ? rider[1] : rider.style;
    const percent = (sagTarget(style) * 100).toFixed(0);
    return `${weight} kg / ${style}: ${pressures[index]} psi for ${percent}% sag`;
  });
  return lines.join('\n');
}

