  const riders = [
    [70, 'cross country'],
    [82, 'downhill'],
    { weight: 95, style: 'Cross-Country' },
    { weight: 60, style: 'DOWNHILL' },
  ];
  const pressures = sag(riders);
  console.log(report(riders, pressures));
  console.log(`recommended pressures: ${pressures.join(', ')}`);
}

main();

