const WAX_BLUE = 'blue';
const WAX_VIOLET = 'violet';
const WAX_YELLOW = 'yellow';
const HUMIDITY_FLUOR_THRESHOLD = 80;

function validateCondition(condition, index) {
  if (condition === null || typeof condition !== 'object') {
    throw new TypeError(`condition at index ${index} must be an object`);
  }
  const temperature = Number(condition.temperature);
  const humidity = Number(condition.humidity);
  if (!Number.isFinite(temperature)) {
    throw new TypeError(`condition at index ${index} has a non-numeric temperature`);
  }
  if (!Number.isFinite(humidity)) {
    throw new TypeError(`condition at index ${index} has a non-numeric humidity`);
  }
  if (humidity < 0 || humidity > 100) {
    throw new RangeError(`humidity at index ${index} must be a percentage between 0 and 100`);
  }
  return { temperature, humidity };
}

function pickColor(temperature) {
  if (temperature <= -8) {
    return WAX_BLUE;
  }
  if (temperature < 1) {
    return WAX_VIOLET;
  }
  return WAX_YELLOW;
}

function wax(conditions) {
  if (!Array.isArray(conditions)) {
    throw new TypeError('conditions must be an array of daily weather readings');
  }
  return conditions.map((condition, index) => {
    const { temperature, humidity } = validateCondition(condition, index);
    const color = pickColor(temperature);
    const fluorinated = humidity > HUMIDITY_FLUOR_THRESHOLD;
    return { color, fluorinated };
  });
}

function formatRecommendation(condition, recommendation, index) {
  const day = `Day ${index + 1}`;
  const reading = `${condition.temperature.toFixed(1)}\u00b0C / ${condition.humidity}% RH`;
  const additive = recommendation.fluorinated ? ' + fluoro additive' : '';
  return `${day}: ${reading} -> ${recommendation.color} wax${additive}`;
}

function report(conditions) {
  const recommendations = wax(conditions);
  const lines = recommendations.map((recommendation, index) =>
    formatRecommendation(conditions[index], recommendation, index));
  return lines.join('\n');
}

function main() {
  const week = [
    { temperature: -15, humidity: 45 },
    { temperature: -8, humidity: 88 },
    { temperature: -3.5, humidity: 62 },
    { temperature: 0, humidity: 91 },
    { temperature: 4.5, humidity: 78 },
    { temperature: 7, humidity: 95 },
  ];
  console.log(report(week));
}

main();

module.exports = { wax, report, formatRecommendation };

