const ISO = 100;
const CALIBRATION = 12.5;
const APERTURES = [1.4, 2, 2.8, 4, 5.6, 8, 11, 16, 22];
const SHUTTER_DENOMINATORS = [1, 2, 4, 8, 15, 30, 60, 125, 250, 500, 1000, 2000, 4000];
const FAST_SHUTTER_EV = 13;
const WIDE_APERTURE_EV = 8;
const MATCH_TOLERANCE = 0.5;

function validateScenes(scenes) {
  if (!Array.isArray(scenes)) {
    throw new TypeError("scenes must be an array of brightness values");
  }
  return scenes.map((brightness, index) => {
    const value = Number(brightness);
    if (!Number.isFinite(value) || value <= 0) {
      throw new RangeError(`scene ${index} has invalid brightness: ${brightness}`);
    }
    return value;
  });
}

function exposureValue(brightness) {
  return Math.log2((brightness * ISO) / CALIBRATION);
}

function candidatePairs(ev) {
  const pairs = [];
  for (const aperture of APERTURES) {
    for (const denominator of SHUTTER_DENOMINATORS) {
      const error = Math.abs(Math.log2(aperture * aperture * denominator) - ev);
      pairs.push({ aperture, denominator, error });
    }
  }
  pairs.sort((a, b) => a.error - b.error);
  const usable = pairs.filter((pair) => pair.error <= MATCH_TOLERANCE);
  return usable.length > 0 ? usable : pairs.slice(0, 1);
}

function chooseSettings(ev) {
  const pairs = candidatePairs(ev);
  if (ev >= FAST_SHUTTER_EV) {
    pairs.sort((a, b) => b.denominator - a.denominator);
  } else if (ev <= WIDE_APERTURE_EV) {
    pairs.sort((a, b) => a.aperture - b.aperture);
  } else {
    pairs.sort((a, b) => Math.abs(a.aperture - 5.6) - Math.abs(b.aperture - 5.6));
  }
  return pairs[0];
}

function formatShutter(denominator) {
  return denominator === 1 ? "1s" : `1/${denominator}`;
}

function expose(scenes) {
  const brightnesses = validateScenes(scenes);
  return brightnesses.map((brightness) => {
    const ev = exposureValue(brightness);
    const choice = chooseSettings(ev);
    return { shutter: formatShutter(choice.denominator), aperture: choice.aperture };
  });
}

function report(scenes) {
  const settings = expose(scenes);
  return settings
    .map((setting, index) => `${scenes[index]} cd/m2 -> ${setting.shutter} at f/${setting.aperture}`)
    .join("\n");
}

const sampleScenes = [8000, 5000, 1200, 250, 40, 6];
console.log(report(sampleScenes));
console.log(expose(sampleScenes));

