function normalizeComponents(components) {
  if (!Array.isArray(components) || components.length === 0) {
    throw new Error('carry: expected a non-empty list of tent components');
  }
  return components.map((part, index) => {
    const name = typeof part.name === 'string' ? part.name : `part-${index}`;
    const weight = Number(part.weight);
    if (!Number.isFinite(weight) || weight < 0) {
      throw new Error(`carry: component "${name}" has an invalid weight`);
    }
    return { name, weight };
  });
}

function normalizeCapacities(capacities) {
  if (!Array.isArray(capacities) || capacities.length === 0) {
    throw new Error('carry: expected a non-empty list of backpack capacities');
  }
  return capacities.map((capacity, index) => {
    const limit = Number(capacity);
    if (!Number.isFinite(limit) || limit <= 0) {
      throw new Error(`carry: hiker ${index + 1} has an invalid capacity`);
    }
    return limit;
  });
}

function carry(components, capacities) {
  const parts = normalizeComponents(components);
  const limits = normalizeCapacities(capacities);
  parts.sort((a, b) => b.weight - a.weight);
  const packs = limits.map((limit, hiker) => ({ hiker, limit, load: 0, items: [] }));
  for (const part of parts) {
    const eligible = packs.filter((pack) => pack.load + part.weight <= pack.limit);
    if (eligible.length === 0) {
      throw new Error(`carry: no hiker can still take "${part.name}" (${part.weight})`);
    }
    let chosen = eligible[0];
    for (const pack of eligible) {
      const roomier = pack.limit - pack.load > chosen.limit - chosen.load;
      if (roomier) {
        chosen = pack;
      }
    }
    chosen.load += part.weight;
    chosen.items.push(part.name);
  }
  return packs.map((pack) => pack.load);
}

function report(components, capacities) {
  const loads = carry(components, capacities);
  const total = loads.reduce((sum, load) => sum + load, 0);
  const heaviest = Math.max(...loads);
  const lightest = Math.min(...loads);
  const lines = loads.map((load, index) => `  hiker ${index + 1}: ${load.toFixed(1)} kg`);
  lines.push(`  total: ${total.toFixed(1)} kg, spread: ${(heaviest - lightest).toFixed(1)} kg`);
  return lines.join('\n');
}

const tent = [
  { name: 'pole set', weight: 2.4 },
  { name: 'fabric body', weight: 3.1 },
  { name: 'rainfly', weight: 1.6 },
  { name: 'footprint', weight: 0.9 },
  { name: 'stakes', weight: 0.6 },
  { name: 'guylines', weight: 0.3 },
];
const backpacks = [6, 5, 4];
console.log('Tent distribution among 3 hikers:');
console.log(report(tent, backpacks));

module.exports = { carry, report };

