function addTask(schedule, taskName, startTime) {
    const todayKey = 'today';

    if (!schedule[todayKey]) {
        schedule[todayKey] = [];
    }

    const newTask = {
        name: taskName,
        time: startTime
    };

    schedule[todayKey].push(newTask);

    // Optional: Sort tasks by time for better organization.
    schedule[todayKey].sort((a, b) => {
        const timeA = a.time;
        const timeB = b.time;
        if (timeA < timeB) return -1;
        if (timeA > timeB) return 1;
        return 0;
    });

    return schedule;
}

