function startsWith(str, prefix) {
  if (typeof str !== 'string' || typeof prefix !== 'string') {
    return false;
  }

  if (prefix.length > str.length) {
    return false;
  }

  for (let i = 0; i < prefix.length; i++) {
    if (str[i] !== prefix[i]) {
      return false;
    }
  }

  return true;
}

