    if (!(key in groups)) {
      groups[key] = []
    }
    groups[key].push(item)
  }
  return Object.assign({}, groups)
}

function groupSizes(groups) {
  const sizes = {}
  for (const key of Object.keys(groups)) {
    sizes[key] = groups[key].length
  }
  return sizes
}

function largestGroup(groups) {
  let bestKey = null
  let bestCount = -1
  for (const [key, members] of Object.entries(groups)) {
    if (members.length > bestCount) {
      bestKey = key
      bestCount = members.length
    }
  }
  return bestKey === null ? null : { key: bestKey, count: bestCount }
}

function formatGroups(groups, labelProp) {
  const lines = []
  for (const key of Object.keys(groups).sort()) {
    const labels = groups[key].map((item) => String(item[labelProp]))
    lines.push(`${key}: ${labels.join(', ')}`)
  }
  return lines.join('\n')
}

function report(arr, prop, labelProp) {
  const groups = groupByProperty(arr, prop)
  const biggest = largestGroup(groups)
  const parts = [formatGroups(groups, labelProp)]
  parts.push(`sizes: ${JSON.stringify(groupSizes(groups))}`)
  if (biggest !== null) {
    parts.push(`largest: ${biggest.key} (${biggest.count})`)
  }
  return parts.join('\n')
}

function main() {
  const records = [
    { id: 1, type: 'A' },
    { id: 2, type: 'B' },
    { id: 3, type: 'A' },
    { id: 4, type: 'C' },
    { id: 5, type: 'B' },
  ]
  console.log(JSON.stringify(groupByProperty(records, 'type')))
  console.log(report(records, 'type', 'id'))
  try {
    groupByProperty(records, '')
  } catch (err) {
    console.log(`error: ${err.message}`)
  }
}

