function generateAcronym(phrase) {
  let words = phrase.split(/[\s-]+/);
  let acronym = '';
  for (let i = 0; i < words.length; i++) {
    let word = words[i];
    let firstLetter = '';
    for (let j = 0; j < word.length; j++) {
      let char = word[j];
      if (/[a-zA-Z]/.test(char)) {
        firstLetter = char;
        break;
      }
    }
    if (firstLetter) {
      acronym += firstLetter.toUpperCase();
    }
  }
  return acronym;
}

