function isPowerOfTwo(n) {
  if (!Number.isInteger(n)) {
    return false;
  }
  if (n <= 0) {
    return false;
  }
  let value = n;
  while (value % 2 === 0) {
    value = value / 2;
  }
  return value === 1;
}

function exponentOfTwo(n) {
  if (!isPowerOfTwo(n)) {
    return null;
  }
  let exponent = 0;
  let value = n;
  while (value > 1) {
    value = value / 2;
    exponent += 1;
  }
  return exponent;
}

function parseCandidate(text) {
  const trimmed = String(text).trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    throw new Error(`not an integer: "${text}"`);
  }
  const value = Number(trimmed);
  if (!Number.isSafeInteger(value)) {
    throw new Error(`out of safe integer range: "${text}"`);
  }
  return value;
}

function describe(n) {
  if (!isPowerOfTwo(n)) {
    return `${n} -> false`;
  }
  return `${n} -> true (2^${exponentOfTwo(n)})`;
}

function report(inputs) {
  const lines = [];
  for (const raw of inputs) {
    try {
      lines.push(describe(parseCandidate(raw)));
    } catch (error) {
      lines.push(`${raw} -> error: ${error.message}`);
    }
  }
  return lines.join("\n");
}

function main() {
  const samples = ["1", "3", "0", "-8", "64", "1024", "1073741824", "12884901888", "4503599627370496", "two"];
  console.log(report(samples));
}

main();

module.exports = { isPowerOfTwo, exponentOfTwo, parseCandidate, describe, report };

