function hammingDistance(x, y) {
  let xorResult = x ^ y;
  let distance = 0;

  while (xorResult > 0) {
    if ((xorResult & 1) === 1) {
      distance++;
    };
    xorResult >>= 1;
  };

  return distance;
};

