function findAllDivisors(n) {
  let divisors = [];
  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) {
      divisors.push(i);
      if (i * i !== n) {
        divisors.push(n / i);
      }
    }
  }
  divisors.sort((a, b) => a - b);
  return divisors;
