const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
const CODE_LENGTH = 6;
const store = new Map();

function normalizeUrl(longUrl) {
  if (typeof longUrl !== 'string') {
    throw new TypeError('long URL must be a string');
  }
  const trimmed = longUrl.trim();
  if (trimmed === '') {
    throw new Error('long URL must not be empty');
  }
  if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(trimmed)) {
    throw new Error(`long URL is missing a scheme: ${trimmed}`);
  }
  return trimmed;
}

function hashUrl(url) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < url.length; i += 1) {
    hash ^= url.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash;
}

function encodeBase62(value, length) {
  let remaining = value;
  let code = '';
  while (code.length < length) {
    code = ALPHABET[remaining % ALPHABET.length] + code;
    remaining = Math.floor(remaining / ALPHABET.length);
  }
  return code;
}

function shortenUrl(longUrl) {
  const url = normalizeUrl(longUrl);
  const seed = hashUrl(url);
  const mixed = (seed ^ Math.imul(url.length, 0x9e3779b1)) >>> 0;
  const code = encodeBase62(mixed, CODE_LENGTH);
  store.set(code, url);
  return code;
}

function expandUrl(code) {
  const url = store.get(code);
  if (url === undefined) {
    throw new Error(`unknown short code: ${code}`);
  }
  return url;
}

function formatMapping(code) {
  const target = expandUrl(code);
  const label = target.length > 40 ? `${target.slice(0, 37)}...` : target;
  return `${code}  ->  ${label}`;
}

function main() {
  const inputs = [
    'https://example.com/very/long/url',
    'https://another.site/',
    'http://localhost:8080/docs/index.html?section=intro',
    'not-a-url',
  ];
  for (const input of inputs) {
    try {
      const code = shortenUrl(input);
      console.log(formatMapping(code));
    } catch (err) {
      console.log(`skipped: ${err.message}`);
    }
  }
}

main();

module.exports = { shortenUrl, expandUrl, formatMapping };

