function simulateCoinTosses(numTosses) {
  let heads = 0;
  let tails = 0;

  for (let i = 0; i < numTosses; i++) {
    const tossResult = Math.random();
    if (tossResult < 0.5) {
      heads++;
    } else {
      tails++;
    }
  }

  return { heads: heads, tails: tails };
