function checkStock(inventory, itemName, requestedQuantity) {
  if (inventory === null || typeof inventory !== 'object') {
    throw new TypeError('inventory must be an object');
  }
  if (typeof itemName !== 'string' || itemName.length === 0) {
    throw new TypeError('itemName must be a non-empty string');
  }
  const quantity = Number(requestedQuantity);
  if (!Number.isInteger(quantity) || quantity < 0) {
    throw new RangeError('requestedQuantity must be a non-negative integer');
  }
  if (!Object.prototype.hasOwnProperty.call(inventory, itemName)) {
    return false;
  }
  const available = inventory[itemName];
  if (typeof available !== 'number' || Number.isNaN(available)) {
    return false;
  }
  return available >= quantity;
}

function fulfillOrder(inventory, itemName, requestedQuantity) {
  if (!checkStock(inventory, itemName, requestedQuantity)) {
    return false;
  }
  inventory[itemName] -= requestedQuantity;
  return true;
}

function restock(inventory, itemName, amount) {
  if (!Number.isInteger(amount) || amount <= 0) {
    throw new RangeError('amount must be a positive integer');
  }
  const current = Object.prototype.hasOwnProperty.call(inventory, itemName) ? inventory[itemName] : 0;
  inventory[itemName] = current + amount;
  return inventory[itemName];
}

function lowStockItems(inventory, threshold) {
  const names = Object.keys(inventory);
  const low = names.filter((name) => !checkStock(inventory, name, threshold));
  return low.sort();
}

function formatReport(inventory) {
  const lines = Object.keys(inventory).sort().map((name) => `${name}: ${inventory[name]}`);
  return lines.join('\n');
}

function main() {
  const inventory = { apple: 10, banana: 5 };
  console.log(checkStock(inventory, 'apple', 7));
  console.log(checkStock(inventory, 'orange', 1));
  const orders = [['apple', 7], ['banana', 6], ['orange', 1]];
  for (const [itemName, quantity] of orders) {
    const shipped = fulfillOrder(inventory, itemName, quantity);
    const verdict = shipped ? 'shipped' : 'rejected';
    console.log(`order ${quantity} x ${itemName} -> ${verdict}`);
  }
  restock(inventory, 'orange', 12);
  restock(inventory, 'apple', 4);
  console.log(formatReport(inventory));
  console.log(`low stock (< 6): ${lowStockItems(inventory, 6).join(', ')}`);
}

main();

module.exports = { checkStock, fulfillOrder, restock, lowStockItems, formatReport };

