const FEET_PER_METER = 3.28084;

function metersToFeet(meters) {
  const value = Number(meters);
  if (!Number.isFinite(value)) {
    throw new TypeError(`metersToFeet expects a finite number, received: ${meters}`);
  }
  return value * FEET_PER_METER;
}

function feetToMeters(feet) {
  const value = Number(feet);
  if (!Number.isFinite(value)) {
    throw new TypeError(`feetToMeters expects a finite number, received: ${feet}`);
  }
  return value / FEET_PER_METER;
}

function roundTo(value, decimals) {
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function feetAndInches(meters) {
  const totalFeet = metersToFeet(meters);
  const sign = totalFeet < 0 ? -1 : 1;
  const absolute = Math.abs(totalFeet);
  let wholeFeet = Math.floor(absolute);
  let inches = roundTo((absolute - wholeFeet) * 12, 1);
  if (inches >= 12) {
    wholeFeet += 1;
    inches = 0;
  }
  return { feet: sign * wholeFeet, inches };
}

function formatConversion(meters) {
  const feet = metersToFeet(meters);
  const parts = feetAndInches(meters);
  const compact = `${parts.feet} ft ${parts.inches} in`;
  return `${meters} m = ${roundTo(feet, 5)} ft (${compact})`;
}

function conversionTable(values) {
  if (!Array.isArray(values)) {
    throw new TypeError('conversionTable expects an array of metre values');
  }
  return values.map(formatConversion);
}

function main() {
  const samples = [1, 10, 0.5, 42, 100];
  const report = conversionTable(samples);
  for (const line of report) {
    console.log(line);
  }
  const marathon = 42195;
  console.log(`A marathon is ${roundTo(metersToFeet(marathon), 2)} feet long.`);
  const oneMile = 5280;
  console.log(`One mile is ${roundTo(feetToMeters(oneMile), 3)} metres.`);
}

main();

module.exports = {
  metersToFeet,
  feetToMeters,
  feetAndInches,
  formatConversion,
  conversionTable,
};

