const calculateRange = (numbers) => {
  if (numbers.length === 0) {
    return 0;
  }

  let minVal = numbers[0];
  let maxVal = numbers[0];

  for (let i = 1; i < numbers.length; i++) {
    const currentNum = numbers[i];
    if (currentNum < minVal) {
      minVal = currentNum;
    }
    if (currentNum > maxVal) {
      maxVal = currentNum;
    }
  }

  return maxVal - minVal;
};

