'use strict';

function assertValidInput(str, maxLength) {
  if (typeof str !== 'string') {
    throw new TypeError('truncateString: expected a string as first argument');
  }
  if (!Number.isInteger(maxLength) || maxLength < 0) {
    throw new RangeError('truncateString: maxLength must be a non-negative integer');
  }
}

function trimTrailingSpace(text) {
  return text.replace(/\s+$/, '');
}

function truncateString(str, maxLength) {
  assertValidInput(str, maxLength);
  if (str.length <= maxLength) {
    return str;
  }
  const window = str.slice(0, maxLength);
  const lastSpace = window.lastIndexOf(' ');
  const body = lastSpace > 0 ? window.slice(0, lastSpace) : window;
  return trimTrailingSpace(body) + '...';
}

function truncateAll(items, maxLength) {
  return items.map(function (item) {
    return truncateString(item, maxLength);
  });
}

function padRight(text, width) {
  const missing = width - text.length;
  if (missing <= 0) {
    return text;
  }
  return text + ' '.repeat(missing);
}

function buildReport(items, maxLength) {
  const truncated = truncateAll(items, maxLength);
  const widest = items.reduce(function (best, item) {
    return Math.max(best, item.length);
  }, 0);
  const lines = [];
  for (let i = 0; i < items.length; i += 1) {
    const original = padRight(items[i], widest);
    const marker = truncated[i] === items[i] ? 'kept' : 'cut';
    lines.push(original + ' | ' + padRight(truncated[i], maxLength + 3) + ' | ' + marker);
  }
  return lines.join('\n');
}

function main() {
  console.log(truncateString('hello world', 7));
  console.log(truncateString('short', 10));
  const headlines = [
    'Local library extends opening hours',
    'Bridge repairs finished',
    'Rain expected all weekend',
    'Census data released today'
  ];
  console.log(buildReport(headlines, 18));
}

main();

module.exports = { truncateString, truncateAll, buildReport };

