  if (typeof rate !== "number" || Number.isNaN(rate) || rate < 0) {
    throw new RangeError("rate must be a non-negative number")
  }
  if (typeof years !== "number" || Number.isNaN(years) || years < 0) {
    throw new RangeError("years must be a non-negative number")
  }
  return principal * Math.pow(1 + rate / n, n * years)
}

function interestEarned(principal, rate, n, years) {
  const final = calculateCompoundInterest(principal, rate, n, years)
  return final - principal
}

function effectiveAnnualRate(rate, n) {
  validatePositive("compounding frequency", n)
  return Math.pow(1 + rate / n, n) - 1
}

function yearlySchedule(principal, rate, n, years) {
  const rows = []
  for (let year = 1; year <= years; year += 1) {
    const balance = calculateCompoundInterest(principal, rate, n, year)
    rows.push({ year: year, balance: balance, earned: balance - principal })
  }
  return rows
}

function formatMoney(amount) {
  const rounded = Math.round(amount * 100) / 100
  return "$" + rounded.toFixed(2)
}

function formatPercent(fraction) {
  return (fraction * 100).toFixed(3) + "%"
}

function report(principal, rate, n, years) {
  const lines = []
  const header = formatMoney(principal) + " at " + formatPercent(rate) +
    " compounded " + n + " time(s) per year for " + years + " year(s)"
  lines.push(header)
  lines.push("  effective annual rate: " + formatPercent(effectiveAnnualRate(rate, n)))
  for (const row of yearlySchedule(principal, rate, n, years)) {
    lines.push("  year " + row.year + ": " + formatMoney(row.balance) +
      " (interest " + formatMoney(row.earned) + ")")
  }
  lines.push("  exact final amount: " + calculateCompoundInterest(principal, rate, n, years))
  return lines.join("\n")
}

function main() {
  console.log(report(1000, 0.05, 12, 1))
  console.log(report(5000, 0.04, 4, 3))
  console.log("interest on $2500 over 10 years: " +
    formatMoney(interestEarned(2500, 0.07, 1, 10)))
}

main()

module.exports = {
  calculateCompoundInterest: calculateCompoundInterest,
  interestEarned: interestEarned,
  effectiveAnnualRate: effectiveAnnualRate,
  yearlySchedule: yearlySchedule,
  report: report,
}

