function toTitleCase(str) {
  if (!str) {
    return "";
  };
  const words = str.toLowerCase().split(" ");
  let result = [];
  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word.length > 0) {
      result.push(word.charAt(0).toUpperCase() + word.slice(1));
    } else {
      result.push("");
    };
  };
  return result.join(" ");
};

