function polygonArea(points) {
  let area = 0
  const n = points.length

  for (let i = 0; i < n; i++) {
    const p1 = points[i]
    const p2 = points[(i + 1) % n]
    area += (p1.x * p2.y) - (p1.y * p2.x)
  }

  return Math.abs(area) / 2
}

// Example usage:
const triangle = [{x: 0, y: 0}, {x: 1, y: 0}, {x: 0, y: 1}]
const area1 = polygonArea(triangle)
// console.log(area1); // Expected: 0.5

const square = [{x: 0, y: 0}, {x: 2, y: 0}, {x: 2, y: 2}, {x: 0, y: 2}]
const area2 = polygonArea(square)
// console.log(area2); // Expected: 4

const anotherPoly = [{x: 0, y: 0}, {x: 3, y: 0}, {x: 2, y: 3}, {x: 1, y: 2}]
const area3 = polygonArea(anotherPoly)
// console.log(area3); // Expected: 5.5

